/* 平成15年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h15.committeeSessions.push(...[{"id":"h15-20030826-8","meetingId":"h15-cm08","date":"2003年8月26日","dateIso":"2003-08-26","committee":"建設委員会","time":"午後１時０５分～午後５時００分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１の広町原っぱ公園の廃止および跡地の駐車場化計画","agenda":"１の広町原っぱ公園の廃止および跡地の駐車場化計画","exchanges":[{"speaker":"原委員","kind":"質問","question":"例えば立体化ができるような駐車場にするのか、平面だけなのか、それによって台数が相当変わってくると思うんです。今伺いましたが、アトレ大井町店も使うし、丸井大井町店も使うし、阪急大井食品館も使って、なおかつ周辺の商店街も利用して、さらに一般の車両も使い、そしてレッカー移動をされてきたものをそこに入れるということだと、相当な台数を予定していないとならないのかなと思うんですが。","respondent":"岩田管理工事課長","answer":"ただ、位置が位置でございまして、幹線道路から全然見えないところの駐車場ですので、看板等を立てるにしろ、ある程度ここの駐車場が認知されるまでの間は経営上は厳しい状態だろうという話を聞いておりますので、利用状況に応じて、パンクするような状態でも困りますので。","voiceIndex":5,"id":"exchange-001"},{"speaker":"原委員","kind":"質問","question":"要するに、運営主体に貸す、あるいはそれをどういうふうに使っていくかというのはどういうふうに考えていらっしゃるんですか。","respondent":"岩田管理工事課長","answer":"区としましては、特定の団体に対して公園を貸し付けて利用させるというのは例外中の例外ですので、先ほど私が説明しましたように、公共的な要素が極めて高いものですし、区の方針にも沿った使い方でもありますので、この四店舗だけではなくて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"それから２００台というのがちょっとひっかかってくるんだけれども、行政として今回こういう異例な形をとって、なおかつ大井町駅近辺の交通の状況をよくしようとするわけですから、果たして２００台で妥当なのかどうなのかという試算があるのではないかと思うんですけれども、その辺はどうなんでしょうか。","respondent":"岩田管理工事課長","answer":"将来的に大井町駅周辺、２５０台なり３００台の範囲内の駐車場の将来予想というのは特にやったわけでございませんけれども、十五、六年前ですか、当時、都市整備本部という組織が品川区にございまして、こちらのところで当時計画したものがありますけれども。","voiceIndex":9,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問・要望","question":"２点ばかり聞きたいんですけれども、先ほど課長からの説明で、地元からの希望があったと。今、原委員に対してご答弁された、大型四店舗からの要望書のことを指しておられるのかどうか。実際にサンピア通り商店街からも要望としてあったのかどうか、ちょっとその辺をお聞きしたいんです。","respondent":"岩田管理工事課長","answer":"ですから、そういった交通安全対策をきちっととるようにいたしましょう。先ほどのご質問の中で、実際７,５００m2あるところで、駐車場としてお貸しするのは７,０００m2の予定です。この差の５００m2程度というのは、公園の道路に面した部分に歩道として確保していこう。","voiceIndex":11,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問・要望","question":"要望書の話なり、地元のサンピア通りの商店街からも口頭でのそういう話はたびたび出てきたということですけれども、実質的に今の状況で見ると、結局はイトーヨーカドーと阪急のための駐車場になってしまうのかなというような、もちろん日曜日のイトーヨーカドー前の状況を見れば、確かに拡大をしていく必要性というのはあるんでしょうけれども、実質的なイトーヨーカドーですとか。","respondent":"岩田管理工事課長","answer":"最初のご質問の、大規模店と、小規模な路線型商店街と区別して考えるということは区としてはしておりません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"本多委員","kind":"確認","question":"ましてや、イトーヨーカドーが新しくなっても渋滞が続く。差の５００m2ですが、道路と公園ということで、公園用地として、取得から８年間用途変更が認められないということですが、当然将来のプレイス構想でも影響がないように、そういったことですが、取得から８年で用途変更できる、前は１０年だったのかなと思いますが、将来のプレイス構想に影響がないということで、そこだけ１点確認をしたい。","respondent":"岩田管理工事課長","answer":"途中で期間の変更がありまして、８年に、６カ月間短縮になっております。平成４年３月に売買契約をしておりますので、それの８年後というのは昨年の３月末をもって既に切れておりますので、契約上は公園を廃止しても何ら問題はない。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"あそこは車線幅はそんなに広くないと思うんですけれども、ここの渋滞が相当危惧されるのではないかと思いますけれども、その辺はどうなんでしょうか。","respondent":"岩田管理工事課長","answer":"この駐車場を主に利用されるのは土曜、日曜、祭日、いわゆるマイカーで大井町に買い物に来られる方が、土曜、日曜は混むと思いますので、そういうときは、逆に一般交通が減っているですので、そこら辺は状況を見ながら、警察と信号の青と赤の時間の調整とか。","voiceIndex":17,"id":"exchange-007"},{"speaker":"菊地委員","kind":"質問","question":"最初にＪＲから買い付けたときの話ですけれども、区としては乱開発は好ましくないとかということで、公園として買い付けたんですけれども、そのときの補助金という形で、国、都から出ている用地ですか。ちょっとそこだけお聞きしたいと思います。","respondent":"岩田管理工事課長、中谷まちづくり事業部長","answer":"今手持ちに当時の財源の内訳の資料がございませんので、お答えできないのは申し訳ないんですが、売買金額は、当時１５７億円で買収をしております。言ってみれば、一般財源ですけれども、用地の手当てについては当時あったということで記憶しています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"藤田委員","kind":"質問","question":"公園を廃止して駐車場にするということで、区初まって以来の今回の計画だと思うんです。四つの事業者に貸し付けるということですけれども、区の今後の貸し付けた後の責務といいますか、例えば何かあった場合の指導とか、どの辺まで責務があるのか。すべてこれは四つの事業者に貸し付けたんだから、そちらで話し合いをしてくださいというようなケースになるのか、その辺をちょっとお伺いしたいと思います。","respondent":"岩田管理工事課長","answer":"貸し付けるだけですので、経営内容については口はあまり出せないと思いますけれども、駐車場が経営されることによって、周辺にいろいろ問題が起きた場合には、貸している品川区としても責任があるわけですので。","voiceIndex":23,"id":"exchange-009"},{"speaker":"藤田委員","kind":"質問・要望","question":"その辺は区民の声もいろいろ出てくると思うんです。ぜひ汲み取っていただきたいと思います。私たちが一番目につくのは、大井町周辺では自転車の駐輪対策、区役所通りにつきましても、細い歩道にオートバイが何台も置いてあるんです。今回の駐車場に対してオートバイというのは考えなかったのかどうか。オートバイは検討しなかったのかということをお伺いしたいと思います。","respondent":"岩田管理工事課長","answer":"うちのほうでは、今のところ四輪の自動車で検討をしておりましたので、二輪車については特に対象としてはおりませんでした。","voiceIndex":25,"id":"exchange-010"},{"speaker":"藤田委員","kind":"質問・要望","question":"ぜひそれはお願いしていただきたい。先ほど言いましたように、区はどこまで口が出せるのかということを、聞きたかったんです。そこに車が出てくるケースもありますので、もう少し見やすいような構造にするとか、この辺をひとつ検討をしていただきたいなと思うんですけれども、いかがでしょうか。","respondent":"岩田管理工事課長","answer":"ですから、現在は工事用のためのガードマンが張り付いておりますけれども、あの工事が終わるまでは、若干の交通安全施設はつくれると思うんですけれども、根本的に歩道と車道をきちっと分離をして、安全な道路に将来的にはせざるを得ないと考えています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"三つあるんですけれども、一つ目は、原っぱ公園をりんかい線工事の工事ヤードと決めたときに、その話し合いの場がよくわからないんですが、そのときにはこの原っぱ公園をその工事が終わった後はどうするんだというようなことは出されていたんでしょうか。","respondent":"岩田管理工事課長","answer":"現況復旧と言いまして、工事が終われば、前の公園のように戻しますという説明を、鉄建公団が地元の皆さんに工事説明会ではそういう説明をしているんだろうと思います。","voiceIndex":29,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"ということは、これが変更になるということを決定される前に地元の方たちに説明がされるのが当然だと思うんですけれども、そういった手だてはどのようにされていたんでしょうか。","respondent":"岩田管理工事課長","answer":"今日議会でご説明しましたのは、近々に現地に立て看板を立てまして、９月いっぱいをもって公園を廃止しますというお知らせを出しまして、ご意見、ご要望があれば、区役所のほうにご連絡くださいという内容で看板を立てる予定にしております。","voiceIndex":31,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問・要望","question":"もう一つ、大井町周辺はオートバイの駐輪場がないというのを、利用者の方たちにたくさん聞きます。経営上のことにつきましては、問題が発生した時点で、契約時点で何も言えないということではなく、区民のための公共化としてここを使うというのであれば、そういったところを強く主張していただきたいという要望をさせていただきたいと思います。","respondent":"岩田管理工事課長","answer":"従業員の車ではないかと思うんですが、ちょっと来て、買い物をして出て行かれる分にはさほど問題はないんでしょうけれども、どうもそうでない大型バイクが駅へ行く途中に何台かありますので、ああいうのは本来必要のないところに止めておられる方ですので、逆に。","voiceIndex":33,"id":"exchange-014"},{"speaker":"井上委員","kind":"質問・要望","question":"オートバイで駅利用とかではなくて、車と同じ感覚でオートバイの大型は使っているわけですから、駅に行くために大型バイクで行くわけでは決してない方たちが今非常に増えていますので、駅利用だけのバイクという形ではない、車と同じに利用されている方たちということで捉えていただければということで要望しておりますので、その辺が少し考え方が違うかなということはありますけれども、そういったところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望だけですけれども、武蔵小山にしろ、スーパーにしろ、駐車場をつくりますと、そこの商店街が今まで土曜、日曜休みだったのが、日曜日をやり出して、人も結構にぎわいを見せてきて、今おっしゃったように、商店街の活気をみせてくるような状況にもなりかねないと思います。要望だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"}]},{"id":"topic-02","title":"２番目の不動前保管所の新設","agenda":"２番目の不動前保管所の新設","exchanges":[{"speaker":"山村委員","kind":"質問","question":"それが一つ。ですから、「撤去自転車の管理システムを整備し、オンラインで結び」というふうに書いてあるんですから、自転車の番号でどの地域に住んでいる人かというのは分かるわけですから、それで、住んでいる地域を考えて、八潮にするか、不動前の保管所に保管するかというのを考えていただければというのが一つあります。","respondent":"奈良交通安全担当課長","answer":"１点目は、一番最後に書いてある、サービスの向上を図るという点ですけれども、現在は撤去しますのは紙ベースでやっている関係で、区民からの問い合わせに対して迅速に対応できなかった部分があります。","voiceIndex":44,"id":"exchange-017"},{"speaker":"山村委員","kind":"質問","question":"あれは何か、例えば交番とかに届け出ていれば、そのお金を払わなくていいとか、何かしらそういうのがないと、物凄い不愉快じゃないんですけれども、腹立たしい思いをしたことがありますので、そこら辺はできるのかどうかを教えていただければと思います。","respondent":"奈良交通安全担当課長","answer":"今、委員から、自転車の持ち主の住所において保管所を変えたらいいんじゃないかというご指摘ですけれども、私ども自転車を撤去するとき、この自転車の持ち主はどこの方々かというのをほとんど把握できない状態ですので、そういった面での振り分けというのは不可能に近いです。","voiceIndex":46,"id":"exchange-018"},{"speaker":"須貝委員","kind":"意見","question":"３カ月間処分まで保管している、それが妥当性があるのかどうか。逆に、持ち主に通告して、もっと短期間で処分完了できないのかどうか。行政で相当な期間を保管する必要があるのかどうか、その辺のお考えを聞かしていただければと思います。","respondent":"奈良交通安全担当課長","answer":"例えば通常の拾得物の場合には法律上６カ月と１４日間経過しないと処分できないということでございまして、それに比べますと、品川区のほうは概ね３カ月で処分できるということで、大分緩和されたということでございまして、所有権に関することですから。","voiceIndex":48,"id":"exchange-019"},{"speaker":"藤田委員","kind":"質問・要望","question":"もう一つ、要望ですが、管理棟をつくったわけですから、取りに行って、パンクしちゃった、捨てたという場合に、自転車をひきずって行かなければいけないというケースがありますので、管理事務所の職員の中に多少パンクを修理をする人、もしそれがいなければ、ここの自転車屋が近いですよとか、そういうようなサービスを管理人の職員の人に、例えば空気入れ、これも一々ガチャガチャやるんじゃなくて。","respondent":"奈良交通安全担当課長","answer":"そういった面で、平成１５年度から業務委託をして業者が替わっておりますので、部品とか、空気を入れるとか、パンクぐらいの修理ができるような方がいるのかどうか、また確認をしてみたいと思いますけれども、できれば、委員ご指摘のように。","voiceIndex":50,"id":"exchange-020"},{"speaker":"井上委員","kind":"質問","question":"今２,０００台ぐらい壊れたものをということで、普通の道路だと思うんですけれども、丸井の向かいのアトレの無料駐車場のところが線路脇にありますけれども、そこに利用したいと思って入っても、大分前からほこりをかぶって、本当に利用されていないのではないかというような自転車があるばかりに、一時保管をしたいという人たちの利用を妨げていると思うんですけれども、その辺の状況の把握と。","respondent":"中谷まちづくり事業部長","answer":"高架下の部分にあるわけですが、こちらについては、アトレが店舗用のために自ら管理しているものですので、適正に管理するのが自らの努めでございまして、区のほうも、私も担当していた時代、時たま、今委員がおっしゃったように。","voiceIndex":52,"id":"exchange-021"}]},{"id":"topic-03","title":"続きまして、３の平成１５年度駐輪場の整備・有料化","agenda":"続きまして、３の平成１５年度駐輪場の整備・有料化","exchanges":[{"speaker":"山村委員","kind":"質問・要望","question":"収容台数ですけれども、新馬場駅はバイクが定期が１９台、当日が７台、大井競馬場前が定期が１０台で，当日が５台ですけれども、この数というのは、要望があってこういうふうにしているのか、それともこの台数しか立地的にできないからこの台数なのか。バイクというのは、５０ccと考えてよろしいでしょうか。","respondent":"奈良交通安全担当課長","answer":"バイクの台数の件ですけれども、新馬場駅、大井競馬場駅につきましても、現に今利用している台数です。新馬場駅につきましては当日が２６台、大井競馬場駅につきましては、超過しましても１５台ということで、現に利用している台数をここに掲載をしております。","voiceIndex":59,"id":"exchange-022"},{"speaker":"山村委員","kind":"質問","question":"この数を変えるというような話は出ていないんでしょうか。","respondent":"奈良交通安全担当課長","answer":"新馬場駅、大井競馬場駅につきましても、特にバイクの台数を増やしてもらいたいという要望はございませんけれども、大井競馬場駅につきましては、利用されるほとんどの方が八潮団地の方ですので、ほとんどバイクを利用しないで自転車で来れる状態ということで。","voiceIndex":61,"id":"exchange-023"},{"speaker":"菊地委員","kind":"意見","question":"有料化を進める基本的な考え方のところになってしまうかもしれませんけれども、放置自転車は５月の段階でこの程度だと。言ってみれば、今の状況でも、ある意味、放置台数との関係で言えば、今のまま無料で、そのまま管理していくことは十分に可能だと思うんです。そこで先ほどの有料化する基本的な考え方と、わざわざこうやって、この程度の放置自転車との関係をもう一度お答え願えますか。","respondent":"奈良交通安全担当課長、中谷まちづくり事業部長","answer":"平成１３年度から始めておりますけれども、既に有料化を始めている駅との整合性もありますので、新馬場駅だけがこのまま無料の状態というのはいかがなものかなということで、採算の意味も含めまして。駐車場につきましては、先ほどもご説明申し上げたとおり、駐車場の使用料を取るわけです。","voiceIndex":65,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問・要望","question":"今、部長のほうから、受益を受ける方から料金を徴収するというお話でありますので、基本的には新馬場駅にしても、大井競馬場駅にしても、駅利用者がほとんどだと思いますけれども、これもまた、いつもの議論になってしまうかもしれませんけれども、新馬場駅で言えば、京急ですか、土地そのものは提供するということですけれども、実質的には駅を利用して電車を利用するわけですから。","respondent":"中谷まちづくり事業部長","answer":"京急については、残念ながら、用地の提供、あるいは公租公課による提供、あるいは比較的安価な貸借料の提供ということでとどまっておりますが、今後とも私どもも強く働きかけてまいりたいと考えております。","voiceIndex":68,"id":"exchange-025"},{"speaker":"藤田委員","kind":"意見","question":"例えば自転車のデザインをした中にいろいろな使用方法とか、ただ１枚のベニア板でボーンとやるのではなくて、例えば色とか、デザイン、標識、その一つ一つがまち全体をグレードアップしていくものだと私は思うんですけれども、そういう一つ一つにぜひまちづくり事業部として、品川区のまちをグレードアップさせるにはどうしたらいいかという。","respondent":"奈良交通安全担当課長","answer":"今委員ご指摘の、案内板のデザインの関係ですけれども、これについては、委員の意見を参考にしながら、案内板の標識について考えてまいりたいと考えています。","voiceIndex":70,"id":"exchange-026"},{"speaker":"金高副委員長","kind":"質問・要望","question":"工事内容の中に防犯カメラの設置が出ておりますけれども、防犯カメラのテープの保管というか、後の活用方法といいますか、当然、防犯カメラを付けるということは、盗難等も含めて、あるいは利用者の安全確保ということ含めてだと思いますが、その辺の防犯カメラのビデオの、盛んにいろいろと問題になっていると思うんですけれども、そこら辺の取り組みが何かあるのであれば、お聞かせいただきたいと思います。","respondent":"奈良交通安全担当課長、中谷まちづくり事業部長","answer":"防犯カメラにつきましては、各駐輪場に設置はしますけれども、その管理につきましては、区のほうできちんと管理をしてまいりたいと考えています。防犯カメラのテープの保管ですが、これにつきましては、区の指導に基づいて、例えば指導と申しますのは、委託の仕様書ですが、こちらのほうに明記をいたしまして、個人情報の保護等に十分配慮して行うということ。","voiceIndex":72,"id":"exchange-027"}]},{"id":"topic-04","title":"続きまして、次に、４番目の大井町西地区再開発協議会の設立","agenda":"続きまして、次に、４番目の大井町西地区再開発協議会の設立","exchanges":[{"speaker":"原委員","kind":"質問","question":"権利者数が５１名ですね。当日のこの設立総会に来ていただいた方が１１名ですね。加入者が２７名ですね。疑問に思ったのは、この設立総会について、加入者は２７名ということで、少ないなという印象だったんですが、その辺の前もっての告知というか、お知らせというか、そういうところはどうだったんでしょうか。","respondent":"上野都市開発課長","answer":"当日につきまして、周知期間とか含めて、若干事前の準備ということでどうであったかというようなところもあろうかと思いますけれども、基本的には内々に同意いただいている方々からの、当日は行けないけれども、設立についてはいいよというような合意を得られているとか。","voiceIndex":80,"id":"exchange-028"},{"speaker":"原委員","kind":"質問・要望","question":"その辺のところがどうなっているか教えていただきたい。それから、再開発の場合は、全員同意型、西大井などの場合もそうですけれども、大切な要件になっていますから、もっと細かい周知なりをして、合意を求める姿勢が大切だと思うんですが、その辺のところの考え方を聞かせていただきたいと思います。","respondent":"上野都市開発課長","answer":"今後、特に自治会を定期的に開いていきまして、この進め方につきましては、詰めていく予定ですけれども、目処といたしましては、お隣の補助１６３号線の整備と一体的に事業を合わせて完了させていくというのが一つの大きな目標となっておりますので、そういう面では。","voiceIndex":82,"id":"exchange-029"},{"speaker":"原委員","kind":"意見","question":"できるだけというか、なるべく周知徹底をしっかりしたものをお願いいたします。今までですと、なかなか道路をはさんで開発はできないという、非常に厳しい状況の中でやらなければならないということがあって、あまり例がなかったんですけれども、その辺のところの決意というか、考え方というか、今後の中で進めなければならないという、そういう面があるのではないかなと思います。","respondent":"上野都市開発課長","answer":"道路をはさんでおりますけれども、従来、一本橋通りをはさんでいるという形で、通常は非常に大きな広幅員の道路をはさんだ形で両側でやっていくという再開発、まちづくりに比べますと、補助１６３号線が残地で残っている権利者の方は。","voiceIndex":84,"id":"exchange-030"},{"speaker":"原委員","kind":"質問・要望","question":"せっかく建設委員会で、こういう設立がなされたという報告ですので、今後の方針というか、動きは、大まかな形で結構ですから、お話をしていただきたいと思います。","respondent":"上野都市開発課長","answer":"それに向けてどういう形で進めていくかですけれども、今年度中に再開発事業をやっていくということですので、準備組合、あるいはそれに準ずる法人組織といったものの設立に向けての地元協議をやっていきたいと考えてございまして、その組織ができた後は。","voiceIndex":86,"id":"exchange-031"},{"speaker":"菊地委員","kind":"質問・要望","question":"半数弱、２４名の方で残りの３０％ということは、再開発を進めたときに権利床として物凄く小さくなってしまう、そういう土地の権利者もうなずくのかなというような気がするんですけれども、あと残りの方の中での、全体５１名の方でもいいんですが、自らの権利を持っている土地の面積で最も狭い方の権利というか、土地の面積というか、その辺が分かれば教えていただきたいと思います。","respondent":"上野都市開発課長、岩野まちづくり事業部次長","answer":"その方がどういう形で権利変換でどういうご希望を持っているかとかといったことにも係わってきますので、そういったものもこれからご意向をよく聞きながら。権利の面積が少ない部分については、残地の方も多いということと、それから、ご案内のように、中のほうでも小さな方がいらっしゃるといったようなことがありますので、そこら辺の弱小の方のことを勘案しながら。","voiceIndex":88,"id":"exchange-032"},{"speaker":"藤田委員","kind":"質問・要望","question":"防災センターが建築中だとか、大井町線が田園都市線になってたりとか、戸越台中学校があったりとか、現地事務所を示すだけの図面だと思うんですけれども、やっぱり議会に出してくる資料というのは、一番新しい図面というのが必要ではないのかと思うんですが、おそらく現地図を出したいために出てきたのかなと思うんですけれども、できれば、次回からぜひその辺を煮詰めていただきたいと、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-033"}]},{"id":"topic-05","title":"続きまして、次に５の東京都特別工業地区建築条例の廃止","agenda":"続きまして、次に５の東京都特別工業地区建築条例の廃止","exchanges":[{"speaker":"藤田委員","kind":"質問","question":"ちょっとわからないんですが、これはあくまでも建築をする際の制限ですね。かわらとか、れんがとか、キャバレーとか、風俗営業、建築し終わった段階で、例えばそういう業者が入り込んでくるというケースはないのか、そこまで規制をするんでしょうか。あくまでも建築を制限するということですか。","respondent":"片田建築課長","answer":"あくまで立地に係わっての建築規制ですので、建築計画を立てるというときに、建築計画の図面の中で、どういう用途に使うかといったような中で、一応確認して、合意事例に合致しているかどうかというを確認するものですけれども、そのうち建築が終わった後、実際用途について。","voiceIndex":97,"id":"exchange-034"},{"speaker":"藤田委員","kind":"意見","question":"そうすると、この意味があまりないように思うんです。建築する段階では、そこでそういう仕事をしてはいけませんよと言っていながら、建築して何年か経って、用途を変えっちゃったという場合は、環境課の判断に委ねると。そうするとあまり意味はないですね。どうでしょう。","respondent":"片田建築課長、中谷まちづくり事業部長","answer":"警察が判断するにあたっては、区のほうに照会がまいりまして、これについては準工業の用途規制に合致しているかどうかといったようなものを警察のほうにご回答申し上げて、その上で警察が判断するといったような内容です。つくる段階での一定の規制をしようというのが、建築基準法の考えです。","voiceIndex":99,"id":"exchange-035"},{"speaker":"山村委員","kind":"質問","question":"今、二重のチェックと言われたと思うんですけれども、それが廃止されるということは、チェックができなくなるということですか。","respondent":"片田建築課長、中谷まちづくり事業部長","answer":"今、委員がおっしゃられましたように、条例が廃止されるということは、計画段階でのチェックがなくなると、いわゆる準工業地域の規制がそのまま適用されるということになりますので、今回記載したようなチェックについては。したがいまして、東京都ではこれを廃止しますので、各自治体において必要に応じて条例により、また制限等をしていただきたいというのが、東京都の趣旨ですので、先ほど申しましたとおり、品川区につきましては。","voiceIndex":102,"id":"exchange-036"},{"speaker":"山村委員","kind":"質問","question":"検討しているというのは、その検討はどういうものでしょうか。","respondent":"片田建築課長","answer":"今、部長のご答弁の中でお話がありましたように、東京都の今回の廃止の手順として、迅速な事務促進による制度運用の対応とか、商業環境の変化ということを含めて、東京都全体の中で一律定めてございましたけれども、予定につきましては、いろいろ詰めた中で、検討しているのは。","voiceIndex":105,"id":"exchange-037"},{"speaker":"山村委員","kind":"質問・要望","question":"要望というわけではないんですけれども、この三つの、作業場とか、工場とか、風俗関係のことが一番規制というか、制限について、ちゃんとしていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-038"},{"speaker":"須貝委員","kind":"意見","question":"特別工業地区建築条例の廃止ということで、今まで現存する工場、または現存する工場が建て直し等々出てくる状況もあると思うんですけれども、この平米数を超えているときには、どのような状況になりますか。","respondent":"片田建築課長","answer":"ただ、先ほど申し上げましたように、住環境ということもありますので、面積制限については、場合によっては撤廃するけれども、特殊な業種というようなものについては十分配慮して検討をしてまいりたいなというふうに考えてあります。","voiceIndex":108,"id":"exchange-039"}]},{"id":"topic-06","title":"続きまして、６番目の用途地域の指定のない区域の容積率等の指定","agenda":"続きまして、６番目の用途地域の指定のない区域の容積率等の指定","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"今、課長の説明の中で、特殊な場合を除くという話がありましたけれども、特殊な場合というのはあるんですね。変な話ですけれども、この間、勝島の埋め立てをやって、容積率を決めましたよね。ああいう場合はあるにしても、運河のままでこれが実際に……。","respondent":"片田建築課長","answer":"今委員からお話をいただきましたように、例えば前回、用途地域の見直しのところで、新たにそういった土地の容積率ということで、準工業地域というような形で、規制を加えた部分がありますけれども、今回、全然土地がない、運河とか、海面上ということになりますので。","voiceIndex":115,"id":"exchange-040"},{"speaker":"藤田委員","kind":"質問","question":"河川および公有水面というんですが、河川についてはどういう位置づけですか。","respondent":"片田建築課長","answer":"エリアの捉え方として、河川とか、鉄道とか、道路もそうですけれども、行政区域のエリアに入ってございまして、それについては都市計画区域内の市街化区域といった形で位置づけられておりますので、特に河川とか公有水面のあたりまですべて入っている。","voiceIndex":117,"id":"exchange-041"},{"speaker":"山村委員","kind":"質問・要望","question":"私は、あまりホームレスを締め出すということは、公園の水道の蛇口とかを取っている人もあるらしいので、品川区ではどうかわからないんですけれども、公園の水道の水が出ないという場所もあるという形で、そこまで、そういう要望もあるとは思うんですけれども、ホームレスを締め出すほどいじめないでいただければという思いがありますので、そこら辺を聞かせていただきたいと思います。","respondent":"松代道路公園課長","answer":"地域の住民の方々からいろいろと苦情等が寄せられまして、そのときにいろいろと対応したんですが、そのときの事例で申し上げますと、警察と連携をしまして、そういった方々に施設等へのあっ旋等をお話をしながら、適正に公園等を使っていただくように、まずはお話をします。","voiceIndex":126,"id":"exchange-042"},{"speaker":"菊地委員","kind":"質問・要望","question":"幾つか教えていただきたいんですけれども、今度明電舎の業務棟が建つんですけれども、都市計画がかかって、容積率が７５０％ですか、都市計画がかかる前ですと３００％とか、そういう数字になるのかもしれませんけれども、都市計画をかけて、実際これだけ容積率を上げて、もちろんここでかかるというのは、実際には概ね５００％ぐらいという形でかかると思うんですけれども。","respondent":"上野都市開発課長","answer":"山手線と東西とのつながりに関しましては、例えば百反坂下の交差点の改良ですとか、補助１６３号線を北側に上がっていって環状６号線とぶつかるところがありますけれども、そこの取り付けの改良ですとか、そういったものをやっていくことと併せまして。","voiceIndex":128,"id":"exchange-043"},{"speaker":"菊地委員","kind":"質問","question":"今の山手通りとの取り付けの部分の話ですが、それを実際に改良をしていこうとしたときに、開発業者の負担で行われていくことなんですか。","respondent":"上野都市開発課長","answer":"補助１６３号線と山手通りというか、環状６号線との取り合いにつきましては、東京都の第二建設事務所のほうで環状６号線の整備事業ということで事業化に取り組まれているところです。","voiceIndex":130,"id":"exchange-044"},{"speaker":"本多委員","kind":"質問・要望","question":"中でも、この中で意見が出ておりますが、土壌汚染の調査ですとか、明電舎のところは以前は軍需工場の部分もあったと思うので、そういったものの対応と、できてからの電波障害、そういったものの対策をしっかりやってほしいという意見が地域からありまして、当然、概ねでき上がることを期待しつつも、生活面での不安というものを払拭してもらいたいというものがありますので、その辺。","respondent":"上野都市開発課長","answer":"遮蔽につきまして、建物外形線のところである程度影響範囲が分かりますけれども、反射等につきましては、外壁の材質ですとか、最終的な建物の形状とかによりまして、どこが影響があるか特定ができませんが、今後その辺の詳細設計をやる中で、場所とかがはっきり分かって。","voiceIndex":132,"id":"exchange-045"},{"speaker":"本多委員","kind":"質問・要望","question":"土壌汚染の調査については、不安がとれたよというような公表をぜひお願いしたいと思います。今の電波障害の話ですが、当然目に見えるものではないので、そういうことで出していますが、６０haの都市再生のエリアとは別に、大崎駅周辺で高い建物が環状６号線沿いに建っている。その辺の対応もぜひこれからしていただきたいと思います。その辺についてお聞かせいただきたいと思います。","respondent":"上野都市開発課長、浜脇住環境整備課長","answer":"明電舎が実際に建物を建ち上げた段階で、明電舎の建物によって原因になるというのは、その前後で調査しないとわかりませんけれども、調査をやりまして、今のところではアナログ放送とか。中には、４、５階のアパートが原因のときもああるんですけれども、そういうときはちょっと難しいかなと思うんですけれども、マンション等で１０階、２０階ぐらいの建物のときには、今回もこういう施設でできたというのは大体分かります。","voiceIndex":134,"id":"exchange-046"},{"speaker":"菊地委員","kind":"質問・要望","question":"１点だけお願いがあるんですけれども、住民の皆さんから説明会で出された要望がここに何点か書かれていますけれども、これに対して事業主がどういうふうに答えられたのかという資料がありましたら、ぜひいただきたいんです。","respondent":"上野都市開発課長","answer":"今後ソニー地区とか、南地区とかが建ち上がるときにつきましては、それぞれ既存の予条件に入れ込んだ形で、それは検討するように、区としても指導をしてまいりたいと思います。","voiceIndex":137,"id":"exchange-047"},{"speaker":"菊地委員","kind":"質問","question":"都市計画に関する話についても、できれば聞かせてもらいたかったんですけれども、後でまたこれはお聞きします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-048"},{"speaker":"須貝委員","kind":"質問・要望","question":"大崎ゲートシテイ等があるんですけれども、日曜、祭日、ほとんど人通りがないような閑散としたような、商業地域、工業地域と言えばそれまでなんですけれども、今回の大崎駅西口地区のほうは何とかにぎわいがあるような工夫を、例えばお店とか、何とか人が寄ってくるような、そういう地域に行政のほうもどんどん応援していただきたいと思います。その辺のご見解をお聞かせ願えればと思います。","respondent":"上野都市開発課長","answer":"明電舎のこの地区につきましては、先ほども大崎の森といわれているものの足元周りに商業施設などを配置する予定ですけれども、そこが休日も開業する予定になっておりまして、そういう面でのにぎわいを保ち続けるようなことを事業者としても検討していくです。","voiceIndex":140,"id":"exchange-049"},{"speaker":"原委員","kind":"質問・要望","question":"建物を建てるときの諸条件については、一つ一つ組み合わされていくだろうと思いますけれども、ここは西口で、東口ゲートシテイとか、あるいはは少し上のほうにも第３地区ですか、まち全体として大崎としていろいろな考え方も、コンセプトを持っていくんだと思うわけですけれども、一番大切なことは、まち全体としてのバランスをどうとっていくかだと思うんです。思いがもしありましたら、お願いいたします。","respondent":"上野都市開発課長","answer":"あとは、８ページのところに、戦略５として、持続的に発展するための体制をつくるとなっていますけれども、先ほども申し上げました、ソフト的な取り組み、にぎわいづくりとか、そういうのを将来、物をつくっただけで終わらせないで。","voiceIndex":142,"id":"exchange-050"},{"speaker":"原委員","kind":"質問・要望","question":"それはここに掲げてあるコンセプトもさることながら、実際つくっていく中で、どう使いやすさが出てくるか、あるいは機能的な回し方ができるか、こんなことをこの中で考えていってほしいし、それから、まちの運営ということも一つの大きな課題だろうと思います。東口なら東口、西口なら西口、中地区なら中地区で運営をされるんだろうと思うんです。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-051"},{"speaker":"金高副委員長","kind":"質問","question":"太陽光がこれだけ当たりますと、周辺に対する温度とか、そういうのは相当なエネルギーとして発散されるのではないかと思うし、また、この中の空調関係が熱を出すとするならば、戦略の中に、一つの目黒川の環境資源というのではなくて、環境全体が地域全部を見るという、そういうもっとグローバル的な発想というのはないんでしょうか。","respondent":"上野都市開発課長","answer":"二つ目のポチのところに、風の道、ヒートアイランド対策など検討とまちづくりへの反映となってございまして、これについては今後の検討課題というふうになってありますが、９ページのところを見ていただきたいんですけれども、右側の３の2)のところで。","voiceIndex":145,"id":"exchange-052"},{"speaker":"金高副委員長","kind":"質問・要望","question":"特にこの場所が目黒川を中心として低地でもあるということであれば、集中豪雨がきたときに、せっかくつくった都市基盤がそれよってまただめになってしまう場合もあるでしょうし、そういう呼び水になるような形の環境というものは、一面では、もっと大きな意味での確認というのをとってしかるべきだと思いますので、その辺を十分考慮して、その中の一つの部分でなくて。","respondent":"上野都市開発課長、岩野まちづくり事業部次長","answer":"今の補足ですけれども、環境検討会につきましては、東京都の環境局も入って、品川区の環境課も入って検討を進めているところでございまして、そういう面では、ここを環境面でのモデル的な地区として取り組んでいくということで。先ほど第３地区というご指摘がございましたけれども、東口の第３地区でも積極的な環境問題に取り組みまして、東京都と共同で、東京都から環境対策のモデル地区として指定をいただきまして。","voiceIndex":147,"id":"exchange-053"},{"speaker":"金高副委員長","kind":"質問・要望","question":"例えばそういうものができて、実際にでき上がって、測定したときに、過去の問題と今とどうなるか、あるいは既存の今までしてある都市と、それをつくったところの都市との比較という、そういうのができた段階で効果があればどんどんそれを公表していっていただいて、それを皆さんが納得できるような形での方向付けは行政として必要じゃないかと思いますので、積極的な行動をぜひしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-054"},{"speaker":"山村委員","kind":"質問","question":"副委員長とも絡んでおりますけれども、屋上緑化とかは考えていないんですか。","respondent":"上野都市開発課長","answer":"屋上緑化につきましては、東京都の条例、区の条例がありますので、この手の制度を使った再開発事業につきましては、３０％以上というのが義務付けられておりますので、それはきちっと守っていくというものですので。","voiceIndex":151,"id":"exchange-055"},{"speaker":"山村委員","kind":"意見","question":"目黒川の浄化のことが書いてあるんですが、例えばウォーターパークの再生、放流でどのぐらい水質浄化はできると踏んでいますかというか、そんなことは無理だろうかと思うんですが、どのくらい水質浄化ができると考えておりますか。","respondent":"上野都市開発課長、矢部下水道河川課長","answer":"まだ総量的なもの、数値的なものは具体的なものは出しておりませんけれども、一つは、今、御成橋のところで少し再生水の放流を試みとしてやることを考えておりまして、具体的な効果はおそらく微々たるものになろうかと思いますけれども。そういうこともありますので、例えば顕著にＢＯＤが６だったものが３に落ちるとか、そういうような数字的には非常に難しい面はあるかと思いますけれども、イメージ的な面、修景的な面、そういう面等を考えますと。","voiceIndex":153,"id":"exchange-056"},{"speaker":"藤田委員","kind":"質問・要望","question":"７月の終わりですから、ちょうど夏休みで皆さんが田舎へ帰ったりなんかしている時期だと思うんです。ですから、改めてもう一遍といいますか、いろいろな形で説明会、補足説明のような形で、紙っぺらでなくて、ビデオとか、分かりやすいような、そういう説明会もやってしかるべきではないかなと思いますが、関係者とよく話し合っていただきたいというふうに思うんです。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"旧正田邸跡地と、もう一つは、公園新設に対して計画が終わったかと思うんですけれども、公園計画のスケジュールと、進捗状況などありましたら、教えていただければと思います。","respondent":"岩田管理工事課長","answer":"順調にいけば、年末ぐらいから工事にかかって、年度内に竣功という、今のところ予定ですが、もともと当初予算では、前年度末、３月に用地買収が済む予定だったのが、国の解体工事が遅れたということで、全体に３カ月工程がずれておりますので。","voiceIndex":165,"id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"旧正田邸のほうでは、プロポーザルの前に、町会の方とか、区民の声をお聞きするということだったんですが、その前にそういったことはされたんでしょうか。","respondent":"岩田管理工事課長","answer":"場合によっては、宮内庁にお伺いを立てるかとか、全国的に声を募るとか、いろいろな考えが出てまいりますが、区としては、あそこの池田山という特殊性、道路そのものも居住者以外進入禁止の地域ですから、そういう極めて品川区の中の特殊な地域の中につくる公園ですので。","voiceIndex":167,"id":"exchange-059"},{"speaker":"井上委員","kind":"確認","question":"ということは、今回は、こういう計画でという住民説明会ではなくて、こういう形で進めていきたいということで、ここの都市計画の会社が選ばれて進めていくという方向ですか。確認です。","respondent":"岩田管理工事課長","answer":"もうちょっと細かく言いますと、要は、ああいう邸宅がずらっと連檐をしている地域の中で、通常、市街地にあるようなブランコとか、滑り台を置いたような公園づくりは、今のところ区はなじめないと考えております。","voiceIndex":169,"id":"exchange-060"},{"speaker":"原委員","kind":"質問","question":"今の話ですが、これ質問が出なかったら、この委員会で話がなかったんですか。建設委員会でそういう話というのは、報告事項で話しするべきでしょう。この委員会の委員はだれも知らないで、地元の説明会なりに行って、逆に、そういう話で来たんだけれども、どうなんですかと聞かれたときに、我々は何も知らなかったという話にならないとも限らないじゃないですか。","respondent":"岩田管理工事課長","answer":"ただ、委員会としてそういった資料、説明というのは、事前に必要だということになれば、今後はきちっとした説明を事前にさせていただきたいと思います。","voiceIndex":173,"id":"exchange-061"},{"speaker":"原委員","kind":"質問・要望","question":"言われていることはよく分かるので、今まで前例がなかった。ただ、この場合はかなり話題性のあるところであったわけです。それについての話になるわけなので、やっぱりその辺のところの取捨選択はしっかりしていただかなければならないのではないかなと思いますので、これは要望ですけれども、今後の中でひとつ対応をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-062"},{"speaker":"山村委員","kind":"質問・要望","question":"旧正田邸のことで質問があるんですが、旧正田邸の隣の方からのご要望がありまして、トイレをつくる、つくらないで、かなり、トイレをつくるようだったら、戦うみたいなことを言っていらっしゃる方が何人もいらっしゃって、署名まで集められているんです。","respondent":"岩田管理工事課長","answer":"区の案というのはまだつくっておりませんで、全くの白紙の状態です。ただ、今回説明会に出すのは、プロポーザルの中で採用された業者がつくってきた案は一応お見せいたします。","voiceIndex":176,"id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3760#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":62570,"voices":183}},{"id":"h15-20030826-9","meetingId":"h15-cm08","date":"2003年8月26日","dateIso":"2003-08-26","committee":"文教委員会","time":"午後１時１０分～午後５時２３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を69件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"学校選択が始まったのは、これで言うと３年生のときからプラス１になっているのかということ。それから、大井第一小学校で学区域内の児童数と学区域外から通っている児童数は、何名ぐらいになるのか教えてもらえないでしょうか。","respondent":"谷田部学務課長","answer":"通学区域外の子どもですが、同じく平成１２年度で申し上げますと５２人、平成１３年度が７６人、平成１４年度が５６人、平成１５年度が７５人という状況になってあります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"今後こういう例がほかの学校でも出てくるかもしれないですけれども、そうした場合には一定学級数を頭打ちにして、抽選という方式で一定の線を引いてやっていくのでしょうか、考え方をお聞かせ願いたいと思います。","respondent":"谷田部学務課長","answer":"それと、やはり希望される方がいる限り、私どもは極力受入れていきたいという基本的な考え方を持ってありますが、一方で先ほど申し上げましたように、普通教室に転用可能かどうかという施設面の状況を踏まえまして、過去３年間、４学級で受入れていた関係がありますので。","voiceIndex":8,"id":"exchange-002"},{"speaker":"沢田委員","kind":"意見","question":"４年生ですと、これでいくと来年、再来年と、さらに１クラスずつ増えてきて、それでやっていけるのかどうか、その辺の見通しについても説明してもらえますか。","respondent":"谷田部学務課長","answer":"大井第一小学校は全校遠足をやっておりまして、これだけの人数になりますと７００人を超えているわけですから、全校遠足でどこかに出かけるときに交差点の信号待ちのときに、何回も信号を変わるのを待つとか、そういうところで多少不便だとか。","voiceIndex":10,"id":"exchange-003"},{"speaker":"沢田委員","kind":"意見","question":"こうやって希望者が増えると、さまざまな見えないところで問題が生じてくると思いますので、ぜひ報告を待っているというだけではなくて、特に大井第一小学校はそういう傾向が強いですので、現場をよく見て相談に乗れるようにお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"西本委員","kind":"確認","question":"二つ確認をしたいことがあるんですが、新入学児の入学予測なんですけれども、平成１６年度は先ほどお聞きしたんですが、平成２１年度まで予測されているんですが、これは住民基本台帳上で平成２１年度までの人数を割り出したということなんでしょうか。","respondent":"谷田部学務課長","answer":"２点目の周知方法ですけれども、先ほど９月２１日号の広報紙にということで、その辺のことも当然触れしますし、各小学校、中学校共通のパンフレットをつくりますので、その中でも「場合によっては抽選もあり得ます」ということで、お知らせ申し上げるということを考えてあります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"確認","question":"もう一つ確認したかったのは施設問題なんですけれども、今後すまいるスクールも始まろうとしていると思うんですが、このスペースは４クラスでこれから整備するという形になっていくんですけれども、その場所も考えた上で４クラスでおさえれば、ある程度可能ですという認識でよろしいのでしょうか。","respondent":"谷田部学務課長","answer":"余裕教室等、さまざまな現状の施設をいろいろな角度から考えて４学級でおさえるという中で、ほかの学習活動展開の必要な部分を残すということも併せまして、今回のような形でお願いするです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今、説明をいただいた５の活動内容のフリータイムの中で、もう少し詳しく教えていただきたいのは、例えば具体的にメニューをどういうふうに対象にしていくのか。それは各小学校ごとにやっていくんですかというのが一つ。それを教えるためには、このことに対しては地域の方がいらっしゃいますけれども、そのことを実際にだれが責任を持ってお願いしていくのかということを教えてください。","respondent":"富田教育改革担当課長","answer":"１点目のメニューについてですが、これまで４校で実施してきておりますので、ベースとなる部分、フリータイム、勉強会、教室を基本にしていくというのは、どこも同一です。","voiceIndex":21,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"確認","question":"こういう書き方をされますと、児童福祉法に定める放課後児童健全育成事業の水準にすまいるスクールを合わせていかなければいけなくなるのではないかという心配があったものですから、その確認をお願いします。","respondent":"富田教育改革担当課長","answer":"すまいるスクール事業そのものが、既にこの項目については、結果として実施してきている中身にあたるものというふうに認識しているところであります。","voiceIndex":23,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"確かに、すまいるスクール自体は現在４校で展開されていて、非常に好評であるし、費用対効果も非常にうまく回っているということも聞いていますし、事業自体が成功しているということを聞きますから、拡大していっていただきたいんですが、これからの中で学童保育クラブ事業とすまいるスクール事業の整合性をどういうふうに山を越えていこうとなさっているのか。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは学童保育クラブ事業より対象を広く包含するものであると認識しておりますので、そういった意味でこれまでのすまいるスクール事業を基本としながら、今後のすまいるスクール事業展開の詳細について児童課と調整をしていきたいと考えているところであります。","voiceIndex":25,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"これから具体化していく中で、過去にいろいろあった保育園のときの議論とか、すぐ言われるのがサービス水準の低下とか、おそらくいろんなことをお話しする方が出てくると思いますけれども、冒頭に確認をさせていただきましたように、児童福祉法に基づく政策ということの中に位置づけしていくという方向性がはっきりしているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"６月３０日の厚生委員会での児童課長の発言ですけれども、「すまいるスクール拡大に伴う事業で、教育委員会と基本的な事項につきまして調整ができました」と断定しているんですけれども、教育委員会でどんな議論がされて、調整がついている事業の内容とは一体どういう内容のものなのか伺いたいと思います。","respondent":"富田教育改革担当課長","answer":"教育委員会と申しますか、教育委員会事務局と福祉事業部の間で、先々のすまいるスクールを含めての再編について基本的な合意をしたということでございまして、そのことにつきまして教育委員会としては８月１２日の教育委員会で報告をし、了承をいただいているところであります。","voiceIndex":28,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"今、来年の４月からまず９校で募集をやめて閉館していくという内容が福祉事業部のほうで報告されていると思うんですけれども、現在通っている学童の父母に対する説明、これから学童に通うであろう保育園に通っている子どもというか、すまいるスクール事業が変わってくるわけですから、それに対する説明はどのように行っていくのでしょうか。","respondent":"富田教育改革担当課長","answer":"教育委員会事務局といたしましては、すまいるスクールの説明をすまいるスクール対象の保護者について行っていくものでございまして、学童保育クラブについての説明が必要であれば、それは福祉事業部で行っていくであろうと考えております。","voiceIndex":32,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"事業を拡大されていくと、伊藤委員のお話の中でも学童保育クラブの機能を残すというか、その中に入るみたいな説明がされたんですけれども、学童保育クラブ機能を残すというのは、具体的にどのように事業を展開させていくのか、そこを具体的に言っていただきたいんですけれども。","respondent":"古川教育次長","answer":"そのことを踏まえながら、学童保育クラブ事業については、先ほど一定の再編というような言い方をさせていただきましたが、廃止等も含めながら福祉事業部のほうで一定の考え方を整理し、所管委員会のほうで説明をしているということでご理解をいただければと思います。","voiceIndex":34,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"すまいるスクールはなり得るという説明だと思うんですけれども、すまいるスクールの要綱の中には親の就労支援という視点は入っていないんです。実際に厚生労働省の見解でも、これらの事業は別々のものだからと、このようにも述べておりますけれども、すまいるスクールがなり得るということを具体的に説明していただきたいんですけれども。","respondent":"富田教育改革担当課長","answer":"先ほども児童福祉法の条文についてご紹介したところであります。すまいるスクールが対象児童につきましても、また内容につきましても、法に定めているところを十分満たす事業であるというふうに考えておりますので、先ほどの答弁をさせていただいたところであります。","voiceIndex":36,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"今、川崎市のわくわくプラザでは、一体どういう状況があるかというと、子どもたちの十分なスペースが確保されなくて、ある小学校では子ども１人当たりの面積がＡ３の紙１枚分しかないところもあると言うんです。こういうものも踏まえて、きちんと学童保育の子どもの安全とともに、親の就労支援対策を明記して、明らかにしていく必要があると思いますけれども、どうでしょうか。","respondent":"富田教育改革担当課長","answer":"品川区として安全第一に留意しながら、事故がないように、すまいるスクールは現在も運営しておりますし、今後ともさらに充実した内容になるよう努めてまいりたいと思っているところであります。","voiceIndex":38,"id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"品川区での今後のすまいるスクールの拡大の内容はどうなのかというと、何にも明らかにされていない。一方で、４月から始めている。１５校広げていく。これでは、やっぱり子どもの安全は保障されないんじゃないかと思うんです。今、子どもの安全が第一ですというご説明がありましたけれども、どうやって子どもの安全を保障して、どうやって親の就労支援を保障するのか、具体的に示してほしいと思います。","respondent":"古川教育次長","answer":"就労支援に対してのすまいるスクールはどう応えていくかですけれども、先ほどからお答え申し上げていますとおり、従来の学童保育クラブがこの間培ってきた部分、それは学童保育クラブ事業としての一つの事業の目的を持ち実施してきたわけですけれども。","voiceIndex":40,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の説明では何ら示されていないと思っているんですけれども、もう一度どうやって子どもの安全や成長、親の就労支援をすまいるスクールの拡大に伴って行っていくのか、必要であればすまいるスクールの要綱を改定するのか示していただきたいと思うんです。いろいろご説明ありましたけれども、そうであれば要綱自身も検討していかないといけないのかなと思いますけれども、いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"したがいまして、区が責任を持って実施する対象も広げたこのすまいるスクール事業というものが、民間施設の国庫補助基準に事細かく合致しなければいけないという定めのあるものではございませんということを申し上げたいと思います。","voiceIndex":42,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"きちんと父母や職員、学童専門のさまざまな方々からご意見を伺って事業を進めていかないと混乱が生じてしまうんじゃないかと思うんです。学童保育クラブがなくなってすまいるスクールに行くわけですけれども、すまいるスクールに通う子どもは何人と想定しているんですか。来年４月から行う事業ですから、きちんと明確になっていないといけないと思うんです。具体的にお答えいただきたいと思います。","respondent":"富田教育改革担当課長","answer":"すまいるスクールは、対象児童を原則として実施校に在籍する児童、１年生から６年生まですべてというふうに要綱で定めております。","voiceIndex":44,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"当然、すまいるスクールに通う児童が増えてくると思うんです。登録している中で、実際通っている子どもは２割か３割という話も伺ったんですけれども、やっぱりきちんと何人の子どもが通うことを想定していて、それに対して必要な職員体制は何人なのか、そこを明らかにしていかないと、子どもの安全は保障されないと思うんですけれども、最後にこれだけきちんとお答えしていただきたいと思います。","respondent":"富田教育改革担当課長","answer":"登録児童の参加児童が多い状況が見られるわけであります。こういった参加児童の状況を参考にしながら、今年度９月以降の人的配置はしてまいりますし、さまざまな安全確保等々を留意していきたいと考えているところです。","voiceIndex":46,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問・要望","question":"例えば、体育館であるとか校庭であるとか、地域のサッカーチーム、野球チームの方たちも使われて、そこのところとすまいるスクール事業も体育館等々を使われると思うんですが、その辺のやり方はどちらが優先というふうに決められているのか、できれば学校ごとでの調整をしてほしいと思うんですけれども、教育委員会としてはどういう方向性で指示を出されているのかという点です。","respondent":"富田教育改革担当課長","answer":"土曜日等、若干成人の団体との重複の問題が出てまいりますが、その辺は実施校の児童が参加するすまいるスクールということもありますので、学校によっては若干時間の調整をお願いできないかどうか相談しているところもあるですが。","voiceIndex":48,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"その場合、一定の研修は必要な部分があるのではないかなと。当然、学校で事業をやっていますので、最高責任は学校長ということはあるんですが、ただ校長先生もずっといるわけではないので、日々の管理体制といいますか安全面も含めまして、人数に対しての加算は、場合によっては考えられるという方向性があるのかどうかお聞きしたいんですけれども、いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"いろいろご指摘をいただきましたが、事実確認ができませんので何とも申し上げられないんですが、９月に任用を新たに予定しておりますけれども、こちらとしても十分なそういった意味でのレクチャー、特に全体を集めての場でもそうですけれども。","voiceIndex":50,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問・要望","question":"これはお願いになります。逆に、中身を知らせると、ボランティアというところでも、少し自分で余裕があるからやってみようかなというように、もう少し地域の方たちがすまいるスクールの中に入って来やすいような、そういう情報源にもなるのではないかなと思っているんですが、父母へのフィードバックはどのようにお考えになっているのかなと思うんですが。","respondent":"富田教育改革担当課長","answer":"保護者へのさまざまなお知らせ等を含めてですが、開設時の説明会のほかに３月末に各学校で説明会を開いておりますが、参加が少ないという状況がございまして、やはりすまいるスクール独自でやるよりも。","voiceIndex":52,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問・要望","question":"それが子育て支援にもなりますので、学校の保護者会である程度の連絡事項は適切だと思いますけれども、ただ生活を伝える場というのは、担当の指導員がおりませんので、全学年のクラスを回ることは不可能ですからできないと思うんです。子育てをしやすくするための大切な方法だと思いますので、今後検討に入れていただきたいなと。これは意見という形にさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"すまいるスクールと学童保育クラブの再編のことについて、もう少し聞かせてほしいんですけれども、今は約１,７００名の子どもが３８の学童保育クラブに通っています。同じようなことをやっているからだと言うけれども、どうも聞いていると、法律的な要請というか、財政効率的なものが前面に出ているんですけれども、区側の思いというのは何なんでしょうか。再編成する動機というか、ねらいというか。","respondent":"富田教育改革担当課長","answer":"すまいるスクールの対象児童は、ほとんど学童保育クラブの児童を包含するということがあります。そしてまた、学校という大変安全な施設の中で、ハード面、ソフト面を含めて学校との密接な連携教育のもとにすまいるスクールが行われてきた。","voiceIndex":55,"id":"exchange-024"},{"speaker":"沢田委員","kind":"質問","question":"そうしますと、すまいるスクールは全児童対象の放課後の生活の場、学習の場を提供するんだから、学童保育クラブも包含しちゃっていると。だから、同じような施設が二つあると、人件費や運営費がいろいろかかってむだだから統合するということでいいんですね。３８館ある学童保育クラブの施設を、あえて閉鎖してしまう。それは財政効率上、むだだからと。どっちなんですか、率直に言ってほしいと思うんです。","respondent":"富田教育改革担当課長","answer":"したがいまして、すまいるスクールとしては、これまでも全児童を対象に行ってきたし、これからも同様に行っていくと、この方向性には何ら変わるものはない、基本部分は変わるものはないというふうに考えているところです。","voiceIndex":57,"id":"exchange-025"},{"speaker":"沢田委員","kind":"意見","question":"わかりました。財政上のむだをなくすために学童保育クラブを廃止するとは言いませんけれども、今の言葉の中でよくわかりました。そこで聞きたいんですが、現在のすまいるスクールのほうが保育に欠ける児童に対して、よりサービスが行き届くと言えるかどうか。学童保育クラブよりすまいるスクールのほうが就労と子どもの支援で、サービスがより行き届くということを言えますか。","respondent":"古川教育次長","answer":"もう一つのすまいるスクールは、あくまでもこの間学校あるいは家庭、そして地域という中での放課後、あるいは土曜日も視野に置きながら、学校という施設を使って全児童に対する施策として平成１３年度から実施してきております。","voiceIndex":59,"id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"私の質問に答えてください。なぜ学童保育クラブを廃止するのか、その理由は何なのかと言うんです。","respondent":"古川教育次長","answer":"その事業内容につきましても、放課後健全育成事業が指定している以上のものを行っていると考えております。ですから、あくまでも財政効率だけを視野に置いて、学童保育クラブ事業を廃止してすまいるスクール事業にということではありませんということでご説明しております。","voiceIndex":61,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"全然、答弁になっていないんだけれども、これをやっていると行き違いのことなので、ちょっと先に進めたいと思います。そこで、先ほどのすまいるスクールの出席率は５０％だったという答弁がされましたけれども、年度を追って人数と出席人数を教えてもらえますか。","respondent":"富田教育改革担当課長","answer":"年度を追ってですが、平成１３年度は９月に第二延山小学校がモデル実施ということで行いました。登録が３月末現在で７１％でございまして、全児童数は４４３名おりましたが、これに対して登録数は３１５名ということでございまして、参加児童数は１カ月平均約２,０００人です。","voiceIndex":63,"id":"exchange-028"},{"speaker":"沢田委員","kind":"確認","question":"今から４回前か５回前の委員会でのすまいるスクールだけの答弁のときに、出席率は２０％台と言ったか二十数％と言ったか、私はその後に議事録を確認していますから、それが今日５０％に膨らんだのは何なのかなと思って聞いたんです。実は、ここに問題があるんです。ところが、学童保育クラブの子どもはどうなのかというと、１日勉強しても帰る家には親がいない。いかがでしょうか。","respondent":"富田教育改革担当課長","answer":"したがって、安全管理とか必要な事項は、当然のことながら全児童に対してやってまいりますけれども、そういった思いが持てるような充実した中身にしていくように、指導員ともども努めてまいりたいと思っている次第であります。","voiceIndex":65,"id":"exchange-029"},{"speaker":"沢田委員","kind":"質問・要望","question":"今日は疲れたからごろっと横になりたい、休んでいたい、今日は行きたくないと思ったら、どこに行けばいいんでしょうか。だから、学童保育クラブの親はみんな心配しているわけですよ。毎日行きたくなる場所を目指しているのは立派だし、やってほしいと思うけれども、学童保育クラブの子どもがすまいるスクールに行きたくないと言った場合にはどう指導するんでしょうか。","respondent":"古川教育次長","answer":"ただし、すまいるスクールが今学童保育クラブを利用されている子どもたちにとっても、学童保育クラブと同等あるいはそれ以上にすまいるスクールが利用されるような環境は、今のすまいるスクールにも当然備わっていると考えていますし。","voiceIndex":67,"id":"exchange-030"},{"speaker":"沢田委員","kind":"確認","question":"私はやるべきではないと思っていますけれども、すまいるスクールに学童保育クラブが合併し廃止をされるようなことになれば、それこそ次の段階としてそういうことを考えるべきだと思いますけれども、今は果してそれが子育て支援という、親が悩んでいることに後押しをする正しい選択かどうかという点を、いろんな角度から考えるべき時なので質問をしているわけです。だから、さっきの答弁はおかしいんですよ。","respondent":"富田教育改革担当課長","answer":"一人ひとり確認を行っております。面積のお尋ねですが、すまいるスクールにより参加児童数に差がありますが、おおむね使用している教室は３教室から４教室、その他体育館、校庭等も授業で使用しない時間には使うということで行っているものであります。","voiceIndex":69,"id":"exchange-031"},{"speaker":"沢田委員","kind":"確認","question":"特に、所在確認ですね。厚生労働省の民間施設の補助基準ですから、これをクリアしていなければ話にならないと思います。今日、これ以上やってもあれでしょうから、ぜひ次回には所在確認を含めて、こうやって現在以上の体制、それから子どもたちが行きたくないと言ったときにはどうするという体制についてしっかり示してほしいと思います。最後になりますけれども、私も長期計画の検討委員会のメンバーです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"今後、学童保育クラブがなくなってしまいますと、児童センターの中には学童保育機能がなくなるということになりますので、働いている親御さんにとっては心配事だと思いますので、受入れ枠をある程度の許容範囲を持った形で、すまいるスクールを利用できるような措置ができないかとか、その辺の考えをお聞きしたいと思います。","respondent":"富田教育改革担当課長","answer":"私立小学校等の児童についての扱いですが、学校の全面的な協力で学校と同様のルールで実施しているという状況がありますので、現時点では私立小学校等の子どもの受入れは困難というふうに考えているところでありますが、今後それにつきましても。","voiceIndex":72,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"最後に意見といいますか現状ということで、今後児童課と検討する際に参考にしていただきたいんですけれども、先ほどすまいるスクールは行きたくなるような内容にするべきだと、それは当然その目標であるべきだし、支援していきたいと考えていますけれども、現時点でどうなっているかというところでは、幾つか意見をいただいているんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ質問をさせていただきたいんですけれども、先ほど障害も持たれた子どもに対しては付き添いがつきますという話があったんですけれども、付き添いの配置基準はどういう基準で行っているのか聞かせていただきたいんです。すまいるスクールでの職員の体制も、今付き添いという説明がありましたけれども、人の配置の基準を教えていただきたいと思います。","respondent":"富田教育改革担当課長","answer":"どの子どもについて付き添いが必要かどうかということは、学校側とよく相談をしてご説明をさせていただいているという状況です。今後につきましては検討課題であると、来年度以降は検討させていただきたいと思っているところであります。","voiceIndex":75,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"保護者がつかれるんですね。当然、働いている家庭で保護者が付き添えないという家庭もいらっしゃると思うんです。そういう家庭については、どのように体制を組まれるんですか。","respondent":"富田教育改革担当課長","answer":"来年度以降につきましては、今後検討をしてまいりますと、先ほど申し上げたところです。","voiceIndex":77,"id":"exchange-036"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１点だけ質問します。先ほど来、すまいるスクールそのものがいいというお話とか、すまいるスクール自体、川崎の例も出されてよくないというお話もある。それから、先ほど非常勤職員の話はさまざま出てきたんですが、教員の参加を当初からさまざま呼びかけをしているという話があったと思いますが、ここの部分についての現状を教えていただきたい。","respondent":"富田教育改革担当課長","answer":"これまで実施をしてくる中で、すまいるスクールの果たしてきた役割というのが二つの面で明らかになってきたかと考えています。","voiceIndex":79,"id":"exchange-037"},{"speaker":"石田副委員長","kind":"質問","question":"ですから、この辺のところの細かい部分をどのように修正していくのかというところと、教員の部分と納得できなかったんだけれども、教員はあんまり参加していないというのが私の耳に入っているのが現状、これは間違っていたらごめんなさい。","respondent":"富田教育改革担当課長","answer":"従前に比べまして、教員集団の中で専任指導員が本当に一員として参加して、さまざまな学年会ですとか職員会議の場に一体となって、すまいるスクールの子どもも実施校の同じ児童でありますので、昼間の姿と放課後の姿は子どもは一体であるということで。","voiceIndex":81,"id":"exchange-038"},{"speaker":"山路委員","kind":"質問・要望","question":"すまいるスクールは地域の保護者、児童にいろいろ話を聞くと、非常に評価があって喜んでやっていると言うんです。区外の方からも、品川区のすまいるスクールはいいねと、かなりの評価を私個人は受けているわけです。飛躍した考えですけれども、そういうふうに学校が自由化になっているので、すまいるスクールも自由化に発展してもらいたいという希望があるんですけれども、今、突然考えられないですか。","respondent":"富田教育改革担当課長","answer":"現在のところでは、学校との連絡を密にしており、かつ緊急連絡ですとか、すべて学校一体のものとして行っておりますので、登録自体を別の児童を受入れるということは、現在はちょっと難しいかと思いますが、例えば特色ある事業、教室等について乗り入れができないかとか。","voiceIndex":83,"id":"exchange-039"},{"speaker":"沢田委員","kind":"質問","question":"学力定着度調査の学力テストの成績の公表で、どんな状況だったのか、問題は特になかったのか、あるいはアクセスが学校ごとにカウントしているものがあれば教えてほしいし、寄せられた意見あるいはメールはどうだったのか概略を教えてもらえればと思うんです。","respondent":"中島指導課長","answer":"２学期が来週から始まりますので、そこで各学校は保護者会等で今後の自分たちのやっていく方向について説明をしていくですので、その流れの中でご意見が出る可能性があろうかなと考えております。","voiceIndex":87,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"本会議でも４会派から学力テストについて質問が出されたり、文教委員会の中でも議論を積み重ねてきました。８月８日の公表をもって、この議論が終わるわけではないんじゃないのかなと思うんです。どうして担任の先生に答案用紙を返さないのか、また児童に返さないのかお伺いしたいと思うんです。そして、どうやって指導計画を見直すのか、説明していただきたいと思うんです。","respondent":"中島指導課長","answer":"具体的には、今後の２学期の保護者会等の説明で、そういう実施をしていくような形になろうかと考えております。","voiceIndex":89,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"このテストは今年だけではなくて、来年度も実施する。やっぱり、こういった経緯を重く受け止めて、来年度の実施、または公表に向けて見直していく必要があるんじゃないのかと思うんです。教育委員会はきちんとそれを受け止めて進めていく必要があると思うんです。学校アセスメント部会また今後学力定着度委員会が行われていくと思うんですが、開催日程についてもきちんと示していただきたい。","respondent":"中島指導課長","answer":"調査の実施につきましては、常に評価をしながら来年度に向けて考えていきたいと思います。この調査は単独では十分にわからない部分がたくさんあろうかと思いますので、経年でやっていきたいというのが私どもの考えであります。","voiceIndex":91,"id":"exchange-042"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"石田副委員長","kind":"質問","question":"今、資料をいただきました。データ的には、例えば８割の子どもが塾に行っているとか、習い事は９割、中学校に行けば九十何％の子どもはそういうものに行っているんだということはよく耳にするわけですけれども、学校の先生がどこまで子どものことを把握しているのかというところを、地域と見るのか、学校がそこまで携わろうと思っているのか、その辺のところからお聞きしたいなと。","respondent":"中島指導課長","answer":"今、委員のご指摘のありました、こういう子どもたちの側面というのは、情報としては学校にはほとんどない中で、子どもたちの教室での姿をもとに教科を指導しておりますし、また生活指導の場面で、必要な状況が応じたときには。","voiceIndex":98,"id":"exchange-043"},{"speaker":"石田副委員長","kind":"質問・要望","question":"今の現状で青少年健全育成、道徳というものをどうとらえて、品川区の教育の中で、こういうことをこう変えたらどうかということをどんどん言っていただきたいし、せっかく所管事務調査でやるわけですから方向性をということで、この前正副委員長でお話をさせていただいて、私が口火を切ろうということだったので、口火を切らせていただきましたので、ぜひ皆さんにそういう視点から物を言っていただければ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-044"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今、ご説明をいただきましたけれども、これはこれでもちろんやっていただきたいし、広めていただきたいんですが、一番最後の６のところにある関係諸機関との連携があります。もちろん大人ですから、学問、知識とか、さまざまな対処法はやってきたでしょう。それをやってください。だけれども、前提が大きく変わっているわけですから、そこについての対応が遅れているような気がするんですがいかがでしょうか。","respondent":"中島指導課長","answer":"例えば少年センターで多くの非行の傾向にある少年たちに係わってきている方々から直接様子を聞いたり、また児童センターで対応しているいろんな形の子どもたちの実態を、タイトルとしては児童相談所の役割ということですけれども、それが終わった後も質疑の中で。","voiceIndex":103,"id":"exchange-045"},{"speaker":"伊藤委員","kind":"質問","question":"そこに対して家庭訪問という話がありましたので再度質問はしませんけれども、そういうところに生活指導主任会の知恵とか知識とか、それからもう少し言えば問題行動を起こすグループに近い予備軍の方々という表現がいいかどうかは別として、そういうところに対してある意味予防的な対応としてもしっかりとした情報があるとするならば、どうして学校で生かすことができないんですかと、逆にお伺いしたい。","respondent":"中島指導課長","answer":"そういった部分はあるんですけれども、主任会等でもらったさまざまな情報ですとか、そこから学校として取り組まなければならないものを共有化してやっていこうという部分につきましては、ご指摘のような状況がまだ残っているかと思いますので。","voiceIndex":105,"id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問・要望","question":"長崎の事件もありますし、やっぱりああいうものを取り囲む環境、それからそれを生み出すような本当に厳しい環境の中にいるということから考えていかないと、９０％ぐらいの子どもたちのもちろんいいことはやっていただきたいんですよ、やらなくていいんじゃなくて、併せてそういう本当に問題の根となる部分についてまで掘り下げていかないと。","respondent":"中島指導課長","answer":"課題もたくさんありますので、委員のご指摘をいただいたところも大きな課題だろうと考えておりますので、先ほどのような体制を取っていきたいと考えております。","voiceIndex":107,"id":"exchange-047"},{"speaker":"石田副委員長","kind":"提案","question":"そういう形の中で、我々のある程度の考え方を委員同士でいろいろすることによって、ある程度わからないことは聞きながら進めることが、かえって教育委員会も参考になる意見だと思いますので、ぜひそういう視点で、相反することでも構わないわけですから、こういう場で所管事務調査をやっているわけですから、そういう形の中でと思って提案させていただいたわけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-048"},{"speaker":"西本委員","kind":"質問","question":"なかなか来てほしいと親は思わないということで、親側からいうと選択制にして、どうしても学校に行って面談したいという場合でもオーケーだし、家庭訪問をしてほしいと言えば、家庭訪問を実施という意味では、それは選択制があっていいかなと思ったりするんです。「品川区で推進しているので、その学校ではできないんですか」と言うと、「できません」というふうに結構できていないんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-049"},{"speaker":"沢田委員","kind":"意見","question":"全然違うんですけれども、今は学校の先生が何年ごとに変わるんでしたか、６年ごとでしたか。","respondent":"中島指導課長","answer":"ちょうど見直しの時期で、来年度からまた切り替わるんですが、現状では６年から１０年ぐらいの間で異動するという形になります。来年度になりますと、もうちょっとスパンが短くなります。","voiceIndex":112,"id":"exchange-050"},{"speaker":"沢田委員","kind":"意見","question":"私は学校の先生が、これは悪く言った言い方で申し訳ないんだけれども、腰掛け的に無難に過ごせばいいと。その辺は私なりの意見なんですけれども、改善の余地があるんじゃないかと。ただ、あまり長いことがいいかと言えば、これもまた別な弊害があるから、どこで線を引くのがいいかというのは言えないんですけれども、そんなところで、後は皆さんの意見を聞かせていただいて、勉強させてもらいたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-051"},{"speaker":"中塚委員","kind":"質問・要望","question":"最近考えていることなんですけれども、親と子どもの接する時間がだんだん持てなくなっているという話を、結構地域の方から伺うんです。僕は２７歳なので、実感としてもちろんないですけれども、結構頻繁に伺うんです。伺いたいのは、家庭がすごく大変だという中で、就学援助を受けている家庭が増えていると伺ったんですが、ちゃんとした資料があればいただきたいんです。","respondent":"中島指導課長","answer":"今、手元にある資料でですが、教育委員会の平成１５年度事務事業概要の２２ページにあるんですけれども、小学校では平成１２年度、１３年度、１４年度で受給率が２３.５％、２５.３％、２６％と増加になっております。","voiceIndex":115,"id":"exchange-052"},{"speaker":"中塚委員","kind":"質問","question":"就学援助を受けている家庭というのは、徐々に増えてきているんだなと。２６％というと、クラスに複数いることになるんでしょうか。〔「４人に１人」と呼ぶ者あり〕 本当に地域と学校というか、教師と保護者というか、そういう中での係わりがあるのかなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-053"},{"speaker":"本間委員","kind":"質問","question":"小さいときから塾だとか家庭教師をつけながら、やはり親のほうも叱咤激励で、やはりよい学校を出て、よい就職をしてという部分は、結局日本の終身雇用制度とか、あるいは年功序列型の部分に起因することも多いわけですから、とにかく小さいうちから親のほうが塾だとか家庭教師をつけたりしながら、親の熱心さのあまり、子どもの競争ではなくて親の競争の時代があったのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-054"},{"speaker":"山路委員","kind":"質問・要望","question":"教育現場において一番大事にしなければいけないというのは、児童・生徒自身の各々の考えというふうに社会をとらえられているのか、自分自身をとらえているのか、地域を学校をということが見えてこないといいますか、子どもの目線でよく私たちは言うんですけれども、児童自身の目線で何を今考えているのか、その辺の現場から上がっていることで、それは教育でもいいですし、我が学校をどうしようでもいいし。","respondent":"中島指導課長","answer":"「担任の先生の言っていることは正しいと思いますか」、これに対する答えが２０％の３年生が「そうは思わない」と答えているんです。これは小学校５年生、中学校２年生も段階的に取っているんですが、ご推察のとおりだんだんとその比率は高くなっていってしまう。","voiceIndex":119,"id":"exchange-055"},{"speaker":"山路委員","kind":"質問","question":"大変いい答弁をいただきまして、ヒントになったんですけれども。その子ども自身の意見を感じて、教師が受け入れて実戦している教師は何％ぐらいいらっしゃるのでしょうか。","respondent":"中島指導課長","answer":"例えば算数の面積のところであれば、この授業を実施するために、どういう指導方法を工夫すればいいかという研究なんですが、そのベースラインでは、今、子どもたちが算数についてどういう考え方やどういう実態があるのかということをかなり調査をするような場面があります。","voiceIndex":121,"id":"exchange-056"},{"speaker":"山路委員","kind":"質問","question":"その１点が迷うところであり、大事な視点じゃないかと思っているんです。学問は今までどおりでいいと思うんですけれども、それに付随するいろんな事業をやられている目的は何なんでしょうか。確かに、子どもの目線の、教師に対する信頼が２０％しかしていないという、それを拡大して考えると社会の現象じゃないかと、ある視点からとらえているんですね。もちろん学校でいろいろ違いますよね。","respondent":"中島指導課長","answer":"ぜひ、教師と子どもたちの信頼関係がよくいっている学校に、すべての５８校にしたいなとは考えておりますが、例えば先般の学校選択制のアンケートのデータを見ましても、私学を選んだ保護者は。","voiceIndex":123,"id":"exchange-057"},{"speaker":"山路委員","kind":"質問・要望","question":"その辺の鋭い視点は、ぜひ養っていただきたいことと、そのために教育委員会は何をやられているか、何をやろうと思われているか、その点を聞かせていただきたいんですが。","respondent":"中島指導課長","answer":"特に、教員に関しましては、ＯＪＴと言われる実際の業務を行いながら自分を高めていくというような要素がこれから必要だろうと考えておりますけれども、それはそれぞれの学校の中でということになりまして、私ども教育委員会が直接係わる部分としましては。","voiceIndex":125,"id":"exchange-058"},{"speaker":"山路委員","kind":"質問・要望","question":"その辺をまず教育者である指導課長が確信を持ってやっていただきたいことと、児童を社会の一員に育てていくという、教師に責任を持っていただきたいような指導をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":127,"id":"exchange-059"},{"speaker":"石田副委員長","kind":"確認","question":"珍しく教員に対しての感じ方は、教育長のお考えではなく沢田委員と意見が合うなと、そういうふうに聞いておりましたが、ぜひそういうこともこの中で話していくと、非常にいいことなんじゃないかと思いますし、ぜひもう一度こういう機会を設けて、今度事実的なことも確認をしたいということもあって、一つだけ言うと、よく渋谷で問題になったということなんだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"さまざまなご意見をいただいて、私も参考になりました。できるだけこれを深める意味でも、品川区の学校教育とかどういう子ども像をイメージして、プラン２１とかいろいろあるというけれども、そこは抑えたいなと思っているんです。そういう議論ができるような場があると、もうちょっと具体的に共通した将来像を頭に浮かべながらの議論ができるのではないかなと思うので、ぜひ考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-061"},{"speaker":"西本委員","kind":"意見","question":"そういう意味です。どういう子どもに育ってほしいとか、それに対してプラン２１で道徳、学校教育活動に出てきていると思うんですけれども、それをもうちょっとクローズアップして、こういうことをするためにはこういう施策が必要ではないかとかとリンクしてくると、出てくるものもぽっぽと出てくるので、リンクの仕方というのがちょっと見えない部分があるんです。","respondent":"堺委員長","answer":"次回は今日の意見を踏まえながら、家庭教育という点に絞って、また所管事務調査を行ってまいりたいと考えています。","voiceIndex":132,"id":"exchange-062"}]},{"id":"topic-03","title":"３の行政視察","agenda":"３の行政視察","exchanges":[{"speaker":"石田副委員長","kind":"質問","question":"日程２日目の午後の廿日市市ですが、決算特別委員会がその時期に入っているというということで、たまたま私が先方の議長を知っておりまして、議長にお願いをいたしました。この学長はもう一つ面白い話をしてくだいさまして、「もし文教委員会の形の視察で来るなら、広島県の教育委員会の次長を同席させようか、そういう人と話したほうがもっと面白いだろう」と、「本当にいいんですか」と言いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-063"},{"speaker":"沢田委員","kind":"質問","question":"広島市の視察は、このとおりやるということでしょうか。","respondent":"堺委員長","answer":"さっき申し上げた廿日市市を当初予定しておりましたけれども、見通しがつかないので広島市になったという説明です。","voiceIndex":139,"id":"exchange-064"},{"speaker":"本間委員","kind":"確認","question":"せっかく副委員長が中に入って、忙しい日程でいまだにクエスチョンマークの部分もあるみたいな話ですからあれなんですが、そうすると皆さんに万が一正式な日程に入らないけれども、こういう形で今回はやりますという形の中身だということを確認していかないと、できたら中に入れてやったほうがいいのかなというふうに思ったわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-065"},{"speaker":"中塚委員","kind":"質問","question":"プロフィールを見ていて、いろいろ研究をされている方だなと思って、いろいろ貴重なお話を聞けると思うので、もし可能であれば最近５年間の研究業績の中で、これは雑誌か何かなんですか、事前に勉強したほうが聞いたときに意見がかみ合うというか、まとめている論文があるという感じなので、取り寄せられるのであれば、僕らも勉強してから伺ったほうが、より討論が深まってくるんじゃないかと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-066"},{"speaker":"沢田委員","kind":"意見","question":"そのことを言われているんだと思うんですけれども、せっかくこういうふうにやったならやったで、正規にしてきちっとしたほうが、どうせやるなら私は賛成です。だから、これは絶対どこかというのは、我々も視察目的に合致して出てくるならいいけれども、そうでないことで出てくると、果たしてこれでいいのかどうなのか判断基準を迷うので、いろいろ意見が出たんじゃないかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":143,"id":"exchange-067"},{"speaker":"沢田委員","kind":"質問","question":"時間的にはどれぐらいを考えているんですか。会食しながらでしたね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-068"},{"speaker":"石田副委員長","kind":"意見","question":"前学長が、文教委員会の中でこういう形のもので視察に行くということであるならば、広島県の立場も語れるだろうから、そういう人を呼んだほうが参考になるんじゃないかというような、善意でおっしゃっていただいている部分で、本当に来てくれるかどうかは全然知りません。たまたま市川前学長からそういうお話が出て、県の教育次長を呼んだほうが皆さんのためになるんじゃないかというお話ですので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":151,"id":"exchange-069"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4478#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":67852,"voices":155}},{"id":"h15-20030826-5","meetingId":"h15-cm08","date":"2003年8月26日","dateIso":"2003-08-26","committee":"総務委員会","time":"午後１時０５分～午後４時２５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"１、平成１５年度都区財政調整の当初算定","agenda":"１、平成１５年度都区財政調整の当初算定","exchanges":[{"speaker":"土井委員","kind":"質問","question":"まだ話が、そういう意味では、進んでいないということになるんでしょうけれども、いわゆる都と区の財源配分割合といいますか、この辺のことは、今回のこの決定に向かってどのように論じられて、その結果、そのままなのかというところは、どうなっているんでしょうか。","respondent":"市岡企画財政課長","answer":"都区間の財源配分の割合、つまり５２％対４８％をめぐっては、財調制度の根幹に係わる問題として、毎年の都区財調協議の中では、後ほどご報告申し上げますが、一たん場を変えて、都区間の財源配分等、今後の財調の課題を議論するための場は。","voiceIndex":5,"id":"exchange-001"},{"speaker":"本田委員","kind":"質問・要望","question":"１点だけ。全体として２.６％減っているのが特徴の一つだということですが、２３区全体が、どこもおしなべて減なんだろうと思いますけれども、２３区の調整三税が全額で当初、これは都のほうの資料だと思うんですけれども、出されたのか、品川区の場合２.６％ということなんですけれども、固定資産税は幾らなのか。法人税は幾らなのか。その数字がもしわかれば、お知らせいただきたいと思うんですけれども。","respondent":"市岡企画財政課長","answer":"以上のように、東京都は、現時点では、今年度の徴税見込額、調定額から、今回の当初算定の基礎になる調整税の額を見込んでいるですので、先ほど、ちょっと申し上げましたが、これから年度の後半に向けて、なかなか楽観はできませんけれども、例えば税収が増えてくれば。","voiceIndex":7,"id":"exchange-002"},{"speaker":"本田委員","kind":"質問","question":"それにしましても、当初算定ですから、そういうような点の推測が出てきているんだと思いますけれども、その辺は、いつも財調の当初算定では、一体品川区は幾ら税金を納めることになっているのか、推測されているのかと思うんです。その辺がよくわからないというのが、どうもしっくり来ないというか、わかりにくい。その辺は、いかがですか。そういう点については、どういうふうに考えていますか。","respondent":"市岡企画財政課長","answer":"調整税の納税と各区への交付の関係なんですけれども、品川区は昔から大体標準区、人口３５万人というモデルの区に一番近い規模と需要を持っているので、かつては、区内で上がってくる調整税と交付金が大体同じぐらいな時期があったんです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"めでたく不交付区になったと言っていいのかどうかわかりませんけれども、両区とも、当初予算では０じゃないんですよね。たまたま私は持っていたんだけれども、渋谷区なんか、科目存置で２,０００円だけ挙げていて０になった。港区の場合は、２億円挙げていて０になった。そういうのもひっくるめて、最初に予算として挙げていくときの考え方はどういうふうになっていますか。","respondent":"市岡企画財政課長","answer":"品川区の場合、去年に比べると８億円ほど落ちているんですが、もっと落ちていますね、今年、もともと予算比で１０億円落としていますから、予算額と当初算定額は１億５,０００万円ぐらいの差で、ほぼイコールです。それは多分、平成１０年度の数字をお持ちなんだと思うんです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、決算が予算どおり出ているかどうか、ちょっと見てないからよそのことはわかりませんけれども、前年比マイナスというのは、各区とも需要額が減ってきているということになるわけですよね。そうすると、何となく、いわゆる東京都のほうが減ってきているというか、減らしてきているんじゃないかといううがった見方もできるんですけれども、そういう細工は、東京都を信じていいんですかね。","respondent":"市岡企画財政課長","answer":"そういう意味では、調整税の歳入の見込みに合わせてフレームをつくっていくという姿勢は、どう考えても間違いですけれども、現実問題として、調整税もそうですし、各区の歳入も含めて、今のように非常に財政状況の厳しい中では、おっしゃられるように。","voiceIndex":15,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"例えば、どのぐらいの区が不交付になったら、もう１回、これについて東京都と話ができるのか。さっき、品川区も住民税が上がってきているという中で、都心回帰で、４区、５区が不交付団体になってくれば、これは９０億円ぐらいだけれども、１００億円、２００億円、３００億円ぐらいにふくらんでいくと、そういう論争が出てくると思うんですけれども、今のところはないですか、懸念と情報は。","respondent":"市岡企画財政課長","answer":"地方制度調査会なんかは、新しい地方財政制度の中で、共同税方式の財政調整を検討したらどうかとか、ドイツのように、いろいろなレベルの地方公共団体が、税を共同で取って、それを水平調整だけをやるというような議論もありますが、私どもは。","voiceIndex":17,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"もう１点だけ。そういう不交付の団体が出てきて、今の制度そのものを考えていく手前に、いわゆる大都市事務という、今まさにここを、時間的な制約の中で解決していく都区間の協議が生れて、そこに影響というのは生れるんでしょうかね。それから、港区、渋谷区はかなり強い口調で言える立場になってくるという気もしないでもないんですけれども、その辺についてはどうですか。","respondent":"市岡企画財政課長","answer":"ただ、これは後の所管事務調査との関係もありますが、都区間の財源配分の議論に、いわば水平の区間の議論を混ぜると、どうもあんばいがよくないものですから、徹底して２３区でやらなきゃいけないんですが、今のところは、都の前ではそういう議論はしていないという状況です。","voiceIndex":19,"id":"exchange-007"},{"speaker":"築舘委員","kind":"質問","question":"逆に交付金がないところは、緊縮財政みたいにして、むしろ損をしているんじゃないかという部分が残るんじゃないかと思うんですけれども、そこはどういうふうに調整しているんですか。","respondent":"市岡企画財政課長","answer":"もう一つは、各区の事業意欲によってと言いますか、重点の置き方によって算定される項目、よく我々が補正係数がかかっているとか、対応補正をしているとかと言いますけれども、こういうものは、確かに各区の行政需要のそのときどきの実績に応じて算定がされますが、全体としては。","voiceIndex":21,"id":"exchange-008"},{"speaker":"築舘委員","kind":"質問","question":"そうすると、品川区なんかは、どんどんアイデアを出して、ある意味で新しいことをやっていこうという傾向があるので、逆に都のほうから見れば、やっぱり財政需要額が多いんじゃないかということで、品川区には交付金を多くしてあげようというようなニュアンスというのは出てくるんですか。","respondent":"市岡企画財政課長","answer":"結論から言うと、基本的なことで恐縮ですが、財調は補助金じゃありませんから、ルールは平等でなければいけないので、そのルールに従って需要を積み上げる限りは、特定の区が、ほかの区に見えないところで得をしたり、損をしたりということは絶対にありません。","voiceIndex":23,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"不交付が港区、渋谷区と２区だったと思うんです。先ほどの説明では、二つの区とも、住民税が増えたのが原因じゃないかと、そういうように担当者が言っていたという話だったんですけれども、このことをもうちょっと詳しくお聞かせいただければと思うんです。もう少し主観を含めてでもいいですけれども、ちょっとどんな状況なのかというのをお願いします。","respondent":"市岡企画財政課長","answer":"名前はちょっと差し控えますが、やはりほかの都心区では、大規模な再開発事業が幾つか集中したために、不交付区、ないしは非常に財調が減りそうだったんだけれども、今年はそれなりの需要が交付金にあらわれたという区もありますので、冒頭申し上げとおり。","voiceIndex":25,"id":"exchange-010"},{"speaker":"川西委員","kind":"質問・要望","question":"有効期限のことを、もう１回、説明していただきたいんです。","respondent":"桑村人事課長","answer":"これは、いわゆる区長・区議選を意識してございまして、その意味では、一定のところでつくりかえるというのを意識しているものです。その意味で、４月末ですけれども、１月程度はつくるのに時間がかかるかと考えています。ほんとうは４年程度で有効期限にしようと思ってあります。","voiceIndex":31,"id":"exchange-011"},{"speaker":"林（宏）委員","kind":"質問","question":"僕のカードは議員証と部屋のと。今、最後にちらっと議員証のほうも言ったんですけれども、全く形が同じになるんですか。それから、せっかくマルチに使えるカードなら、部屋のあれも一緒にしてくれるとありがたいと思うんですけれども、なるんですか。","respondent":"桑村人事課長","answer":"デザインにつきましては、職員のほうにつきましては、基本的に提示のことがかなりありますので、その意味ではっきりするような形にいたしましたけれども、議員証については、特に変える予定はございません。","voiceIndex":33,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"確認","question":"これは確かじゃないんですけれども、僕が持っている議員証というのは、見ると同じなんだけれども、本人の住所は入っていないんですよね。あるところで、住所がないと本人の確認証にはならないと言われるんだけれども、その心配はないんですか。","respondent":"桑村人事課長","answer":"いわゆる、生年月日と職員番号、私どもの言っている認識番号、それと、有効期限がいつまでか、この名前の職員が私どもの区の職員であるということを証明するという部分で、たまたま住所が必要な要件の何か証明書を取る場合には、これは使えませんというか。","voiceIndex":35,"id":"exchange-013"},{"speaker":"林（宏）委員","kind":"確認","question":"実は、区役所で言われたんです。これでは、あなたを証明できませんと。住民票のところで、今、必要でしょ。住所が入ってないと、確認ができないそうですよ。議員証は、前に１回、そういう話が出て、住所を入れようと。こっちは、そういうことで、住所がなくて、職員を証明するということだけで、これが使えるのはどことどこなんですか。それもセキュリティに入るか。","respondent":"西島経理課長","answer":"部屋のレイアウト上、真ん中が仕切れない課もありますので、その場合は、両課が併用して使っているような教育委員会の例みたいなこともありますけれども、基本的には、閉庁後の入退庁、それから各課の一番最後、最初の出入りの際に、そのカードを当てると、そこで記録が残る。","voiceIndex":37,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問","question":"それ以外に、いわゆるパソコンを開けるとか、そういうところまでのセキュリティには使ってないということなんですか。そこまでやる必要がないんですか。","respondent":"桑村人事課長","answer":"もちろんＩＣチップが入ってありますので、相当、いろいろなことに使えるということは、また別途の検討になろうかと思います。今現在は、いわゆるパソコンですとか、違う意味でのセキュリティに使っているものではございません。","voiceIndex":39,"id":"exchange-015"}]},{"id":"topic-02","title":"３の公職選挙法の一部改正","agenda":"３の公職選挙法の一部改正","exchanges":[{"speaker":"土井委員","kind":"確認","question":"ちょっと確認したいんですけれども、不在者投票の期日前投票制度に関連する問題で、今までの不在者投票の場合は、二重袋に入っていまして、選挙当日に上袋を開けて入れるわけですね。もしその間にお亡くなりになったりした場合は、どう扱っていましたか、私ちょっと記憶がないんで。今までも、そうなっていましたっけ。すみません、ちょっと確認させてください。","respondent":"野田口選挙管理委員会事務局長","answer":"今回の期日前投票は、投票する時点で選挙権がある人が対象です。逆に言うと、今までですと、選挙期日に満２０歳になれば、その前でも不在者投票ができたんですけれども、今回の選挙期日前投票というのは、そのときに２０歳になっていないと。","voiceIndex":45,"id":"exchange-016"},{"speaker":"土井委員","kind":"意見","question":"私のように端的な言い方をすれば、今までですと、投票までにお亡くなりになって、区に届出がありましたという方については、もう抜いちゃったと。今回の場合は、この期間中に、お亡くなりになるような方は、当然２０歳を過ぎた人と考えれば、もう投票をしてしまったから抜くことはないと、そういう形になるということですね。","respondent":"野田口選挙管理委員会事務局長","answer":"簡単に言えば、そのとおりです。","voiceIndex":47,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"提案","question":"不在者投票という言い方がおかしいじゃないかと、投票日になる前に投票してもいいという仕組みが入っているんだから、投票日と呼べばいいんじゃないかという提案をしたことがある。この期日前という言い方なんだけれども、パンフレットを開いたところの左の一番上に、「選挙期日前」と書かれているんだけれども、選挙期日というのは、どの日を言うんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"選挙期日は、従前、投票日のことです。","voiceIndex":49,"id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりました。そうすると、今度は、こっちのいただいたレジメの表の中の「投票期間」というところに、「選挙期日の公示または告示の日の翌日から選挙期日の前日まで」と書いてあるんだけれども、選挙期日の公示という言い方が正式な言い方なんですか。それは、選挙に立候補をする届け出での日じゃなくて、その日に選挙期日、いわゆる投票日の公示をするということなんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"投票日のことを選挙期日と言うんですけれども、例えば、区議・区長選挙の場合には、選挙期日前より７日前に告示しなさいと。","voiceIndex":53,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"説明は、よくわかりましたが、ここに書いてあるのは期日の公示なんですか。投票日の公示なんですか、そうじゃないんですよね。","respondent":"野田口選挙管理委員会事務局長","answer":"俗に言う投票日なんですけれども、公示するときには、例えば選挙期日は４月２７日とか、そういうふうに公示する。","voiceIndex":55,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、その日が改めて投票日が決まる日ですよというふうに、我々は受けとめていなければいけないということになるわけですね。では、改めて別のあれで聞くんですけれども、そうすると、選挙が始まるのは、公示、告示の日からかな。もう１回、別の意味で言います。そうすると、選挙期日前というのは、選挙期間中とは違うというニュアンスになるんだけれども。","respondent":"野田口選挙管理委員会事務局長","answer":"選挙期日前というのは、告示日、公示日の翌日から投票日の前日までの間に選挙期日前という位置づけの投票というふうに位置づけたということで、ちょっと従前の不在者投票を、選挙期日の投票所と同じような形で位置づけるために、わざわざこういったネーミングをしたです。","voiceIndex":59,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"十分にわかっているつもりなんです。だったら、僕は投票日でいいと思う。あるいは、投票日前投票のほうが、有権者にはわかりやすいと思う。選挙期日前投票というと、選挙が始まる前から投票ができるものととれるじゃないですか。僕は、選挙する人に混乱が起きるんじゃないのかなと思うんですけれども、その辺は、これからＰＲをするんだろうけれども、どうでしょう。","respondent":"野田口選挙管理委員会事務局長","answer":"投票日を１週間にすればいいじゃないかというのが極論なんですけれども、そうなると、また選挙権とかいろいろな問題が出ますので、そういった意味で、選挙期日前に不在者投票と同じ理由で投票日当日に投票所に行けない方を対象に、選挙期日前投票というものを設置したと。","voiceIndex":61,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"意見","question":"では最後にします。ここに上に小さい字で書いてあるほうが、こういうふうに言ったほうが、区民にはわかりやすいと。それからもう一つ、さっき、土井委員からも話があった、投票所に行って、投票用紙に名前を書いて、ＡさんがＢ立候補者に投票したというのがわからないようにするシステムですよね、無記名投票というと。それはどうクリアしていますか。","respondent":"野田口選挙管理委員会事務局長","answer":"今回の期日前投票になると、当日の投票箱に入れるのと同じですので、だれに入れたかわからないということになります。","voiceIndex":63,"id":"exchange-023"},{"speaker":"林（宏）委員","kind":"質問","question":"でも書いてあるじゃないですか、入れた袋に。","respondent":"野田口選挙管理委員会事務局長","answer":"今までのことで言えば、どういうふうになるかというと、内封筒、外封筒をなしにする。","voiceIndex":65,"id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"なしにするんですか。じゃあ、危惧している人の意見が通ったわけだ。","respondent":"野田口選挙管理委員会事務局長","answer":"そうです。書いて投票箱に入れるという、そういう簡素化です。","voiceIndex":67,"id":"exchange-025"},{"speaker":"川西委員","kind":"質問","question":"ですから、期日前の投票箱が、そのまま本来の投票日に投票所に移動する、そういうイメージでいいんですか。それからもう一つ、立会人の数、今まで、推進委員の方が交代で出張所に詰めていたように思うんですが、立会人の数が変わらないのかどうか。したがって、国で決めたことだからいいでしょうけれども、経費の点で、立会人の数が変われば違うし、職員の立会いがどうなるのか教えてください。","respondent":"野田口選挙管理委員会事務局長","answer":"投票箱の数ですけれども、これまでは、投票日当日で４３カ所ありました。今度は、投票箱が１３地域センターと本庁ですので、１４カ所ということで、投票箱が４３から１４増えて、開票所に５７個送られるというイメージです。これが１点。","voiceIndex":70,"id":"exchange-026"},{"speaker":"川西委員","kind":"質問","question":"わかりましたけれども、その管理者といいますか、責任者というのはどういう方がなるんですか。","respondent":"野田口選挙管理委員会事務局長","answer":"投票所と全く同じでございまして、当初、私どもが実務的に考えたのは、例えば地域センターの所長にやっていただければ一番いいと思っていたんですけれども、それですと、選挙が適正に行われているかどうかを常に監視しなくちゃならない。","voiceIndex":72,"id":"exchange-027"},{"speaker":"川西委員","kind":"質問","question":"そうしますと、４３投票所のときには、管理責任者という立場の方は、区の管理職か何かの方じゃないんですか。〔「違う」と呼ぶ者あり〕違うんですか。そうしますと、実際の投票日の管理責任者と同じ条件を持つ方を配置するという理解でよろしいんですね。","respondent":"野田口選挙管理委員会事務局長","answer":"全く投票所と同じというふうに考えていただければと思います。","voiceIndex":74,"id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと２点ほど聞きたいんですけれども、一つは不在者投票、公示または告示の翌日からということで、告示、公示の日が受け付けをやっているからということだったんですけれども、選挙の制度を拡大していくという角度から言うと、公示の日、告示の日でも、投票というのは可能じゃないのかと思うんです。そこのところは、なぜ、告示、公示の日はだめなのかというのはよくわからないんですね。","respondent":"野田口選挙管理委員会事務局長","answer":"選挙期日に投票というのが基本であって、選挙期日前投票ということで制度を拡充してきましたと説明しましたけれども、選挙期日前投票というのは、投票所と全く同じという考え方なんです。","voiceIndex":76,"id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ここで言ってもしようがないので、一応、私の感想と要望です。もう一つは、不在者投票の代理記載の制度なんですけれども、あらかじめ市町村の選挙管理委員長に届け出るということなんですけれども、いわゆる本人の意思確認といいますか、そういうのはどういうふうな形で行われるようになるのかよくわからないところなんです。そこのところはどうでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"この制度は、冒頭に説明しましたように、かつて昭和二十何年時代に、郵便投票制度というのはありましたけれども、不正がたくさん見られたということで、現行のような厳しい制度になったわけです。","voiceIndex":78,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"確認","question":"政令が出てからということなんですけれども、要介護５というところまでクリアして、これは非常にいいことだと思うんです。逆に、意思確認というのは非常に難しい。今言ったように、意思と違うことが出てきやしないかというのはちょっと心配だろうと思うんです。政令等ができたら。","respondent":"野田口選挙管理委員会事務局長","answer":"それと、代理記載制度を導入したということとはまた別です。要介護度５の人が代理記載制度が該当するということとはまた別個ですので、よろしくお願いいたしたいと思います。","voiceIndex":80,"id":"exchange-031"},{"speaker":"宮崎委員","kind":"確認","question":"確認するんですが、要介護５の人だからといって、イコール代理記載制度にいくというわけじゃないんですね。","respondent":"野田口選挙管理委員会事務局長","answer":"すみません、説明がちょっとあれですが、代理記載制度の導入の改正後のところで、下のほうで※が書いてあると思うんですけれども、「身体障害者手帳に上肢又は視覚の障害程度が１級として記載されている者」が対象となるです。","voiceIndex":82,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"確認","question":"確認だけしたいと思います。区のセキュリティについては、来たというのが感知できるんですか、そういうシステムがあるんですか。Ａさんが訪ねてきたとか、Ｂさんが来たというのを表示してくれるようなセキュリティになっているんですか。ただ、結果的に入っていないということですか。自民党のは、何々が来ましたというふうに一つ一つ表示が出るんです。どういうようなセキュリティなんですか。","respondent":"田中情報システム課長","answer":"当然、ウイルスをブロックしますと、そのものについて記録が残りますので、非常にウイルスが飛び交う時期になりますと、大体１月に５０件ぐらいブロックした記録等が残っております。基本的には、そういう形でブロックしているということがわかるようになっています。","voiceIndex":89,"id":"exchange-033"},{"speaker":"林（宏）委員","kind":"意見","question":"ただ２３区間に温度差というがあるのは否めないところだろうと思うんです。品川区はおそらくそっち側の考え方の最先端というか、先頭を引っ張っているような形なんだろうけれども、清掃のことに関するとより鮮明になるんだけれども、財調に関して、その辺の２３区間の温度差というか、そんなものについても、ちょっとお話をしてもらえますか。","respondent":"市岡企画財政課長","answer":"所管事務調査ということで、少し踏み込んだ言い方をすると、２３区の中はかなりの温度差がありまして、これは、交付金が多いか少ないかということもそうなんですが、基本的には、徴税の負担とか、リスクを負わないで配分を受けることができる交付金ですから、そういう意味では。","voiceIndex":100,"id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"一番最初の報告をされた数字と、それから検討会で検討されて、失礼な言い方をすると、課長会の段階で最終決定するようなことはない思うんですよね、手続の上から言って。その後、どこらあたりで、どのぐらいの時期にという、そういうようなことは、全体で話されているのか、品川区としてお考えを持っているのか、その辺もちょっと聞かせていただきたい。","respondent":"市岡企画財政課長","answer":"各検討会によって、若干あれがありますけれども、大体、そういうスケジュールです。","voiceIndex":102,"id":"exchange-035"},{"speaker":"林（宏）委員","kind":"質問","question":"税制の中でちょっと仕組みが違うという説明はあったけれども、いわゆる交付金として出していくということは、国も同じような形をとっているとすれば、２３区にとって、いろいろなことを主張する、特に品川区の主張をしていっても、なせばなるはないだろうというようなあきらめじゃなくて、ほかの何区か、半分ぐらいの区にとっては不可能な数字になってくるというのは。","respondent":"市岡企画財政課長","answer":"なかなか大きな問題だと思うんですが、まず、今度の都区検討会が何のために設けられたかというと、基本的には、平成１２年度の宿題を解決するというのが、まず最初の出発点です。","voiceIndex":104,"id":"exchange-036"},{"speaker":"林（宏）委員","kind":"意見","question":"平成１７年度末に、まさしく清掃に関しては、きちんとしたというか、暫定的でも、１回形をつくらないとならない中で、区長会の決定が大きく財調とも絡んでくると思うんです。そういうことを、ちょっと検討会の所属が違うので、どこまでというのはありますけれども、清掃がらみということを絡めていくと、財調問題は、タイム的に非常にタイトになってくるというのは、どういうふうにお考えになっているのか。","respondent":"市岡企画財政課長","answer":"東京都も、そういうふうに入口で何か紛糾させて、いろいろな議論を先送りするということのないようにやるべきだということを、連絡調整会議も含めて、３検討会の調整も何度もやっていますので、そういう場を通じて、まだまだこれからの話ですけれども、基本的な考え方としては。","voiceIndex":106,"id":"exchange-037"},{"speaker":"築舘委員","kind":"質問","question":"ですから、そこをかなり２３区が一致団結していかなければいけないところなんだけれども、温度差があるために、清掃問題にしてもそうですけれども、ある意味では、区長、助役レベル、それぞれあっていいんですけれども、そこがしっかりとしてないと、部長、課長の検討会だけして、結局は何かわからないうちにずるずるになってきて時間切れですと、それで終わりましたというんじゃ。","respondent":"市岡企画財政課長","answer":"往々にして、都区でいろいろ協議をすると、委員、おっしゃられたような懸念が生じる会議体もあるんですが、財調をめぐる検討組織については、これまでもそうなんですけれども、本来であれば、都区協議会。","voiceIndex":108,"id":"exchange-038"},{"speaker":"土井委員","kind":"質問","question":"本来はうちのだけれども、向こうにやっているんだとか、逆の意味で、これだけ労が少なくても我々のものなんだとかいう、何か共有の部分がよくわからないでもやもやとした感じの表現の中で、精神的な意味も含めて何となく説得されて、そうかななんて思っている人もいるらしいということ等があるものですから、その辺はどうなんでしょうかというのが１点あります。","respondent":"市岡企画財政課長、中尾根企画部長","answer":"つまり、ちょっと言い方を変えますと、役割分担に応じて財源を保障するんだけれども、都が、これが自分の役割分担だと説明できる事務以外に、この財源を充てることはできませんと。ただ、僕らの態度は、もしこの表現でいくとすると、調整税を、区と都の共有財産と位置づけた上で、その一定割合を都の固有財産として２３区が保障すると、せめて、そういう表現だと、そういうことでなければならないというのが。","voiceIndex":110,"id":"exchange-039"},{"speaker":"土井委員","kind":"確認","question":"さらにそれが、先ほどちょっと言った、東京二十三区清掃一部事務組合のあり方の問題等々の中にも、共有財産でやっていた仕事の共有財産で手に入れた工場なんだから、共有の財源で買ったんだから共有財産なんだということなんではなかろうかと思うんですけれども、そういうような意味の表現をされている、かなり議会答弁等でやられている方もいらっしゃるので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-040"},{"speaker":"林（宏）委員","kind":"質問","question":"ちょっと一つだけ、入門として聞かせてほしいんですけれども、このあいだも、聞きこそなったんですが、東京都、道府県と違う、首都だから都なんだと。その東京都というところに２３区と多摩地区がありますよね、市町村がある。あそこは普通の市ですか。そこと２３区と、なぜ制度が違って首都として、戦後、こういうふうになったのか。今の２３区というのは、どういう位置づけで生れたんですかね。","respondent":"市岡企画財政課長","answer":"しかし、東京２３区というのは、経済的、あるいは都市構造的な実態がどうなっているのかは別にして、戦後、２３区制ができたときには、そこが一つの大都市を形成しているという実態と構造があったという理解で、一時、普通地方公共団体でしたけれども、特別地方公共団体として。","voiceIndex":117,"id":"exchange-041"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、都と２３区というのを考えるときに、議長会なんかでは、２３区は議長会に入ってくると大きい顔するから、発言は２年間控えてくださいというような、非公式な団体だから、入れちゃっているんだけれども、公式ないわゆる公共団体としての立場で話をしたら、そんな話は通じないことですから、これから多摩地区というのも、我々というか、２３区側としては。","respondent":"市岡企画財政課長","answer":"都区財政調整制度というのは、２３区が実態としても、構造としても、一つの大都市を形成しているということが前提になっていますから、人間で言えば、１人の人間のいろいろな機能を分かち合っているんだけれども、全体として一人の人間なので、右手がどう、左手がどうって。","voiceIndex":119,"id":"exchange-042"},{"speaker":"土井委員","kind":"意見","question":"今、この議論がされるときに、先ほどもあったんですけれども、東京都が我々のところで集める税金も、人を使って、金を使って集めているんだというのは、片方はやりますと。全部区のほうで集めします。何だったら、都税も集めますよと。だから、そういう発想まで含めて、最後はあるんですよという意気込みがないと、どうも進まないんじゃないかという気がするんですけれども。","respondent":"市岡企画財政課長","answer":"先ほどの役割分担論ではありませんが、都がどうしてもある一部の事務を一体的、統一的に都の責任で行わなければいけないというものがあるんなら、それは区から都に事務の委任、委託をしてやっていただくという関係でもよろしいんじゃないですかと。","voiceIndex":124,"id":"exchange-043"},{"speaker":"土井委員","kind":"質問","question":"先ほど、私が言ったのは矛盾するような発想なんだけれども、でもそんな思いがないと、解決しないなと思いました。自由にということだったものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-044"},{"speaker":"宮崎委員","kind":"質問","question":"なかなか難しくて、私も改めていろいろなところで、清掃は移ったけれども、金はわたさないとか、そういった攻防をやっているのは、一つ伺いたいんですが、先ほど都の役割で、これはちゃんとやっているんだというふうな説明がつかないものは、財政を保障するものじゃないという説明があったんですけれども、今まで、５２％、４８％の役割の中で、区にわたす分というのは、あくまでも区の積み上げできていて。","respondent":"市岡企画財政課長","answer":"同じことを、例えば我々が区議会で、これはどういう財源がどう当たっているかよくわからないけれども、まあ全体としては帳尻は合っていますなんていう説明をしたら、これはおしかりを受けるのは当たり前のことですから、ぜひ、今度は、そういう説明はしてくださいと。","voiceIndex":127,"id":"exchange-045"},{"speaker":"宮崎委員","kind":"質問","question":"どこかでやっぱり決着をつけなきゃいけないところはあるかと思うんです。それは、今やるべき問題じゃないとか、今は避けながらとかいうことがあるかと思うんですけれども、そういう議論の中で、じゃあ、４８％の根拠は何なのかと、こういう議論というのは、逆に区側のほうからやっていったら、これはまたやぶ蛇になっちゃうんでしょうか。","respondent":"市岡企画財政課長","answer":"そこが、まさに我々が主張しているところです。具体的な方法論は別にして、４８％の説明責任、これが今のところ、区側の合言葉になっています。各検討会では、それをそれぞれ主張しているという状況です。","voiceIndex":129,"id":"exchange-046"},{"speaker":"林（宏）委員","kind":"意見","question":"この検討委員会、新聞に出ている。新聞だと、当たりさわりがないように書かれるので、議論の内容を委員会で報告をする、内容を報告するというか、方向を我々に見せてくれればいいわけです。見過ごしちゃうことがあるからね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1624#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":53872,"voices":135}},{"id":"h15-20030827-12","meetingId":"h15-cm08","date":"2003年8月27日","dateIso":"2003-08-27","committee":"清掃制度特別委員会","time":"午後１時０３分～午後 ４時１６分","status":"正式会議録","sourceType":"formal","overview":"清掃制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5622#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=12&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":534,"voices":4}},{"id":"h15-20030827-16","meetingId":"h15-cm08","date":"2003年8月27日","dateIso":"2003-08-27","committee":"街づくり特別委員会","time":"午後１時０４分～午後４時４６分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"連続立体交差事業が、平成１９年秋までに延期されたということで、大きな意味での、工事のおくれの原因をひとつ教えてほしい。２点目は、武蔵小山駅前の用地買収がおくれている、なぜ、今現在まで土地が手に入らないのか、用地買収おくれの原因を教えていただきたい。","respondent":"中島街路事業担当課長","answer":"連続立体交差事業の事業期間は、平成１９年春完成の見込みです。おくれた原因は、先ほど、東急電鉄の工事事務所でのご説明の中にもありましたけれども、いわゆる、連続立体交差事業をするに当たって、用地買収、あるいは用地の借用というのが、当然、必要になってあります。","voiceIndex":7,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"武蔵小山駅前の９棟のおくれのところは、行き違いがあったということですが、私も、何人かの方からお話を伺ったことがあるんです。移動して、今までどおりの営業ができるかといったら、ほんとうに死活問題ですから、その点は、気持ちはだれでもわかると思うんです。きちんとした話し合いが、この間、あまり積み重ねられていないという声も伺ったので、ちょっとこの間の経過をお聞かせいただきたいんです。","respondent":"中島街路事業担当課長","answer":"もともと発端は、事業認可前にさかのぼってしまうんですけれども、そういった中で、現在の計画に固まるまでの段階も、若干変更になったというようなこともございまして、途中で、今の９棟の部分については、駅前広場から外すという案も、一時はありました。","voiceIndex":9,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"長い月日が経っているので、いろいろなことがあったんだろうなと思います。年に何十回も訪れて話し合いをしているというんですけれども、具体的にどういう話がされているのか、もうちょっと聞きたい。もうちょっと、何十回も訪れて話し合いをしているという、その中身を聞かせていただきたい。","respondent":"中島街路事業担当課長","answer":"例えば平成１５年度で言いますと、権利者は随分いますけれども、１００回以上伺っているわけです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"先ほど、資料２のところで、平成１５年度に青から赤に微妙に色が変わっていて、この辺のあたりが、立ち入り調査とか、そういうものが始まったということのあらわれなんですか。色の変わっている任意交渉というあたりが、そういうところなんでしょうか。","respondent":"中島街路事業担当課長","answer":"その辺も含めてです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実際に、何とか営業を守っていきたいという立場ですので、私はやっぱりほんとうに営業ができる代替地を探してほしいなと思います。１点なんですけれども、この図面で見ると、補助２６号線から入った補助３２０号線と書いてあるこの一角に、へこんでいる地域がありますよね。ここに移りたいという声もあったんで、その辺はどうなのかなというのをちょっとお伺いします。","respondent":"中島街路事業担当課長","answer":"その間、いろいろな形で計画変更されてありますので、先ほどもお答えいたしましたように、今、９棟と言われている部分が入っていなかった絵も、確かに昔、ございました。さまざまな計画の中で、現在の計画に決定したです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"金高委員","kind":"質問","question":"果たして、それだけでもって収容するだけの東急のほうでなされるかどうかということもあると思いますので、その辺は、別の観点からするという形で、せっかくこれだけの事業をやるんですから、その辺をもう少し深く落とし込んだ形の計画を作成するのもいいのではないかという気がしたんですけれども、その辺のところはどうでしょうか。","respondent":"中島街路事業担当課長","answer":"近々、それぞれ駅の両側に２カ所設置する必要があるかということも含めて、検討する材料として、実際に、利用者の動線、動向というんですか、どちから何台ぐらい来ているのかという調査をいたしまして、それをもとに、箇所数、台数も含めて。","voiceIndex":17,"id":"exchange-006"},{"speaker":"金高委員","kind":"質問・要望","question":"今の街路事業担当課長の話のとおり、１カ所より２カ所、その分だけ台数が増えるわけですから、やはりそういう面では、積極的な発言をしていただいて、１台でも多く。そういうのを、まず利用者に対して一番利便性の高い状態であれば、１台でも多く設置できるような形での、これからの取り組みをしていただければと思います。これは要望で、見た感じを述べさせていただきました。結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"といいますのは、当然、東口にだけできれば、なぜ西口にないんですかと、地元の方はおっしゃるでしょうから、将来的な計画も含めて検討されないんですかということを、ちょっとお伺いしたいんです。それから、昇降機設置についての費用負担、どこがどれだけお金を出してという形で、品川区は当然お金を出していくんでしょうけれども、どうなっているんでしょうかということをお答えください、お願いします。","respondent":"中島街路事業担当課長","answer":"武蔵小山駅の東口に設置するということになりましたけれども、先ほども申し上げましたように、こちらにつきましては、仮駅舎につける仮エスカレーターですので、そういった意味では、費用については、なるべくかからないように、あるいは、事業に影響のないように。","voiceIndex":20,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問・要望","question":"どう言ったらいいんでしょうか、民間の感覚からすると、相当いいといいましょうか、ある意味では補助制度があるからできる話なんでしょうけれども、６,０００万円の価格のことを考えていくと、使うのは２年間ですよ、２年間使うのに６,０００万円投資をしていくという考え方が、どうも感覚として高すぎるんじゃないか。","respondent":"中島街路事業担当課長","answer":"言ってみれば、たった２年で６,０００万円、１年３,０００万円ということになるわけですから、これがほんとうに必要なのか、どうなのかということで論議になりましたけれども、先ほどもご説明いたしましたけれども、事業期間が延びてしまうということと。","voiceIndex":22,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"これは仮駅舎につけるものというご説明ですので、２年過ぎたら取り壊しするわけですよね、単純に。要は、６,０００万円のお金をかけてつくったものを２年しか使わない、それを取り壊してしまうというような話ですけれども、エスカレーター自体のリサイクルと言ったらいいですか、２年間で寿命がくるとは、私は思わないんですよ。非常にもったいない気がするんですが、いかがでしょうか。","respondent":"中島街路事業担当課長","answer":"私ども、最初にこの検討に入ったときに、仮設ということで、設置して、それをまたどこかで転用可能じゃないかということも含めて、検討させていただきました。","voiceIndex":24,"id":"exchange-010"},{"speaker":"伊藤委員","kind":"意見","question":"まとめますけれども、ぜひ、そういう観点を考えてほしいんですよね。確かに、補助金が出るから進めていくんですけれども、２年間で６,０００万円という投資をして、ただ壊してしまうというのは非常にもったいないですよ。やっぱりそれをどこかでリサイクルするなり、対応していくことのほうが、税金の有効活用につながっていくと思われますので、ぜひ検討してください、お願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-011"},{"speaker":"武内委員","kind":"意見","question":"多分、おそらく変わらないと思うんですが、そうすると、今、その道路を抜けて踏切のほうに出ていくと、車は左側に一方通行になっていますけれども、そういう意味じゃ、今のところ、地下化されても変わらないというのは、まだそこまでは話は出てないということですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-012"},{"speaker":"藤田委員","kind":"意見","question":"先ほども出ていました昇降機の関係なんですけれども、武蔵小山駅の乗降客の調査をしたという話ですね。１日に、武蔵小山駅を利用する人たちというのは何人いらっしゃるのか。そのうちの７割ということですが、その人数がもしわかれば。","respondent":"中島街路事業担当課長","answer":"休日のほうは、やはり合計で２万８,５９３人の利用者がございまして、そのうち２万８１７人が東口、西口が７,７７６人ということで、東口利用者が７３％、西口利用者が２７％という状況です。","voiceIndex":30,"id":"exchange-013"},{"speaker":"藤田委員","kind":"質問","question":"２年と言えども、１日に４万の人たちが階段を使っているという実態を、やっぱり我々は認識していかなきゃいけないと思うんです。昇降機についても、通常、早朝とか、深夜だと人が全くいない場合がありますよね。そういうときに、とまっているという省エネというんですか、そういうエスカレーターもあるわけですけれども、これについては、どういうことになるんでしょうかね。","respondent":"中島街路事業担当課長","answer":"基本的に、よく日本の施設で、人が来ると動くというようなエスカレーター等がありますけれども、今回設置するエスカレーターにつきましては、営業時間帯については、常に動いているというものです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"藤田委員","kind":"質問・要望","question":"これは答えるのが大変だと思いますから、要望にしておきますけれども、そういうこともひとつ頭に置いて、ぜひ、お願いをしたいなと思います。それからもう１点、連続立体交差事業の今後のスケジュールの中で、電線類の地中化設計委託とありますよね。武蔵小山駅も西小山駅もありますよね、これは広場のエリアだけに限って地中化にしようという考えなんでしょうか。","respondent":"中島街路事業担当課長","answer":"現在、私どもで計画しているのは、駅前広場事業は、武蔵小山駅にしても、西小山駅にいたしましても、それぞれ補助３２０号線、補助３０号線という、いわゆる街路事業の一環としてされているものですので、もちろん、道路部分につきましてもそうですし。","voiceIndex":34,"id":"exchange-015"},{"speaker":"藤田委員","kind":"質問","question":"武蔵小山駅についても、補助２６号線ですよね、両方が非常に狭い歩行者道路になっていますけれども、あれもやはり狭くしているのは電柱なんです、両方にだあっとあるわけですから。この際、もう間に合わないんですかね、平成１５年度ですから。技術的によくわかりませんが、もしお考えがあれば、この際に、電柱の地中化の設計をやっているわけですから。もしわかればで結構です、わからなければ結構です。","respondent":"中島街路事業担当課長、中谷まちづくり事業部長","answer":"２０５号線のほうでも着手しておりますし、１６３号線につきましても、整備する段階では、すべて電線の地中化を図るということで、まずは都市計画道路事業に関しましては、電線の地中化を図っていくということで、現在。現況、今、１６ｍの道路になっておりますが、計画幅員が２０ｍになっておりまして、ちょうど東側の部分が４ｍ拡幅される予定になっております。そういう意味で、ここの早期整備を要請しております。","voiceIndex":36,"id":"exchange-016"},{"speaker":"藤田委員","kind":"質問・要望","question":"これを一つの起爆剤じゃありませんが、ひとつここでやろうという考えがあるわけですから、やっぱりそれに連動してやるべきじゃないかなという発想があったものですから質問したわけです。ぜひひとつ、そういう意味で、積極的に取り組んでいただきたいと、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"確認","question":"地中化に絡んでつながりが出てくると思うんですけれども、工事のやり方の確認なんです。西小山駅の近く、５８ｍが地中化になっていきますけれども、この資料が平成９年ごろのものなんで、ちょっと状況はわからないんですけれども、反対の目黒側の延長約１８０ｍの工事はもう終わっているんですか。状況がわかりますか。","respondent":"中島街路事業担当課長","answer":"そういった意味で、若干、用地買収がおくれているということで、おそらく、駅前広場の事業のほうが先に終わってしまうのではないのかなと考えています。相当難航していると聞いておりますので、なかなか、今、厳しい状況になっているという状況です。","voiceIndex":40,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"基本的に他区のことだから、あまり言えない、各区、進展状況というのは違うのかもしれないけれども、せっかくここがつながっているんだったら、同時にやっているのかなというのがあったので、同時にやったほうが、交通の流れですとか、費用的なものも安くなるのではないかなと。他区の状況ですけれども、基本的には地中化という方向に向かう場所だということでいいわけですか。","respondent":"中島街路事業担当課長","answer":"こちらの駅前広場の事業ですが、基本的に、先ほど申し上げましたように、補助３０号線の整備事業ということで、目黒区も含めて一体として事業化を図っているところです。","voiceIndex":42,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"最後に、ここに関して、今、用地買収がおくれているということですけれども、これが同じようなペースで進んだときは、基本的には工事は同時並行で進めていくというのが、他区との関係でも同じということですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-020"},{"speaker":"木下委員","kind":"質問","question":"安全性の面から、商店街ですとか、人の多いところだけではなしに、震災ですとか、東京都内の中で品川区は危ないと言われていますから、細い道路ですとかが網の目のように連なっている道が多いものですから、震災面でも、地中化ですとか、そういうお考えがあるのか、どうなのか。","respondent":"中島街路事業担当課長、中谷まちづくり事業部長","answer":"単価ですけれども、駅前広場につきましては、まだこれから設計の段階ですので、具体的にございませんけれども、平成１４年度に補助２０５号線、約２００ｍの区間の工事の中で、本管を設置する工事がございましたけれども、たしか。現在、大井方面の東西を結ぶ道路というのが非常に少のうございまして、滝王子通りが大井競馬場、あるいは大井ふ頭方面への非難道路ということで、その路線につきましては、周辺を固い建築物を建てるということで。","voiceIndex":45,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"このパンフレットはよくできているなと思うんですが、つくられたのを見ると、大体平成９年とか、７年とかということで、かなり経っちゃっているんですよね。延びましたよというような通知ですが、そこら辺は、どういうふうにされているのかなとお聞きしたいんです。","respondent":"中島街路事業担当課長","answer":"特に武蔵小山駅前広場、あるいは西小山駅前広場関係の地域センターが、荏原第一地域センター、それから荏原第二地域センターが管轄していますので、そちらには、定期的に事業の進捗状況を、町会長の皆さんにご説明をしています。","voiceIndex":48,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"定期的に、年に１回とかだけでもしていただければ、あとは回覧等々を。品川区の事業としては、かなり皆さんのためにいろいろやっていますというような、そういうこともどんどん知らせていくということが必要ではないかなと思っているんですけれども、その辺、いかがでしょうか。","respondent":"中島街路事業担当課長","answer":"今後ですけれども、先ほどお話ししました、詳細設計等に入ってきます、それからこれから工事に入っていく中で、また、当然、地域の皆さんにご迷惑をかけるということもありますので、工事説明会等で、また改めて直接お話する場も、これから出てくると考えています。","voiceIndex":50,"id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"ちょっと最後にお聞きしたいんですけれども、西小山駅のほうで、都市計画決定が昭和２１年と、さっきおっしゃっていたんですけれども、それは間違いないんですか。大分古い話なんで。","respondent":"中島街路事業担当課長","answer":"そのときに決定されたのがずっと生きていまして、この駅前広場事業に合わせまして、平成６年に、いわゆる都市計画を変更という形で、平成９年に決定を取り直したです。昭和２１年というのは、間違いございません。","voiceIndex":52,"id":"exchange-024"},{"speaker":"藤田委員","kind":"質問","question":"今のところで。きょうはせっかく防災課長が見えていますので、ちょっとお伺いしたいんですけれども、町会の防災資材置き場ですか、ありますね。各町会にあるのかどうかわかりませんが、防災の資材置き場ってありますね。〔「倉庫」と呼ぶ者あり〕倉庫ですか、あそこの中に、組立式のリヤカーみたいなものがありますか。","respondent":"久保田防災課長","answer":"土のうを運んでもらっているというのも、私、聞いたことがあるんですけれども、あまり大量に運びますと、やっぱりちょっと耐えられないかなというところがあるので、そこら辺は工夫してお使いくださいという形でお話させていただいているところです。","voiceIndex":59,"id":"exchange-025"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、今おっしゃったように、一つが非常に重いんですよ。だから、リヤカーでさえもちょっと危なっかしいということなんですね。皆さん、大変な思いをされたという声も聞きます。毎年、必ず集中豪雨はあるわけですから、とっさにそれが出て来ないと大変な思いでおられる。ぜひ、ひとつ検討していただきたいという要望、お願いしたいと思いますので、よろしくお願いします。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-026"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、この基準というのは、多分、例えば、目黒川沿いであったり、立会川沿いであったり、そういうような判断で決めたんでしょうけれども、今まで水害が出た地域は把握されているはずです。今、たまたま、南大井五丁目のさくら会のところに水が出ましたね。ですから、そういう過去の水害の被害と土のう置き場がどういうふうにリンクしているんですかということをお聞かせください。","respondent":"松代道路公園課長","answer":"ただ、今、委員ご指摘のところは、現在、設置されていません。ですから、こういったところも、各町会、地域センター等にいろいろと問い合わせをしながら、そういった場所の要望、もしくは必要な場所を、今後、さらに見極めて設置をしてまいりたいと考えているところです。","voiceIndex":62,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そんなに難しいことじゃないと思うんですね。今まで、水害が出た地域の記録が残っているでしょうから、それに合わせて、土のうを効果的に置いていく。それは、多分、スペースは取りますけれども、例えば悪臭が出るということでもないでしょうから、協力が得やすいと思われますので、十分、それは対処していただきたいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-028"},{"speaker":"木下委員","kind":"確認","question":"今、伊藤委員がおっしゃったのと同じで、私も、前回の大水の際に浸水被害のあった、豊町、二葉、西大井の地域に、こちらで見ると、全然土のうの置き場がないということで、この地図で書いてあるとおり、この地域というのは、全然土のう置き場がないんですか、ちょっと確認を。","respondent":"松代道路公園課長","answer":"今ここにある地図でお示ししたところの箇所ですので、今、委員からお話が出ました豊町等については、一番直近で言いますと、西大井広場等々でご利用いただくような状況にあります。","voiceIndex":65,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6260#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":27766,"voices":69}},{"id":"h15-20030828-14","meetingId":"h15-cm08","date":"2003年8月28日","dateIso":"2003-08-28","committee":"行財政改革特別委員会","time":"午後１時０８分～午後５時１２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を10件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"行財政改革に関することのうち、「電子区役所に関すること」","agenda":"行財政改革に関することのうち、「電子区役所に関すること」","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"今度のエムエスブラストはものすごい脅威となって、大田区でも一部感染したとかと報じられているんですが、これの影響と対策についてどうだったのか、全般的なことをちょっとお話しいただけるとありがたいんですが。","respondent":"田中情報システム課長","answer":"うちでは１台も感染しておりません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"ＬＡＮだと、ＩＰアドレスを振りかえてやっちゃうから入ってこないということなんでしょうか。区にはいろんな形でメールがＬＡＮを通じて入ってくるんだと思うんですけれども、日常的なセキュリティの対策、職員がやるレベルと、業者が入ってくるレベルといろいろあるんじゃないかなと思っているんですけども、どういう体制でやっているんでしょうか。","respondent":"田中情報システム課長","answer":"ということで、基本的には職員が日々やっていまして、毎月１回ぐらい定期的にマシン等の補修で業者が来るというような形になっております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"高星委員","kind":"質問・要望","question":"そこのところにいつ入ってくるかわからないという状況の中で、そういうふうなときに、こういうシステムが侵されてしまったとき、個人保護条例もあるけれども、庁舎内でそういった危機管理体制、あるいはそういうふうになったときに、どういった発動体制をとるのかということが、そこら辺のところはどういう体制をとられているのかということですね。その辺のところの考え方をちょっとお聞かせいただきたい。","respondent":"田中情報システム課長","answer":"こちらの４枚目のところの説明をちょっと割愛させていただいたんですが、「要綱および基準の骨子」という別紙がありますが、その管理体制というところで、全体のセキュリティ上というか、情報、セキュリティ上の統括運用管理者は企画部長になっておりまして。","voiceIndex":9,"id":"exchange-003"},{"speaker":"高星委員","kind":"質問","question":"時間の関係もあるんですけども。それから、先ほど来からお話を聞いていると、セキュリティホールそのものが毎日、日々発見されているということで、どんどんこれも際限なく、いわゆるコンピュータですから、そういう数であるんだろう、これからもまだまだ見つかってくるんだろうというふうに。いいんだと。","respondent":"田中情報システム課長","answer":"基本的には業務のダウンといろいろな障害でセキュリティ上の障害でダウンしたところについては、対応については、基本的にはフェールセーフという考え方で、二重三重に、例えば住民基本台帳のシステムが日々地域センターや何かで落ちると、大体のサーバーが立ち上がって。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど沢田委員のご質疑の中にも少し触れられておりましたけれども、職員体制というところの考え方で、これは行財政改革特別委員会ですので、全般的には職員の配置ということに関して傾向としては外部委託ということがいろんな分野でだんだん増えてきておりますが、このシステムの管理の部分については、非常に大切な個人情報も含めて多くの重要な情報を管理している部署ということで。","respondent":"田中情報システム課長","answer":"ただ、事務職ですので、一定の人事異動の季節がありますので、システムエンジニアの専門職ではありませんので、その辺は区の体制としてはちょっと限界があるかなと。","voiceIndex":13,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問","question":"今回のセキュリティ対策ということで、今日はあれになっておりますが、いわゆるウイルスというのは、全く予測もつかない全く新たなものですので、それを把握することとか、またそれに対するいわゆるワクチンと言われる対応するためのソフトの開発といいますか、というのは、そういう新種のウイルスに対する対応の部分で言うと、依存度というのはどれぐらいになるんでしょうか。","respondent":"田中情報システム課長","answer":"ですから、１００％ウイルスを世界中で網を張っているウイルスチェックのソフト会社が見つけて、すぐプログラムをつくって、すぐ配布する。うちのほうはそれをすぐ適用するという形になっております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"場合によっては全国一斉に、同時にこういったウイルスに侵されたときに、品川区だけ優先して対応してくれるのかどうかということも含めまして、そういう意味でのセキュリティ対策を対コンピュータ・メーカーなり、あるいはソフトウエア開発会社なり、管理会社なりとの関係も確立していくべきだと思うんですけれども、そういった部分でのちょっと考え方を最後にお聞かせをいただきたいと思います。","respondent":"田中情報システム課長、中尾根企画部長","answer":"そういうところも含めまして、なるべく特定のメーカーやベンダー等に依存しないような形で、オープンな形で標準的な技術やいろんな業者の方が仕事に対応できるような形のシステムをつくっていきたいというふうに考えております。このように毎日仕事についても、インターネットがなければ仕事ができないというようなことになったときのほんとうに保護というのはどういうことなのか、もう一回これは考え直す必要があるのではないかということで。","voiceIndex":17,"id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"そこは破られるかどうかについてテストをするというような、安全だということを前提にしないで、自分たちでもセキュリティ上問題ないのかという非常に念には念を入れた慎重な姿勢が、ちょっと報道を読んだんですけれども、品川区でセキュリティ会議をつくったりいろいろやっていても、何かやっぱりもう一つほんとうに大丈夫なのかなという不安があって。","respondent":"田中情報システム課長","answer":"その点で、ヨーロッパの政府の中では、既に採用したところがあるようですが、日本の政府もその辺の検討をしているというふうに聞いております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"一稼ぎするために自分の職務についていた問題を、データをあるところに流しちゃうなんていうことになると、規制の網がかからなくなっちゃう部分があるんじゃないかというふうにちょっと心配なんですけども、その辺は外部業者を入れた場合の責任体制というのは、どうしているんでしょうか。","respondent":"田中情報システム課長","answer":"厳格な住民基本台帳ネットワークシステムの運用等になりますと、業者が入る際、サーバー室等に入る際には、職員が立ち会うという、ふだんでもサーバー室に入る人は指紋で認証しないと入れませんし、ずっとカメラで作業内容を確認し続けるということになっておりますので。","voiceIndex":22,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"だから、委託に出すという、ある意味じゃ専門性が必要ですから、委託に出さざるを得ないというのはわかるんだけれども、さっき言った外からのやつと、内部から出ていく問題というのは、やっぱり両方目を光らすということが非常に大事だと思うんですが、例えば品川区の場合ですと、何かデータを外に持ち出すということは１００％ないことなんでしょうか、あり得ることなんでしょうか。","respondent":"田中情報システム課長、中尾根企画部長","answer":"地震等があって、こちらのシステムがすべてつぶれたとしても、データが補完して、すぐサービスが開始できるような形になっておりますので、まるまる例えば住民情報ですとか、税ですとか、国民健康保険や介護の情報はすべて日々最新の。だから、開発なんかでも、必ずしも全部場所的なものや人的なもののことで限度があるんですが、やっぱりそういう点をできるだけここの役所の中ですべてを完結してもらおうということだけは。","voiceIndex":24,"id":"exchange-010"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5736#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":16835,"voices":30}},{"id":"h15-20030926-4","meetingId":"h15-c-settlement","date":"2003年9月26日","dateIso":"2003-09-26","committee":"決算特別委員会","time":"午後４時０２分～午後４時１１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1210#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":2672,"voices":18}},{"id":"h15-20030929-6","meetingId":"h15-cm09","date":"2003年9月29日","dateIso":"2003-09-29","committee":"区民委員会","time":"午前１０時０４分～午後１時４６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区国民健康保険条例の一部を改正する条例","agenda":"品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"一つは、事務手続上簡素化されて８００万円事務経費が削減されるという状況、できるだけ簡素化するということは否定しないところですが、区民の方たちからの問い合わせが多かったということで、それをきちんと整理する意味もあるというお話なんですが、こういう方式で税額を算定するというのは、国保だけではなくて、区民税なんかはどういうふうなシステムになっているんでしょうか。","respondent":"松崎税務課長、太田保険年金課長","answer":"賦課の時期は、特別徴収の場合は６月から翌年の５月まで１２回。普通徴収の場合は４回、６月、８月、１０月、１月の４期で税金を納めていただくというシステムになってあります。それからなお、ちょっと冒頭説明を漏らしましたけれども、附属資料の６ページをお開きいただきたいと思うんですけれども、６ページの例が所得の低い方の例です。国民健康保険料で、いわゆる政策減額というのがあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"それで、率直に言って不況ですから、自営業者が大半ですよね。その辺がどの程度の負担になるのかなというところをちょっとよく見ておきたいと思うので、そういうところを伺いたいと思うんですけれども、一つは前年度から所得が下がっている人の割合、あるいは退職者がこの国保に占める状況というのはどのくらいあるのか、パーセンテージでいいですから、ちょっとそれを教えていただきたいと思います。","respondent":"太田保険年金課長","answer":"２点目の問題ですけれども、確かに１０期割になりますので、これは確かに１期割の１期の納める額というのは、これは上がる方もいらっしゃるということは間違いないんですけれども、じゃあ１２期にできるかというと、これは、やっぱり会計年度の関係で。","voiceIndex":8,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"９割の人が金額が変わるんだという話なんですが、その中で、上がる人がどのくらいというのはちょっと大雑ざっぱな数でいいですから、今までの通年で言ったらどういうふうになるのかなというのをちょっと教えていただきたいなと思います。それとあと、区民税が私の理解では６月から１２カ月で、国保と同じ徴収方法をしているわけですよね。そこについて、ちょっと確認をしたいんですけれども。","respondent":"太田保険年金課長","answer":"ただ、先ほど申し上げましたように、退職者の社会保険離脱等の部分がありますので、おそらく半分ぐらいの方は退職者を含めて、政策減額の方も含めて半分ぐらいの方については納めやすいといいますか、減になるのかなということで見込んでおるところです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"ちょっとよくわからないので申しわけない、長くなって悪いんですが、区民税は６月から５月です。だから、国保のときに上がったり下がったり、数カ月でまた切りかえて打ち合わせをしなくちゃいけないという、そういう煩雑さというのは、区民税の場合はどういうふうに消化しているのかなというのがわからないんです。あるのかないのか、ちょっとそこからわからないんですけれども、教えてください。","respondent":"松崎税務課長","answer":"したがいまして、特別徴収の場合は６月に賦課をして、５月までの間に１２回でお支払いをいただく。その間にその前年度の収入で、実はこれだけ少なかったとか多かったとか、扶養家族を取り違えていたとかいう場合には税額の変更はありますが、それ以外は変更はございません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"国保の今までの徴収方法というのは、３月までは前年度ですから、当然今年で言えば平成１５年度ですから平成１４年度までの収入所得で算定しますよね。ところが、４、５、６月は年度が変わるわけですから、平成１３年度のでやって、平成１４年度になるわけですよね。そうすると７月からは、ちょっとごめんなさい、数字がちょっとわからないので、とにかく前年度ですから３カ月でかわっちゃうわけですよね。","respondent":"松崎税務課長","answer":"ありません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"松澤委員","kind":"意見","question":"なるほど、前々年度で収入がこういう、リストラがはやったりしている、職を失ったりしたときに、すぐそれが反映されるというと、なるほど、このほうが事務も煩雑にならない、８００万円も事務が助かりますのでなるほどという気がしたんですけれども、これが何で今改正するのか、そうしたら、こんなことは昭和５６年、５７年……もう２３年近く前から同じ方式でやっていて、今ここで何で改正するのか。","respondent":"太田保険年金課長","answer":"その中で賦課の一体化ということで平成１１年度に検討をして、一定の考え方等も出ているところです。その中では、やはり被保険者にとって極めてわかりにくいという保険料の暫定賦課、本賦課２回の方式をやはりわかりやすいものにしていくことが必要だと。","voiceIndex":18,"id":"exchange-006"},{"speaker":"松澤委員","kind":"意見","question":"よく時代の背景がわかりました。品川区は何でも頑張って勉強してやっているのに、なんで一番にこういうことができないの。当然そういう話し合いはしてきたというならば、他区の様子を見てから始めたというのは、どうも品川区は遅いなと、いいことだったら率先して始めるべきではないか。区長ではありませんけれども、ここら辺を一つ。","respondent":"太田保険年金課長","answer":"正直申し上げまして、私が来たのが平成１３年ですので、その前の段階で、実際に検討していたのは、平成１２年度で１区が熱心に検討していたというところでございまして、その後で取り組みを本来すべきなんですが、ただ、昨年度、大きな医療制度改革もございましたし。","voiceIndex":20,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、そこではほとんど、今の話の中では１０カ月徴収だから１カ月分がちょっと上がってしまうよというお話はありますけれども、正確な保険料を納めるにはしょうがないかなという気もするし、そこが一つのネックなんでしょうけれども、ほかでは事務経費が減ったよとか、電話がじゃんじゃんかかってきたよということは、その点、ほかの区では何事もなく済んでいるのかどうか、あるいはまた反対に。","respondent":"太田保険年金課長","answer":"７月のときに、電話等の問い合わせはやはり減っているです。それから、１０期割になったということでの反応については、特に大きな、聞いていないというようなお声は出ていないです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"そういう中で、私が直接聞いた方たちは、１０カ月にすると高くなるからそれは困るというふうなお話をされました。したがって、相談等々について周知も十分丁寧にしていただきたいし、相談についても、今までも丁寧にしていただいたとは思いますが、やっぱりその辺の理解をしていただくための丁寧な個別の相談をしていただきたいということをちょっとあえて申し上げておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"}]},{"id":"topic-02","title":"第３８号議案 平成１５年度品川区一般会計補正予算、歳出の区民委員会所管分につきまして","agenda":"第３８号議案 平成１５年度品川区一般会計補正予算、歳出の区民委員会所管分につきまして","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"１点目の豊町二丁目の区民農園についてなんですけれども、今１,６５０万円で整備するということになると、平成１６、１７、１８、３年間ですよね。この間の後のランニングコストは幾らぐらい見ているんでしょうか。","respondent":"長田区民課長","answer":"そういったようなことで、必要経費につきましては、あそこだけにすれば、年間１００万円未満で済むだろうというふうに思ってあります。","voiceIndex":31,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問・要望","question":"実は補助２６号線というのは、我々地域住民、品川区の住民でほんとうに最大の課題なんですよね。やはりその農園をつくりながら工事をどんどん進めてもらいたいという要望は出していただきたいというふうに思っておりますが、その促進方の要望はどのような形でやられているのか、ちょっと委員会が違うから言いにくいかもわからないけれども、その辺はどうでしょうか。","respondent":"長田区民課長","answer":"それで、その間、ここを従来は道路用地というのはほとんどさくで囲って閉鎖管理をしていたというようなことですけれども、この辺はそれではもったいないというようなこともございまして、第二建設事務所のほうで有効活用できないかというようなことで考えて。","voiceIndex":33,"id":"exchange-011"},{"speaker":"松澤委員","kind":"質問・要望","question":"私の地元でもありますし、どっちみちつくるならすばらしいものをつくっていただきたいと思っています。一応それでやめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"私も区民農園について質問しますが、この案については議会側には出てきたのは今回が初めてでしょうか。","respondent":"長田区民課長","answer":"そもそも第二建設事務所側からこの話がありましたのが７月末の話です。","voiceIndex":36,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"議会に報告されるのは今回が初めてということなんですが、議会に報告される前に、町会の方とか近隣の方とかに説明をしたという経緯はあるのですか。","respondent":"長田区民課長","answer":"近隣の関係ですけれども、この件の話が７月に出まして、実はこの方針を持ちまして第二建設事務所とは１０月以降、今回の議決をした以降、無償で借りるという方向で調整をしてまいりました。","voiceIndex":38,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"改めて伺いますが、今回今審議しているんですけれども、議決がされてから初めてこの事業というのは進むわけですので、だから、これが議決がされてから初めて事業としてやっていくという考えで改めていいですか。","respondent":"長田区民課長","answer":"私どもは、地域の説明に関しましては、私どもでそういう調整をしているのは確かですというようなことで、実際に今回の区議会にかけてありますので、それの議決をいただいてからでないと、詳しい話については申しわけありませんけれどもできません。","voiceIndex":40,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"私も、その地域の方から、隣接の方がどういう、どうなっているのかと、私が所管する委員会でもあったにもかかわらず、えっ何のこと、ということになってしまったんですけれども、この文章を見ると、断定的に正式な町会の回覧板として出ている。しかし、議会で議決されていない案件が、これからですよね。にもかかわらず、なっている。この辺に関してはいかがでしょうか。","respondent":"長田区民課長","answer":"ですから、その話の内容をちょっと先走って８月３１日付の町会のお知らせというようなことで横出しをした経過だというふうなことがわかりまして、その場で、いや実は区議会も含めて、これについては、まだ調整がついていません。","voiceIndex":42,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問・要望","question":"どんなものになるのか、あと、単純に農園ですから土の関係ですとか、風が吹いたときの洗濯物はどうなるか、細かいいろいろなご不安があると思いますので、今回議決等されましたら、ぜひ隣接に関しての方々への説明を、１回こういうことでなおさら不安を持っていらっしゃると思いますので、よろしくお願いしたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-017"},{"speaker":"松澤委員","kind":"質問","question":"この４駅だけではないですよね。そうすると、同じような形で警察官ＯＢの方を、まだ拡大する予定があるんでしょうか。最終的にはどれくらいまで採用する計画なのかということをお聞きしたいと思います。","respondent":"志村地域活動課長","answer":"その左に担当主査がおります。その上に今度は生活安全担当課長というのは警視庁のほうから派遣ということで、１年半にわたりますけれども担当課長がやってまいりまして、こうした専管組織のもとでこれから進めていきたい、かように考えてあります。","voiceIndex":46,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、今４駅ということですけれども、これをまた拡大するという計画はないということなんですか。","respondent":"志村地域活動課長","answer":"今のところは４駅です。ただ、これはあくまでも事業の推移を見ながら考えてまいりますことなので、これから例えば拡大しなくちゃいけないのか、あるいは縮小すべきなのか、それは事業の進捗等を見ながら対応してまいりたいと思います。","voiceIndex":48,"id":"exchange-019"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうすれば、必ずやはり人員が要るわけですから、それは今４駅で６人体制ですから、将来的に広がった場合にはどれぐらいまでを考えているんですかということなので、それについてのお答えをいただきたいというふうに思います。","respondent":"志村地域活動課長","answer":"の２人はそれをサポートするということをやってまいります。ですので、そこら辺につきましても、そうした経費の面も考えまして、その辺のところについてはこれから考えていきたい。","voiceIndex":50,"id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"昨今ほんとうに治安が悪化しているということで、区によっては自主的に夜間パトロールをしたりということもあるんですけれども、本会議や何かの質問でも出ますけれども、空き交番対策ですよね。この方たちを使おうと思うのか、あるいはあれは警察だから、警察でも増やすような方向にあるという話ですけれども、警察で対応してくださいというふうに申し入れをしているのか、その辺の答えはどうですか。","respondent":"志村地域活動課長","answer":"この事業の全体像をご説明するのを忘れておりまして、実はこの生活安全サポート活動ということで表にお示ししたとおり、実はこの大きな柱は２本あります。生活安全の対応と、それから歩行喫煙に代表されるポイ捨ての取り締まりです。","voiceIndex":52,"id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"それが、私はこの議会であり、委員会であるというふうに思っているんですけれども、そうすると、議会で代表質問、一般質問された方がたくさんいらっしゃいます、こういう区民委員会の中でも話題になるわけですから、その区民の声の代表、私たちとしては、私としては、理事者は警察にこういう声があるんだよと伝えていただかなきゃいけないんですね。","respondent":"太川区民生活事業部長","answer":"ですから、今、生活安全サポートで説明いたしましたのは、やはりこれは私どもの条例の中でも、役所のやるべきこと、それから警察署がやるべきこと、地域がやるべきこと、それぞれ役割は明確に書いてありますので、当然警察署がやるべきものというのは。","voiceIndex":54,"id":"exchange-022"},{"speaker":"嶋委員","kind":"質問・要望","question":"同じく生活安全サポートのところで交番のことなんですが、空き交番のことはもちろん今問題になっていますが、交番の設置というか、増設というか、これもぜひ考えていただきたい。増設というものを、地域の住民から声が上がってきたことがあったのかどうか、また今後それをどうされていくのか。","respondent":"志村地域活動課長","answer":"ただ、東京都のほうの事情もありまして、現実には交番が増えたということはございませんけれども、機会がありますたびに私どもで伝えてまいりたいと、かように考えてあります。","voiceIndex":56,"id":"exchange-023"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、この増設を、この地域はほんとうに前々から行くたびに町会長からもお話が出る問題は、交番の設置のことなんですね。ですので、ぜひ区のほうからも積極的にぜひ増設を、設置をお願いをしていっていただきたいと思っています。きっとそこだけでなくて、いろいろなところで照明が大分落ちているところがあると思います。","respondent":"志村地域活動課長","answer":"ただ、私どもはやはり８時間というんですか、この辺のところをローテーションといいますか、これもちょっと早目に決めなきゃならないということもありますので、ちょっとこの辺は対応といいますか、これから検討してまいりたいと思ってあります。","voiceIndex":58,"id":"exchange-024"},{"speaker":"嶋委員","kind":"意見","question":"ぜひこれから、１０月から日がもう暮れてくるので、大分この遅番の方たちが夜の時間帯に少しかかわるので、照明度なんか少しわかっていただけるのかなと思います。区道、都道、国道があるかと思いますが、そういう形も全部この方たちが相談に乗っていただける状況がありますか。","respondent":"志村地域活動課長","answer":"基本的には全域ですので、そのようにお考えください。","voiceIndex":60,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"防犯というかしら、防犯協会、これも警察の防犯協会と書いてありますが、こういうふうに書いてあるから、当然組織的には警察組織に加わっての組織なんだろうというふうに思うんですけれども、改めてそこをちょっと確認したいんです。何もかも品川区がやるというのは、やはり無理がどうしてもあると思うし、限界がありますので、その辺がちょっと気になるので伺いたいなと思います。","respondent":"志村地域活動課長","answer":"平成１４年は半年間それで行いましたけれども、平成１５年からは警察官ＯＢの方を１０人を採用しまして８地区を私どもと同じように２交代勤務でそれぞれ規制をしているというようなお話を聞きました。","voiceIndex":62,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"だから、私はそうであれば、今東京都が空き交番を空き交番のままにしないで、ここに警察官を配置して、区民、住民のそういう不安な状況に対しての体制がとれるようにということで、検討しているように聞いているので、その辺との関係で、やはりどういうふうに調整して、こういうふうな組織、地域センターを使って相談業務をするよというふうになったのかというのをもう少し詳しく。","respondent":"太川区民生活事業部長","answer":"今ご説明しましたのにちょっと補足いたしますと、最初委員もおっしゃいましたように、ポイ捨てがちょっと先行していたような印象があったというのは、それは事実です。","voiceIndex":64,"id":"exchange-027"},{"speaker":"南委員","kind":"質問","question":"東京都の条例を受けてのことではないと、以前から検討していたことで、たまたま最後に何とかちゃんとおさまったという感じなんですが、私は、やっぱり今の説明を伺っていても、また地域センターでの相談業務をやるということについてもやっぱり警察の範囲のことではないかというふうに思うんですね。やっぱりこれは警察の責任として、警察行政の中でやってほしい部分だというふうに思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。生活安全担当という、この担当というのは、ちょっともう少し詳しく教えていただきたいと思います。","respondent":"志村地域活動課長","answer":"ですので、すみません、当面はまだまだ組織としてはこれだけの人数ですので、すべて１３地域センターで一斉にというわけにはまいりませんけれども、日にちを定めましてそれぞれ巡回する中で、こうしたことをやっていきたいと考えています。","voiceIndex":68,"id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"それで、生活安全担当主査と書いてありますが、これは今まで地域活動課の中にはなかったですよね。まちづくり事業部のほうに交通安全担当課長とありましたよね。そことはもう、全くそこは交通安全担当課長は置きながらも、新たにこれを地域活動課の中にある生活安全担当主査を置き、そことはまた別の流れというかしら、地域活動課とは別に生活安全担当課長を置くという、そういうふうに読むんですか。","respondent":"太川区民生活事業部長","answer":"もう１点ですが、先ほど地域のパトロールということで、ポイ捨てをやって、そのほかの時間につきまして、そちらのほうに当然当たるんですけれども、先ほど地域センターでの相談、そのほかちょっと申しましたけれども、これから私どもといたしましては。","voiceIndex":70,"id":"exchange-030"},{"speaker":"田中副委員長","kind":"質問・要望","question":"今回、生活安全サポートの体制をとるに当たりまして、担当課長のほうとこういう新たな組織をつくっていくということで、非常にそういう課長職を設けることからしても区の姿勢としては積極的に力を入れているという姿勢が見えていいことだと思うんですが、先ほども区民生活事業部長のほうからも少し言われていましたので、総務委員会になってしまうかもしれないんですけれども。","respondent":"太川区民生活事業部長","answer":"ただ、今回のこの生活安全担当課長につきましては、ある意味で言えば特殊なというか、私どもは、なろうと思えばなれるかもしれませんけれども、やはり先ほど地域活動課長のほうの説明もありましたとおり、非常にこれは経験等いろいろなものを。","voiceIndex":72,"id":"exchange-031"},{"speaker":"田中副委員長","kind":"質問・要望","question":"ぜひご注意をいただきながら、続けていただきたいと思います。その喫煙所周辺の方にとってみれば、そこに集中するということで大変、逆に煙だとか含めまして、近隣の方に迷惑を被る方も出てこようかと思いますので、その辺のご配慮をぜひお願いしたいと思うんですが、その点を何かいただけますか。","respondent":"志村地域活動課長","answer":"ですので、その辺につきましては、一帯の灰皿につきましては、清掃活動といいますか、委託をしておりましたけれども、これにつきましても引き続きちょっと回数の増を考えていきたいというように考えてありますので、これからもその清掃については努めていきたいと。","voiceIndex":74,"id":"exchange-032"},{"speaker":"田中副委員長","kind":"質問・要望","question":"もう一つは、にぎわい商店街クリニック事業のことで、大変すばらしいことだと思うんですが、ちょっと期間が緊急ということもあって、また緊急対応ということで、平成１５年１１月から平成１６年の２月までという期間がちょっと短いので、平成１６年度以降の引き続きこの結果によってもご判断があろうかと思いますが、新たな新年度以降も同様の事業をされるお考えがあるのかどうかと。","respondent":"市川産業振興課長","answer":"その関係で、２点目の診断結果をどう生かしていくかですけれども、もともとこのクリニック事業というものは、これまで各商店街に区からさまざまな補助金を出して、商店街活動を支援してきた、その辺のいわば免許の書きかえに当たるような。","voiceIndex":76,"id":"exchange-033"},{"speaker":"田中副委員長","kind":"質問・要望","question":"この診断結果によって、オーダーメイド型商店街の診断とありますが、オーダーメイド型の補助金のあり方も含めまして、支援策をぜひご検討いただいて、全体が発展するようによろしくお願いします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"地域センターの関係でちょっと伺いたいんですけれども、個別のことなので簡単でいいんですけれども、８カ所今回予算計上をしているということなんですが、大きいところはさっき説明がありました。だから、そういうところは今回入っていないのか、ちょっと気になったので、その２点だけ伺います。","respondent":"志村地域活動課長","answer":"ですので１億４,０００万円の中に一部若干該当するものもありましたので、それはそこで充てていきます。ですので、その中で、やってまいる予定です。","voiceIndex":79,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"にぎわい商店街の診断のお話を伺いますが、これは区の独自の施策ですか、それともどこかに前例があってやるものでしょうか。それと、１,６００万円かけるわけですが、その費用対効果というのは、どのように判断していくのか。３点目は、この事業の結果といいますか、目的は、やはり個々の商店の売り上げ向上にあるんでしょうか。","respondent":"市川産業振興課長","answer":"逆に、これまで商店街のいろいろな活性化支援事業を行ってまいりました、その経験の中で、やはり商店街がなかなか、同じような悩みもあるかもしれませんけれども、個別の商店街はやはり個別の悩みを持っていますので、それに対応したものをやってほしいという。","voiceIndex":81,"id":"exchange-036"},{"speaker":"南委員","kind":"質問","question":"それで、非常に悩むところなんですけれども、ここのところについては、先ほどの質疑の中でも東京都の流れの方向とはリンクしていないんだという話なんですけれども、やはり民間人、警察官ＯＢと同時に民間人も一緒にして巡回相談等々に立ち会わせるというところでは、やっぱり私は民間人にさせるべきではないというふうに思いますし、また新しく生活安全担当課長職を派遣で受けて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-037"}]},{"id":"topic-03","title":"請願審査","agenda":"請願審査","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"そういうのを含めてどれぐらい、このような交通事故というのはあるのですか。例えば、これと逆にこっちが悪くないのにタクシーがどんと突っ込んできて壊されたりとかいう報告としてあると思うんですけれども、そういうのは当然これには載っていないというふうに思うんですが、どのくらいこの庁有車で事故というのは起こるものですか。","respondent":"山口品川清掃事務所長、中山清掃リサイクル課長","answer":"庁有車の事故と言うことで、〔「清掃車で」と呼ぶ者あり〕私ども品川清掃事務所におけば、２０台の自分のところの車両を持ってありますので、平成１２年度以降幾つかの事故が起きてありますが、ただ。若干補足しますと、今ご質問のうち、区が被害のような場合の事故ということで、今品川清掃事務所長が申し上げた件数、例えば直営車両で平成１２年度は８件事故を起こしておりますが、加害が５に対して被害が３。","voiceIndex":107,"id":"exchange-038"},{"speaker":"松澤委員","kind":"質問","question":"事故率なんて言ったら怒られちゃいますが、やはりある程度の台数を抱えたら事故というのは必ず起きるものですからね。こういう形で見ると、ああそんなに大きなけがをさせなくてよかったなというふうに思うけれども、事故の中には死亡事故ということも、こういう可能性があるので、ひとつ気をつけるようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-039"},{"speaker":"藤原委員","kind":"質問","question":"これは民事だと思うんですけれども、この１５号と１７号は、いわゆる人身事故ですよね。に対しての刑事罰というか、いわゆる業務上過失傷害になると思うんですけれども、加害者に関しての刑事罰というのはあるのでしょうか。","respondent":"山口品川清掃事務所長","answer":"加害者としての刑事罰はございません。双方それぞれ過失割合ですけれども、１０割の部分については。示談で決着をつけておりますので。","voiceIndex":111,"id":"exchange-040"},{"speaker":"藤原委員","kind":"質問","question":"そうしたら、例えば示談したから刑罰は来ないということであるならば、区の規定として、例えばちょっと質問を変えて、区としては何か加害者、運転手に関しては、訓告程度の処分といいますか、何かしたんですか。","respondent":"松本環境清掃事業部長","answer":"初めてのようなケース、事情があるようなケースについては、今のところあれなんですけれども、ただ、東京都においては、人身罰については相当重い処分を下しております。","voiceIndex":113,"id":"exchange-041"},{"speaker":"南委員","kind":"確認","question":"それで、この１７号の場合は１３１万円余ですが、休業損害も含んでということですけれども、頸椎捻挫症ということで、どの程度の症状なのかちょっとわからないんですけれども、休業損害も含めてということでこれだけの金額になったのかなと思うんですけれども、異議申し立てをしないことを確認したという話なんですが、一般的に私たちも受けている交通事故等々の相談で。","respondent":"山口品川清掃事務所長","answer":"事故防止の点ですが、確かに直営車両を２０台抱えておりますので、私どもは先般、先々週の土曜日ですか、２０日に大崎警察署の交通課長を呼びまして、年２回やっておりますけれども、安全運転講習会という大きな事故のビデオテープも見ながら。","voiceIndex":115,"id":"exchange-042"},{"speaker":"南委員","kind":"確認","question":"ちょっとそれなりのきちんとした対応はしいているということが改めて確認されたんですが、職員の方にぜひとも徹底というか、改めて喚起をしたほうがいいかなということを改めて思いました。そういうところでのやっぱり細心の注意というのを改めて確認をしてもらいたいなということをあえて申し上げていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-043"},{"speaker":"高星委員長","kind":"質問・要望","question":"所管質問等がございましたら、ご発言をお願いいたします。そのほか、その他で特に何かございませんでしょうか。もう一度ご当地でいただいた資料等に目を通していただきまして、思い返していただきまして、具体的に気がついたことを勉強すべきどういうことだというご指摘いただけるような点がございましたら、できれば今日中に取りまとめをしておいていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2370#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":47012,"voices":123}},{"id":"h15-20030929-7","meetingId":"h15-cm09","date":"2003年9月29日","dateIso":"2003-09-29","committee":"厚生委員会","time":"午前１０時０３分～午後２時４０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"私の知り得る限りなんですが、間違っていましたらちょっとご勘弁を願いたいんですが、知的障害者福祉法第５条３項とあるんですが、知的障害者福祉法に５条はあるんですが、５条３項なる規定というのが見当たらないんですが、平成１０年か１１年以降改正された、または添加された条文があるんでしょうか。その部分、ちょっとお教え願いたい。以上の４点をお伺いしたいと思います。よろしくお願いします。","respondent":"日下部障害者福祉課長","answer":"最初に、知的障害者福祉法の関係ですけれども、実は私今それをコピーしたものを手元に持っておりますけれども、お調べいただいた知的障害者福祉法と基本的には同一のものであるというふうに思いますけれども、実は。","voiceIndex":10,"id":"exchange-001"},{"speaker":"大沢委員","kind":"意見","question":"１５条の１２、下に「１６号」になっているんですが、これは「法第１６条」の誤りだと思うんですが、１５条の１２というのも、前置きで申し上げましたように、私の見た知的障害者福祉法のほうが、仮に若干古いのであれば、またそれが明記もしていなかったんですけれども。","respondent":"日下部障害者福祉課長","answer":"２点目にショートステイ、これの弾力的な運用についての目安ということでありますけれども、私ども先ほど申し上げました制度上は基本的に７日以内ということになっておりますけれども、大体今、中期保護ということで、短期保護ですと大体７日以内、７日程度。","voiceIndex":12,"id":"exchange-002"},{"speaker":"大西委員","kind":"意見","question":"このショートステイの件ですが、介護者の方の仕事の形態によっては、お正月が自営で書き入れどきということで、そういう時期にだれも面倒を見る方がいないということもありますが、先般までは少しお正月の時期というのは、こういうショートステイが拒絶されているという状態があったように思っているんですが、これは３６５日、通年を通してオーケーかどうかお尋ねします。","respondent":"日下部障害者福祉課長","answer":"入所施設も、これは基本的に３６５日の施設です。ということで、これに併設しておりますので、基本的にはお正月も含めまして３６５日一応稼動するという前提に立っております。","voiceIndex":14,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つ、現在デイサービスに通っている方はどのような状況になっているのかについても教えていただきたいと思います。それともう一つ、この施設の職員体制がどういう職員体制になっているのか。運営は前にお聞きしたところでは、福栄会に委託ということでお聞きしたと思うんですけど、ここのところに書かれていないので、改めてそこのところを確認させていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"それから定員３０名に対する申請の見込みということでありますけれども、現在私どものほうで把握をしております入所施設への待機者につきましては、大体４０名程度ですので、少なくともその４０名の方はおそらく申請をされてくるのではないかと、このように見込んでおります。","voiceIndex":16,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのほかに待機者は１００名くらいを見込んでおり、中でも４０名はかなりせっぱ詰まった状況ということで言われていたと思うんですけど、この４０名というのはかなりせっぱ詰まった状況ということで、今すぐにでもということでされている方で、それ以外にもたくさんの方が入所待機というふうなことで考えられるということなんでしょうか、そこら辺のところを一つ教えていただきたいのと、あと。","respondent":"日下部障害者福祉課長","answer":"デイサービスについては、２０名程度ということで、今私ども大ざっぱに見ておりますけれども、そのお１人お１人の利用の状況等、これは実はこれからそれぞれの方との具体的な面接とかヒアリングをやってみないと、なかなかその辺はっきりとは言えないところがありますけれども。","voiceIndex":18,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４０名はかなり急を要するというところで、今回３０名ですので、そのうち急を要する方でも入れない方というのが出てしまうという状況だと思うんですけど、これからの区のこういう施設に対しての、整備についての考え方をちょっとお聞かせいただきたい。","respondent":"日下部障害者福祉課長","answer":"区内では２番目なんですけど、２３区を見ても６番目なんですね。６カ所目です。だから、６カ所のうち３分の１は品川区ということになりますけど、そう簡単に地域の理解も含めて、こういう入所施設を設置するということは非常に難しいだろうということがまず一つです。","voiceIndex":20,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今北海道とか東北とか、そういうところに入所されている方も、大変だというのは今までも何回も厚生委員会の中にも出てきていますけど、通うのも大変、なかなか子どもにも会えないというふうな状況がある中で、やはり２３区の中で６カ所しかない中で、品川区に２カ所あるというふうなところでそういうふうに品川区に建てられたということは、ほんとうに大きな評価をするところですけども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-007"},{"speaker":"若林委員","kind":"質問","question":"何点か。今回の新しいかがやき園、区とか都の補助の対象となっていらっしゃいますか。参考までに、あれば、その具体的な数字を教えてください。それから、２３０名の入所というふうに資料でも、今口頭でもありました。ワンフロアに３ユニット、男女別ということですが、おふろも２カ所、同じフロアになりましたので、そこら辺、時間差とか、どういうふうに使い分けられるのか、お教え願いたいと思います。","respondent":"日下部障害者福祉課長","answer":"最初に、補助対象かどうかということですが、これは国の補助制度を活用して建設をしています。大ざっぱに申しますと、全体の建設費が福祉施設だけで３億６,０００万円かかっておりますけれども、３分の２は国と都の補助金ということで予定をしております。","voiceIndex":23,"id":"exchange-008"},{"speaker":"三上委員","kind":"質問","question":"少し教えてください。この通所施設で労働、労働というところまでいくのかどうかわかりませんけれども、それなりの仕事的な部分というのをつくっていかれるんだと思うんですけれども、そういった点に関しての賃金的な部分というのは、どういうような仕組みになっていらっしゃるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"授産施設になりますと、例えば皮細工をやって、そういうものを販売したりとか、そういうことである程度工賃もお支払いするような形になっておりますが、更生施設ですから、工賃の支払いというのは基本的にございません。","voiceIndex":25,"id":"exchange-009"},{"speaker":"三上委員","kind":"意見","question":"そうすると、入所している人たちの個人の負担というのは、結局家族が負担するという形になってくる。条例によると、負担額の規定に基づき別に区長が定めるというような雰囲気になっているのか、そこらあたりはどういう仕組みになりますか。","respondent":"日下部障害者福祉課長","answer":"それから２級の、その下の障害程度の方でも年額８０万円程度が支給をされますので、これまでの入所者の方の状況を見ますと、それで十分に対応できる。","voiceIndex":27,"id":"exchange-010"},{"speaker":"三上委員","kind":"質問","question":"そうしますと、区が負担しなければならないというのは、そういった施設に働いている人に対する補助になるのか。結局福栄会の運営ということになれば、直接的な給与の関係というのは区はないんでしょうけれども、そういった部分についての、品川区からそういう施設的な援助や負担的な部分はあるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"ですから、１人当たり三十数万円の範囲内でこれが実際に運営の委託を受けた福栄会のほうで、その中で人件費とかそういうものを賄っていくというか、大ざっぱに申し上げればそのような仕組みですので十分対応できると思います。","voiceIndex":29,"id":"exchange-011"}]},{"id":"topic-02","title":"引き続き(2)の第４３号議案、品川区心身障害者福祉手当条例の一部を改正する条例","agenda":"引き続き(2)の第４３号議案、品川区心身障害者福祉手当条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、この品川区心身障害者福祉手当というふうになっているように、これは区の手当ということでいろいろなところには書いてあるんですけれども、前に障害者福祉課のほうでお借りした２３区の資料では、この制度が区は事務処理特例交付金というふうに書いてあるところがあるんですけど、区の制度というふうになっているんですけど、制度そのものは区の制度ということでいいのか、それと。","respondent":"日下部障害者福祉課長","answer":"東京都の制度にのっとって実施をしているものです。ですから、財源については全額東京都のほうが負担をするという仕組みになっております。それから第２種につきましては、これは２３区すべて持っておりますけれども、区が単独で実施をしている、そういった手当の制度です。","voiceIndex":37,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"高いところだと、１万円を超えて、隣の目黒区は１万２,０００円というふうになっているんですけど、こういうふうに他区と違うということに対して、品川区としてはどういうふうに考えられているのか、ちょっとお聞かせください。","respondent":"日下部障害者福祉課長","answer":"だから、そういった意味で、手当の金額は多少違いがあったとしても、政策全般をトータルでどう評価するか、どう判断するかということではないかなということで私どもは考えております。","voiceIndex":39,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、やはり難病なんかも医療費の負担がどんどん増えているような状況もありますので、せめて他区並みに引き上げていただくような検討もしていただきたいなというふうに思うんですが、いかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"そういったことを基本にして、サービスの充実を私どもは図ってまいりましたし、現金給付については、これは適宜見直しをしっかりしていくということが非常に重要だというふうに認識をしておりますので、従来の基本的な考え方を今後とも踏襲していきたい。","voiceIndex":41,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"すみません。初歩的だと思いますが、高齢者福祉手当との併給を制限していた。平成１４年度末で終了した、この意味をちょっとすみません。それと、所定の難病というのは、いわゆる厚生労働省の言うところの難病というものと一致するんでしょうか。独自に障害を持った方へという意味で難病が指定されているのか、お教え願いたい。","respondent":"日下部障害者福祉課長","answer":"併給制限の具体的な中身ですけれども、高齢者福祉手当は先ほども申し上げましたように、主に６５歳以上のねたきりの方を対象に支給をされてありますけれども、心身障害者福祉手当につきましては、これは従前６５歳以上の方にも支給をされていたというような経過もありますので。","voiceIndex":43,"id":"exchange-015"}]},{"id":"topic-03","title":"引き続き(3)第３８号議案、平成１５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"引き続き(3)第３８号議案、平成１５年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２月末に国のほうからそういうふうな話が来たのでということなんですが、こういうのがつくことになったんで、今回改修するということになったんでしょうか。それとあと、この内容を見ますと、ほんとうに段差解消とか、そういうのが多いんですけども、発注は地元事業者に行くのか、そこら辺の基本的な考え方を教えていただきたいと思います。","respondent":"蓼沼高齢事業課長","answer":"昨年度健康づくりプランを策定しまして、今年度から実施していくというようなちょうどよい機会でもございましたので、この補助事業を活用して、今回健康塾の会場を中心にこの改修の工事をお願いしたというものです。","voiceIndex":51,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"毎年予算の範囲内でやっていたのが、今回国のほうから予算がついて、一気に改修が進んだと、こういう考え方でいいんでしょうか。そうしたら、じゃあ今回のその後というのは、またもとに戻って、今までのような形で緊急性のところから改修していくという、そういうことになっていくんでしょうか。","respondent":"蓼沼高齢事業課長","answer":"今回、平成１５年度、またそういう協議があったので、それを国のそういった事業を十分活用して改修を行うです。今後ともこういった補助事業については注意しながら、活用できるものは十分活用しつつ、区の予算の計画の中で改修については進めていきたいと考えております。","voiceIndex":53,"id":"exchange-017"},{"speaker":"若林委員","kind":"質問","question":"細かいことで。西大井シルバーセンターのほうでは、ふろ場に１カ月半ほどの工期がかかるという現場の方のお話もあったりしまして、あと見ると、トイレをいじる。各１６館について、何か緊急もいずれというのも含めて、そういうバリアフリー一覧表みたいなものを区では既にチェック済みでお持ちなのかどうか、この２点お伺いをしたいと思います。","respondent":"蓼沼高齢事業課長","answer":"そういう意味では、１２月から１月、それから１月から２月、２月から３月というふうにＡ、Ｂ、Ｃというふうに段階的に工事を進めていく予定です。その工事期間中につきましても、なるべく休館は可能な限りしないようにというふうな配慮も考えてあります。","voiceIndex":55,"id":"exchange-018"},{"speaker":"若林委員","kind":"意見","question":"そこまでどういうふうに課長が押さえられているか、トイレが一つしかないところが、和式を洋式に変えると使えるところがない。それから、上大崎シルバーセンターと南大井シルバーセンターが閉館に一時なると言われましたが、利用者にとってはどういうケアをするのか。これもブロックで割り振るというお考えなのかどうかお聞かせ願います。今、バリアフリーの一覧表がないと。","respondent":"蓼沼高齢事業課長","answer":"そのほか、今後ふれあい健康塾と、健康塾関連、健康学習会等の会場として、一定程度検討を進めている分野、シルバーセンター、それは特におふろのあるシルバーセンターが中心になりますけれども、健康学習会等で水中リハビリというと少し大げさなんですけれども。","voiceIndex":57,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"今のリハビリというのは、要するにリハビリをやるという意味なんでしょうか。身近でリハビリというのが最近、ちょっと新しい言葉というか、入浴の際にそういう指導を行うということなのか、リハビリという形でやるのか。","respondent":"蓼沼高齢事業課長","answer":"これはいわゆる身近でリハビリといったものとは違いまして、基本的には元気なお年寄りの方が自主的におふろ場の中で筋力の老化を防ぐとか、関節の老化を防ぐとか、そういう自主的な可能な範囲で体を動かせるようなものが介護予防につながるのではないかというようなことで。","voiceIndex":59,"id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"鈴木ひろ子委員の特別養護老人ホームの質問のところの一番初めの質問のところで、ケアホームの入所申請のところの介護度別の人数を質問したんですけれども、そこのところがちょっとくくりが大ざっぱだったので、要介護から介護度別にきちんとお答えをいただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-021"},{"speaker":"須藤委員","kind":"質問","question":"どうもその辺も出てきて、またあるいは変えていこうとかというような、学術的に病名を変えていったりするのは精神障害者の問題のときは知的障害者といろいろ変わってきましたよね。そんなこともあるんで、何かそういう方向に行くのかなという思いがあるんだけど、いかがですか。","respondent":"新美保健高齢事業部長","answer":"「痴呆性」はどちらかというと、私なんかは１０年ちょっと前ぐらいのときは、「ボケ」と言って、ボケ老人という言い方で、それは片仮名で「ボケ」と書いてというので、それではやっぱり、ボケはちょっと表現上どうなのかというようなことがあって、痴呆性高齢者。","voiceIndex":73,"id":"exchange-022"},{"speaker":"須藤委員","kind":"質問・要望","question":"今、脳のほうのいろいろな研究が出てきて、痴呆自体も海馬の問題とか、いろいろな状況があがってくるので、今お話しのように、痴呆性の状況というのが介護の問題で大きくだんだん出てきているので、それを状況がそうだから、一つで痴呆性という形に取り上げてくるんでしょうけども、何かその辺のところをもう少し介護度をつけていく上でも必要な状況だなというのは、僕らは町にいると感じているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-023"},{"speaker":"若林委員","kind":"意見","question":"痴呆ということは、ほんとうに的を得ていると思いますし、民間という形も非常に的を得ていると思いますし、震災前後からの見守りというのが私ちょっと言葉としては初めてなので。ほんとうに見てどう判断するかということで、こういう３ポイント、せいぜいあともう１ポイントぐらいの中で絞っていただければ非常にありがたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":95,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3058#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":28647,"voices":98}},{"id":"h15-20030929-8","meetingId":"h15-cm09","date":"2003年9月29日","dateIso":"2003-09-29","committee":"建設委員会","time":"午前１０時０４分～午後２時５１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第４５号議案 品川区営住宅条例の一部を改正する条例","agenda":"の第４５号議案 品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"ちょっと駐車場のところでお聞きをしたいんですけれども、障害者向けの住戸が４戸ということで、駐車場台数、今、５台という話でしたけれども、今、マイクロバス云々という話があったんで、ちょっとその辺がよくわからないので、その辺、ちょっと教えていただきたいのと、それともう一点が、建替法に書いているところで、勧告が、もう区市町村で勧告ができると、で。","respondent":"田村住宅課長","answer":"駐車場の関係ですけど、全体で、台数とすれば１０台確保してます。そのうちの区営住宅の居住者が使うのが５台です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"菊地委員","kind":"意見","question":"区市町村が実際に危険性の高い物件に対して勧告ができるといったときに、じゃ、その危険性が高いというのをどこで一体、区が見きわめていくのか。何を基準にして見きわめていくのかというのも、ちょっと疑問として残るんですけども、そこがわかれば。","respondent":"田村住宅課長","answer":"施行令の中を見ますと、かなり細かくなりますが、１００点以上はもう危ないとか、細かく明記されていますので、これは法律で一律、全国の都道府県、地方自治体、影響しますので、アンバランスがあっちゃまずいということで。","voiceIndex":9,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"そうすると、まず見た目の話じゃないかと思いますけれども、じゃ、２０年たったらそういう調査に入るという規定があるのか、それとも３０年たったら、そういう調査に入るという規定があるのか、その辺ちょっと、今最も、どういう形で実際に調査に入っているのかというところをちょっと教えてください。","respondent":"田村住宅課長","answer":"だから、そういう状況になったんで、あくまで、今回も例えば１０年でも建て替えしたいという物件があれば、老朽危険度がどうなのか、チェックも必要になるかもしれないですけど、年数についてのあれはないんで。","voiceIndex":11,"id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"１点教えてほしいんですが、先ほどのご説明の中に、型別供給住宅というのが出てきたんですけれど、余り聞いたことがないんで、その状況等、現状、品川区の中ではどういう形になっているのか、わかりましたら、教えてください。","respondent":"田村住宅課長","answer":"ところが、ここ二、三年、会計検査院の補助金のチェックのときに、やはり間取りに合ったふさわしい人数、それを設けてほしいということで、これは第八期建設計画５か年計画という国の計画という住宅建設計画の法律があるんですが、その中でもやはり最低居住水準。","voiceIndex":13,"id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"そうすると、例えば２ＤＫだと何人、３ＬＤＫだと何人とかって基準が出てきているんですか。その辺、教えてください。","respondent":"田村住宅課長","answer":"そのとおりでございまして、東京都のほうの基準に沿って、例えば１ＬＤＫ、明日、募集の関係でご報告しますけど、今回、西大井は大部分が１ＬＤＫ、単身者向けで、その型別供給の基準によりますと、やはり申し込めても１ＬＤＫだと。","voiceIndex":15,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"対応というんでしょうか、そういった家族構成が変わったときにも、対応がしやすいのかなと思いました。定期借家権等はこの辺はどんなふうなあれになっていますか。","respondent":"田村住宅課長","answer":"みんな戻ってきたときには、今まではそうじゃないのに、１０年の定期借家しますと、あるいは２０年しますというのは、これは建て替え時移管そのものの趣旨とあれなんで、今回については、検討はしてみましたけど、なじまないだろうです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"井上委員","kind":"質問","question":"第６条第２項のところのこの規定が新しく入ったということは、今までこういった１から６の方々は、同居人とか親族のいることが必要だったということでしょうか。変わった理由は何かあるんでしょうか。","respondent":"田村住宅課長","answer":"先ほどちょっとご説明したんですが、既存の区営住宅条例に該当する物件というのは、すべて区営住宅条例に基づく住宅は、ファミリー向けなんですね。家族がもともといる方しか申し込みできないわけです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"井上委員","kind":"質問","question":"障害者の施設の方の住居が４戸ということなんですけれども、こういったところに入居する方が、車があっていいのか悪いのかというそこがわからないのであれですが、もし、そういう方々が車があっても入居できるということであれば、そういった方たちは足がそういう移動手段やそういうことであるところで、そういう方の優先のようなことも、こういったところでは入るんでしょうか。","respondent":"田村住宅課長","answer":"それも明日ご説明しようかと思ったんですが、やはり障害者向けの住宅が４戸あるということで、戸数が５戸で限界がありますので、それを上回った場合には当然、障害者の方を優先して入居させようと、いわゆる駐車場の使用を許可しようというような形で、今、仕組みを考えています。","voiceIndex":25,"id":"exchange-008"},{"speaker":"藤田委員","kind":"質問","question":"私もあしたやろうと思っているんですけども、きょう１点だけちょっと。４６戸のうち、障害者が４戸で、４２戸になりますね。そうすると、今まで３世帯の人は何か優先権みたいなの、あるんでしょうか。もともと住んでいたんだよというんで、例えば一番見晴らしのいいとこだとか、そういうこともないのかもわかりませんが、優先権があるのかどうかというそこだけちょっと教えてください。","respondent":"田村住宅課長","answer":"明日の資料そのものになるんですけど、要は総戸数は３８戸です。書類を見ていただければわかります。事業用の確保として、都市計画事業等ありまして、全体で８戸ですけど、そのうち３戸が現在、西五反田のほうに住んでいる方です。","voiceIndex":28,"id":"exchange-009"}]},{"id":"topic-02","title":"の第４６号議案 品川区立区民住宅条例の一部を改正する条例","agenda":"の第４６号議案 品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"意見","question":"区民住宅って結構人気があると思うんですが、公募を行わないで、その使用を許可するというところでは、そういったものをあらかじめ確保しているのか。建て替えのときにこの区民住宅も公募を行わないでもできるよということになっていますけれども、あらかじめて確保してきているところではないですよね。","respondent":"田村住宅課長","answer":"ところが、最近、戸数が少なくなったんですが、そういう場合が仮にあれば、例えば５戸、今度、都営住宅で品川区民として抽せんして決めていいよということだと、あきがこれから出る可能性もあるので、じゃ、１戸あるいは２戸。","voiceIndex":35,"id":"exchange-010"}]},{"id":"topic-03","title":"３の第３８号議案、平成１５年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"３の第３８号議案、平成１５年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"１，２６０m2の地区全体でということなんですけど、そのうちの実測では４９２m2なんですが、そのほかのところは、この斜線のそこでしょうか。地域的にはどうなっているのか。","respondent":"浜脇住環境整備課長","answer":"お手元の資料のほうの地区の概要の中にご説明してあるんですが、これまでに２カ所ほど広場用地を買わせていただきまして、１カ所が６６４m2を荏原町の周辺で持っています。","voiceIndex":43,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"３カ所に分かれて、今。で、全体が１,２６０m2だということ。このスケジュールでいきますと、今回、予算の議決をされて、土地取得の契約が１１月に行われるわけですけれども、今後、この地域の近隣の方々の説明とか、そのスケジュール、解体までの間のスケジュールとか、そういったところはどのようにされていくんでしょうか。","respondent":"浜脇住環境整備課長","answer":"当然、建物の除却工事のそういう際には、そういった、どうして買ったのか、今後どうするのかといったようなことについては説明させてもらって、そのころから、地元の方々とそういった整備について打ち合わせをしたいなと、話し合いをしたいなと思ってあります。","voiceIndex":45,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、具体的に公衆浴場がいつおやめになる予定だとか、ちょっとした、いつごろからのそういう時期的なもので、見当がつけば、教えていただきたい。","respondent":"浜脇住環境整備課長","answer":"あくまでも、今あるのは私どものこういった、行政側のスケジュールといいますか、予算のスケジュールといいますか、それだけの話であって、向こうさんのほうには、いつお引っ越しをしたりとかというのは聞いてございませんというか、契約が済んでからでないと。","voiceIndex":47,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうことであれば、きょう、視察に行ったところでは、本当に通りもにぎわいを持っていますし、近隣へ全然空き地もなく、すぐわきには住宅が建っているというような状況ですので、長い時間をかけることは難しいかもしれませんけれども、地域の方の要望、もしくはそういったことをきちんと理解を求めるということをしていただきながら進めていただくように要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問・要望","question":"一点だけ示していただきたいんですけれども、全体の網かけが１９haということで、１,２６０m2の不燃空間整備する、これは何か要綱なんかで決まってる、比率といいますか、全体の網かけ地域の広さと、こういう公園整備、駅前空間を整備するというこれは、何ら決まっている基準みたいなものってあるんでしょうか。","respondent":"浜脇住環境整備課長","answer":"その合計が１,２６０m2ですね。それ以外にも例えば共同化の建て替えをしようとか、道路確保しようとかっていうそういうことを７年間でやれそうなことといいますか、行政として取り組むべきことを事業計画にも盛り込んであるです。","voiceIndex":50,"id":"exchange-015"},{"speaker":"藤田委員","kind":"質問","question":"さっきバスの中でちょっと私、聞き漏らしたことが、これ説明では借地というようにおっしゃってましたよね。そうすると、地主との話し合いというのは２億６,４００万円という多額の金額なんですけども、この辺の流れをちょっと教えてください。","respondent":"浜脇住環境整備課長","answer":"借地人のほうも、そういう地主のスケジュールどおりにいくというふうに役所のほうには報告されておるです。","voiceIndex":52,"id":"exchange-016"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと１点、確認をさせていただきたいんですけど、こういった事例で現在、このように裁判になっている事例というのがどのぐらいあって、これから、今、区民住宅をかなり建てて、こういった事例が出てくる可能性も、かなり秘めていると思うんだけれども、それも含めて、民間にいろいろ委託をするような形も出てきていますけれども、現状と今後の対策なんですが。","respondent":"田村住宅課長","answer":"ただ、そうはいっても、３カ月ではかなりの数いますので、３カ月未満のものの短期滞納者については、短期滞納時点で民間のノーハウを活用して少なくしていきたいと考えております。","voiceIndex":59,"id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"今、委員長の質問に対する答弁で考えたときに、本人が、例えばこれよりもっと軽く、毎月３万円ずつにしてくれとかって、そういう相談をしたときには、じゃ、それも区としては考えていきますよみたいな話なんですかね。","respondent":"田村住宅課長","answer":"本人、特定されていますから。先ほどもちょっと私、触れましたが、説明の中で繰り返してます。今回初めて和解したわけじゃありません。分納制約とか督促とか来庁とか、必ず電話入れてくれと。あるいは来られなくてもというんで、何回も繰り返してます。","voiceIndex":65,"id":"exchange-018"},{"speaker":"金高副委員長","kind":"確認","question":"その場合には全部行政負担で、最終的に処理をする以外にほかに方法がないと思うんですけど、この確認が一点と、そういう方というのは、本当に生活そのものが破綻、先ほど消費者金融とかという話がありましたけど、そういう感じになって、完全に生活状況が完全に破綻してしまっているというのが、大前提にあるんではないかと思うんですけど、その二つのところも、一般的なことでいいですから。","respondent":"田村住宅課長","answer":"ですから、そういう意味からすれば、行政がどこまで打ち出していいのかあれですけど、計画的な生活のリズムなり、生活パターンもつくっていただくことが必要と考えております。","voiceIndex":67,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"こういう問題どうなんですか、やはり少しずつ増えているのかどうかということと、あと行政のほうで、強くかかわっていきますと、今度、イメージ的に、区から追い出されたんじゃないかとか、どういう問題も出てきますし、本来なら、しっかりその区分で、なるだけ、滞納したら、そういう処置をとるとか、何かそういうマニュアルをやっぱりきちっとつくっておかないと、また。","respondent":"田村住宅課長","answer":"明日、マンション基礎調査の概要をご説明しますけど、その調査の中でも、やはり滞納というのは、公的住宅だけが影響する内容じゃなくて、やはりほとんどの分譲マンションについての管理費とか修繕積立金で、大体５％前後の滞納があるという、課題になっているんですね。","voiceIndex":69,"id":"exchange-020"},{"speaker":"山村委員","kind":"質問","question":"勉強不足なんで、突拍子もないことなんですけど、これ区営だからなんで、民間の滞納者、長期滞納者に対して、いわゆる区というのは何かやることがあるんでしょうか。何か区のほうに相談されるということで、区でやれるということはあるんですか。","respondent":"田村住宅課長","answer":"いわゆるこういう条件に合った人が申し込めば、区長が使用許可する。だから、先ほどちょっと３カ月単位の使用許可取消と、条例上明記してあります。賃貸借はそうじゃないですね。やはり訴訟になりますね。ですから、滞納して、もちろん督促だとか何かをしてもらって、だめだと。","voiceIndex":71,"id":"exchange-021"}]},{"id":"topic-04","title":"平成１５年請願第９号「（仮称）大井３丁目マンション新築工事」及び「（仮称）大井３丁目計画に伴う解体工事」に関する請願","agenda":"平成１５年請願第９号「（仮称）大井３丁目マンション新築工事」及び「（仮称）大井３丁目計画に伴う解体工事」に関する請願","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"最後のところで今、課長が説明された最後の都のほうの話なんです。都議会のほうは前回、調停に入ったということで、審議を保留して、今回これやっぱり同様に都議会で出されて、同じように審査保留という形に今なっていますよというところなんでしょうか。","respondent":"浜脇住環境整備課長","answer":"今現在、都議会のほうに聞いたところ、９月２２日ですけども、聞いたところ、今現在は、先ほども言いました建築審査会に審査請求を出しておるので、その結果が出ないうちは審議はしないということで、また保留になっていると、こういうことです。","voiceIndex":77,"id":"exchange-022"},{"speaker":"菊地委員","kind":"質問","question":"課長のところでわかるわけもないんだけど、その審査請求を住民の方がしている状況で、ちょっと私もその辺のシステム、よくわからないんですけれども、実際にじゃ、その結論というか、出てくるというのはいつごろの話になるんでしょうか。","respondent":"浜脇住環境整備課長","answer":"８月ですから、二、三カ月ぐらいは普通かかると。１０月、１１月ぐらいまでかかる可能性があるのかな。ちょっと私どもにスケジュールがないのでわかりませんが、会議は二、三回やりとりをした上で、審査会のほうが判断をするというふうに思います。","voiceIndex":79,"id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"今のご説明ですと、８月７日に審査会のほうへ確認申請の取り消しを求める申請をしたわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-024"},{"speaker":"山村委員","kind":"質問","question":"当然、原委員がおっしゃるとおり、今、委員会でどうこういえる状態じゃないんだと思いますから。それで、あと、須貝委員は前回、本会議でご質問なされたように、こういう例でも、品川区でも何かしらできるような条例なりなんなりが早くできればとは思いますが、今回は継続です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-025"}]},{"id":"topic-05","title":"平成１５年請願第１０号 高層マンション（グランシティ旗の台）建設に関する請願","agenda":"平成１５年請願第１０号 高層マンション（グランシティ旗の台）建設に関する請願","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"私も説明会に出席しております。一応、住民の皆さん、また今回、建てる施行主、建築主ですか、一応、説明会ならびに話し合いが穏便に今、進んでいる最中ですので、できましたら、今後もまだ継続ということなので、皆さんにも継続ということで、ご賛同願えればありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-026"},{"speaker":"菊地委員","kind":"意見","question":"業者が機械を置いて、もう１日中計測をされて、住民に知らせるみたいなことをやっていらっしゃるという意味なのか、それとも、振動が起きないようにといったらおかしいね、振動が起きないようになんてできないことだから、ちょっとその辺、少し、業者側が入った機械のことで。","respondent":"浜脇住環境整備課長","answer":"７０やるつもりが８０になったりしちゃうときはあるんです、瞬間、ある力が、ある場所で。そういうのを自分たちのほうで確認しておく、そういったもので使っているようです。","voiceIndex":94,"id":"exchange-027"},{"speaker":"菊地委員","kind":"質問・要望","question":"課長はそれを別に確認をしたというわけではないんですね。実際に住民の皆さんと約束、当然、住民の皆さんから、その辺は要望として出てるんでしょうから、住民の皆さんに測定した結果を明らかにするような、住民の皆さんのほうから、実際的な要望として出ていれば。何ていうんでしょう、それなりの指導というのは、できないものなんでしょうかね。","respondent":"浜脇住環境整備課長","answer":"私どもはもちろん、前向きにそれなりの対応が受けたのかなということで思ってますので、それをどうしようということは言っていません。","voiceIndex":96,"id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"そういう騒音・振動に関しても、ある程度、やはり掘ったり、ブルドーザーが入ったりと、そういうことも、ある程度はやむを得ないだろう。ただ、あんまりひどい場合には、じかに建築現場に申し出るということで、進んでおりますので、課長のほう、ご心配のなく、一応、話し合いということで、そこは進んでおります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-029"},{"speaker":"原委員","kind":"質問","question":"ですから、本来で言うと、ここで当委員会としての結論を出してもいいんじゃないかなというように私は思いますけれど、紹介議員のほうで、もう少し待ってくれとおっしゃるのであるんだから、そうしなきゃいけないのかなということも考えているんですけど、ただ、前回、この手の請願については速やかに判断を下すというのが前提になっていますよと。今の状況であると、この請願についてはですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3762#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":31049,"voices":103}},{"id":"h15-20030929-9","meetingId":"h15-cm09","date":"2003年9月29日","dateIso":"2003-09-29","committee":"文教委員会","time":"午前１０時０４分～午後３時４８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"山路委員","kind":"意見","question":"今説明をしていただきましたけれども、東京都の支出金６０万円ということで、ティーチングアシスタントモデル事業の内容ですけれども、今までもティームティーチングという事業を何校かでやられていましたね。そこはどういうふうに違うのか。品川区も補助教員をやると言っていましたけれども、学力向上のためというんですけれども、その内容の違いを説明していただけますか。","respondent":"中島指導課長","answer":"いずれにしましても、教員免許を所有してございませんので、例えば小学校の５年生の２学級でやるときに、これを三つに分けて実施をするというときには、一人ひとりが一つのグループを持ちますと、３人指導者が必要になってくる。","voiceIndex":6,"id":"exchange-001"},{"speaker":"山路委員","kind":"質問","question":"今までは教員の免許を持った人に限られていましたね。今回は大学生ということで、サイドから授業を教えることは可能という説明がありましたけれども、その辺の、直接教える、これのお手伝いという形ですか。","respondent":"中島指導課長","answer":"学校のほうでは、この事業によって、アシスタントが成果を得て、どういった部分が向上していったかという報告書を都のほうに上げるというような状況もあります。","voiceIndex":8,"id":"exchange-002"},{"speaker":"山路委員","kind":"質問","question":"大体見えてきましたけれども、大学生の方が、今までに専攻された専門を特に教えるというふうなこととはまた違うんですか。生徒に合った、チームで教えるというふうに捉えていいんですか。","respondent":"中島指導課長","answer":"品川小学校、中延小学校におきましても、それぞれ習熟度別学習を展開するための指導助手が派遣されておりますので、それぞれの学校で、例えば算数の個別指導ですとか、そういう計画を立てたプログラムの中に入っていただいて、その指導計画に則っとって。","voiceIndex":10,"id":"exchange-003"},{"speaker":"山路委員","kind":"質問","question":"学校別の特色あるということで、各学校がいろいろな研究発表をしてまいりましたけれども、そういうことで、今回この三校が選ばれたということですか。","respondent":"中島指導課長","answer":"具体的な希望数、そして希望がかなわなかった部分のところにつきましては、今手元に資料がなくてお答えできなくて申し訳ございません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"山路委員","kind":"質問","question":"一つは、全体的には、若い大学生が直接教えていただくということは、私も向上するように期待しているんですけれども、もう一方、学生の方たちが勉強する、教員を目指す人の勉強の場としても非常に効果があるんじゃないかと思うんですけれども、何を得ると思われますか。","respondent":"中島指導課長","answer":"その中でも、特に今求められているのが、個に応じた指導ということで、もちろん自分が個別に指導に入る場面もありますが、ベテランの教諭が個別に指導に入る場面、そういったところを見ながら覚えることができる、また、グループ指導の中で共にやりながら。","voiceIndex":14,"id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"二つお伺いします。それから、追加された６０万円の具体的な金額はどういうふうに三つの小学校に係わっていくのか。もっと言えば、ティーチングアシスタントをする大学生に対してどういう形でそれが支給されていくのか、その６０万円の使い道を教えていただきたいと思います。","respondent":"中島指導課長","answer":"具体的な６０万円の使い道ですけれども、ティーチングアシスタントモデル事業にアシスタントとして参加する学生への報償費という形で５５万４,０００円を予定しています。そして、一般需用費という形で４万６,０００円を支出する予定です。","voiceIndex":16,"id":"exchange-006"},{"speaker":"伊藤委員","kind":"質問・要望","question":"５５万４,０００円が報償費ということですので、三つの学校で何人ぐらいいるのか。それから今、品川区は一生懸命プラン２１を推進して優秀な教師を探しているわけですが、可能性として、こういうところから来る大学生の中で、将来的に品川区に来ていただきたいなと思う方がいらっしゃると思うんです。そういうようなことまで考えていくんでしょうか。そこまで教えていただければと思います。","respondent":"中島指導課長","answer":"今年度の実施の中では、品川小学校では３名、中延小学校では１名、荏原第四中学校では４名の学生をアシスタントとしてお願いすることになっております。実施をしております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問・要望","question":"でも、私たちがずっと言い続けているのは、教員の質の問題ですね。そういうところまでできれば、現状は、おっしゃるとおり、難しいことは分かりますけれども、やはりこういう意欲ある方々が、しかも品川区の腹はあまり痛まないで来ていただくわけですから、できれば、そういうことをぐっと引きつけてもらえるように、魅力ある品川区の教育をつくっていただきますように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"アシスタントですけれども、教員の資格がないから、習熟度別の、一つのクラスの授業は持てない、あくまでも先生についてサポートするという格好だとは思うんですけれども、全体として、正規の教員と、指導助手として入ってきて、今度は学生が入ってくるという、何か教育を進める中で、いろいろな身分の違いと言ったらいいんでしょうか、何と言うかわからないんですけれども。","respondent":"中島指導課長","answer":"各学校におきましては、特に小学校の場合は研究組織の中にこういった習熟度別の分科会を設置して、そこでティーチングアシスタントの発表について研究を通しながら実施していくというようなシステムを組んでおりますので、中にその学生が参加して。","voiceIndex":21,"id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"今品川区全体で教員がどれぐらいいるのか、指導助手がどれぐらいるのかということが分かったら、人数だけを教えてほしいのと、それぞれ今度のティーチングアシスタントの賃金といいますか、指導助手は時間当たりどれぐらいなのか、併せて教えてもらえればと思います。","respondent":"中島指導課長","answer":"アシスタントのほうは、交通費相当を支給するという形になっておりまして、各校１８万円、これがおよそ１回につき２,０００円、これを３０回分、３名ぐらいを想定してという想定のもとに１８万円が各学校に配付されるという形になります。","voiceIndex":23,"id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"１回につき２,０００円というのは、１回というのは２時間ぐらいを見ているんですか。","respondent":"中島指導課長","answer":"先ほど申し上げました指導の回数という形になりますので、その日に持っている時間はそれぞれの学生によって状況が変わってくるという形です。その日に５時間持っているという状況はあります。","voiceIndex":25,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"確認したいんですけれども、品川小学校が３名、中延小学校が１名、荏原第四中学校が４名ということで、ばらつきがあるのはどうしてか。多分これは予算的には３、３、３かどうかわからないんですが、人数割がどういうふうになっているのかということ。","respondent":"中島指導課長","answer":"それぞれの三校の校長、教育委員会の指導課のメンバー、学識経験者が１人入りまして、その内容についての指導・助言に入っていただくという形で、内容の充実を図っているということがあります。","voiceIndex":29,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"そうすると、地域連絡会ということなので、東京都のほうからいろいろ指導されるということではなくて、品川区の中で、そこら辺は連絡をとり合いながらチェックしていくという感じですか。","respondent":"中島指導課長","answer":"そうです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"西本委員","kind":"意見","question":"そういう面では、若い人たちをいろいろと応援してあげたいと希望して、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"その方が補助的に係わっていくんですけれども、授業を行う前の打ち合わせというか、授業ごとに目標を掲げて事業を行っていると思うので、打ち合わせなどはどのように行っているのかということと、授業の後、子どもたちの表情がどうだったとか、具体的な打ち合わせというようなことがもしあるのであれば、そんなところをどんなふうに行っていくのかお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"そこに優秀なアシスタントのスタッフも入ってくるわけですけれども、１回ということで、１日の中で、例えば４時間授業に入ってくる学生が、その１回の中で、最初に少し早めに来てもらって、そこで打ち合わせをするとか、それから、特に評価につきましては。","voiceIndex":34,"id":"exchange-015"},{"speaker":"石田副委員長","kind":"提案","question":"それが現実に都までいって、補助金をもらって、それが都までいかないけれども、区で大切だと思って、区教育委員会で対応をして、こういうモデル事業をやっているよというような数、あとは、これはだめになったとか、補助金がつかないからやめてしまったとか、区でこれだけ提案して、こういうものが都教育委員会で補助金も受けながら一つの事業になったよとか、そういうものの数の度合いというのか。","respondent":"中島指導課長","answer":"スチューデント・シティに代表されるＮＰＯとの関連事業も、これも文部科学省の取り組みとして支援していただくという形でないと対応ができないというような状況があります。","voiceIndex":36,"id":"exchange-016"},{"speaker":"石田副委員長","kind":"質問","question":"もっと文部科学省はこういうふうにしろよとかという場面も出てくる場面もあるんだけれども、逆にあと、知りたいのは、校長会とか、そういうところから都教育委員会に対して、こういうことをやってくださいよというのがどれぐらい上がってきているところがあるのかというところを、せっかくこれだけやって、意識も変えて、方針でやっているわけだから、そこら辺の部分はどれぐらいあるのかという。","respondent":"中島指導課長、古川教育次長","answer":"校長会からの要望という部分ですが、校長会のほうは、プラン２１に基づく事項の自立的な各学校を目指した取り組みで、かなり努力をしていただいているという状況はありますけれども、例えば研究学校等の中で。品川区はプラン２１についてさまざまな角度で、一言で言えば教育改革ですが、現場の実態を踏まえて、それがより効果的であれば、区としては一定の予算措置も加えながら、それを実施していく。","voiceIndex":38,"id":"exchange-017"},{"speaker":"石田副委員長","kind":"質問・要望","question":"だんだん話がそれてしまうみたいなので、これでやめておきますが、私の今言っていた、校長会という話のところで、またほかの場面でやりますが、せっかく教育委員会でプラン２１を出して、特色ある学校をつくっていこうというときに、学校側からさまざまな要望なり、こういう形のお金を使ってこういうことをやっているよという部分が、私の思っている中では。","respondent":"若月教育長","answer":"そんなことから、それだからいいやというわけではもない、教育委員会としては何かそこに援助ができるものがあれば、これからもしてあげたいなとは思っていますが、現実に校長会からはそういう動きがありますので、それを大事に育てながら。","voiceIndex":41,"id":"exchange-018"},{"speaker":"石田副委員長","kind":"質問・要望","question":"そこら辺の収入の部分も含めて、「学校」と名がついているから、ある程度みんな我慢しているんだけれども、あまりにも自分たちの仲間の平均というか、これぐらいでしょうという感覚の出るものと違いがある場合に、いろいろお願いをしてきて、今はちゃんとやっている、対処をとっていらっしゃるんだけれども、労働基準監督署との相差というのをどういうふうに捉えていけるのか。","respondent":"谷田部学務課長","answer":"最初の、学校医としての報酬は通常の業務に比べて高いか安いか、過去にも決算特別委員会、予算特別委員会でいろいろ議論がありましたけれども、私ども学校医の先生方にお支払いしているのが、内科医は月額４万５,５００円、眼科医と耳鼻科医。","voiceIndex":55,"id":"exchange-019"},{"speaker":"石田副委員長","kind":"質問・要望","question":"私の理解がわからないので、もう一回教えていただきたいんですが、２ページに計算式がありますね。今のお話の中だと、公務災害だから、公務員の常勤の方の基準を算定して、その方の部分が基準になるんだよと。こっちの部分については品川区常勤というのはないわけだから、そういうものをお願いしたときに、こっちの基準を引いてきて、ある程度の金額を決めてきているんだという理解でいいのか。","respondent":"谷田部学務課長","answer":"ですから、法律の基準に従いながら、それから、４分の３という考え方ですけれども、これも労働基準法の第１２条第７項の規定、いわゆる非常勤職員、日々傭い入れられる部分の者の平均賃金ということで当てはめなければならないですので。","voiceIndex":57,"id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問・要望","question":"基本的なことを教えていただきたいんですが、補償内容ですから、医師、薬剤師の方が公務中に、例えばけがをしたとか、もし亡くなった場合とか、公務災害の基準というものをお伺いしたい。それとも職場に復帰されるまで支給されるのかということ。それから、職務に復帰した場合には、この基礎額は支給されなくなるのでしょうかということ、非常に基本的なことですけれども、教えていただければと思います。","respondent":"谷田部学務課長","answer":"療養補償というのがありまして、これは治療費とか、薬剤、手術、家庭療養、看護、病院療養を伴う看護、医療費、こういういわゆる実際にけがをされて、治療に伴う補償、それから、休業補償、けがをしたことによって、本来、医師として開業されて。","voiceIndex":59,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"確認","question":"この補償制度の全体の仕組みを簡単にお聞きしたんですが、この条例からすると、医師または薬剤師の方が学校での公務災害になられた場合の補償の１日の金額を掲げているということでよろしいでしょうか。ということは、給与が変われば、補償額も変わるのでしょうかということ。今回はそれが変わったから、これを変えたということ。非常に原点な質問ですけれども、改めて確認をお願いいたします。","respondent":"谷田部学務課長","answer":"１点目は、日割計算の補償額です。２点目の、この改正の決定の仕方というんでしょうか、昨年の４月に条例そのものを制定する方針でしたが、それまでは東京都条例で昭和３７年から平成１３年度まで東京都が条例を定めて、区立または市立の小中学校の学校医の補償をしておりました。","voiceIndex":61,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、これからの補償額算定基礎の考え方ですけれども、政令の改正とか、それから、品川区独自で変えるということを聞きましたので、そういうようなことから考えてまいりますと、品川区の責任は非常に重くなってくるわけですから、うまくバランスを保ちながらという表現をしておきますけれども、それは対処していってくださいということをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"補償基礎額を減額した背景に、５年未満だと現行が６,７７０円が６,６５３円になっておりますけれども、それが何なのか。もうされたんですか。いろいろ説明をしていただいたんですけれども、何なのかというのがもうちょっとわからないことと、それから、これは品川区単独のものなのか、２３区で統一したものなのかも含めて教えてください。","respondent":"谷田部学務課長","answer":"たしか今年の２月１日、それが介護補償の関係で４月１日に改正されまして、それを受けて、東京都のほうでは都立学校の学校医につきましては、都議会のほうで改正をしたというふうに、私ども第２回定例会で災害補償とかいろいろ準備したんですが。","voiceIndex":64,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"質問・要望","question":"自民党としては、先ほどの話も聞きましたけれども、学校医、歯科医師の給与の水準、それから、サークル、政令等の対処を十二分に視野に入れながら対処していただきたいということを要望して、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-025"},{"speaker":"山路委員","kind":"質問","question":"今の質疑の中で何点かお伺いしまして、補償制度として必要だということで、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-026"}]},{"id":"topic-02","title":"続きまして、(3)第４８号議案、品川区立文化センター条例の一部を改正する条例","agenda":"続きまして、(3)第４８号議案、品川区立文化センター条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"提案","question":"生涯学習課でつくっていただいた、品川区立文化センター条例の一部を改正する条例について（概要）の資料の中で気になったのは、４のスケジュールで、平成１５年第３回区議会定例会、「条例改正」という表現になっておりますけれども、今日初めて委員会に出た話であって、「条例提案」ということのほうが正しいのではないかと思いますけれども、伝えておきます。その二つをまずお伺いします。","respondent":"上川内生涯学習課長","answer":"大体６０歳代、５０歳代が中心です。今日品川健康センターのほうを伺いましたけれども、４０歳代、５０歳代、若い層の方たちがいらっしゃっているというふうには認識しております。","voiceIndex":78,"id":"exchange-027"},{"speaker":"伊藤委員","kind":"質問","question":"もう一つ気になっているのが、今課長が最後のほうでおっしゃった、初めはきれいで、比較的若い方々が品川健康センターを利用されているのを今日見ました。ところが、品川健康センターは多分そうでない場合がありますので、そういう調整をとったほうがいいんじゃないかでしょうかということをひとつお伺いしたい。そこについてはどういうふうに考えているかということをお伺いします。","respondent":"上川内生涯学習課長","answer":"品川健康センターのほうはそういうことはございませんので、そういう意味では、より多くの方たちが利用しやすくなるというふうには認識しております。","voiceIndex":80,"id":"exchange-028"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、それをぜひ対処してくださいということをお願いしておきます。ですから、サウナ、浴室を廃止という表現がありましたけれども、廃止なら廃止で結構ですが、これを将来、例えば１年なら１年、２年なら２年経って、ヘルストレーニングルームがこういう施設に変わった後、ではどういうふうにしていくんですか。そこまで考えているんですかということをぜひお伺いしたい。","respondent":"上川内生涯学習課長","answer":"だから、大きな部屋だけではなくて、小さな部屋もあるほうが、いろいろなグループに対応ができるのかなと思いまして、４０m2程度の講習室を別につくろうかなというふうに考えてあります。","voiceIndex":82,"id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今浴室だけに限ってだけ言いますけれども、浴室、サウナについては結論は出ないかもしれませんが、廃止なら廃止で構わない、できれば一体的にやっていただきたいんですけれども、予算も高額だからできないという説明ですから、サウナ、浴室の部分については、できるだけ早くと言っても、来年にはなるんでしょうけれども、計画をつくって、施設の有効活用。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-030"},{"speaker":"山路委員","kind":"質問・要望","question":"中途半端にやって、それでまた漏れて、苦情がきますと、今まで以上にまた。それよりも、今伊藤委員のほうからもありましたけれども、地元の方の意見を聞かれて、やっていただきたいと思います。それと、私のほうに相談を受けたのは、無料だったのが、今度は有料になるのではないですかと、何人かの人が言っているんです。今度は有料だと。その辺の配慮というのは何か考えていらっしゃるんでしょうか。","respondent":"上川内生涯学習課長","answer":"１回５００円、東品川文化センターは昔から５００円でした。品川健康センターも新たにできるときには５００円にしていったということもありますので、そこのところは５００円払っていただいて、新しい器械と、たくさんのお友達をつくっていただきたいと思います。","voiceIndex":85,"id":"exchange-031"},{"speaker":"山路委員","kind":"質問・要望","question":"課長の言われることも分かるんですけれども、年金生活をして、無料だから健康のためと通っている人々に５００円、一般の人はいいですよ。そこに納得性のある説明をお願いしたいと思います。現場では、何とかできないんですかという意見もまだあるんです。それを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"今いろいろご説明を伺いまして、品川健康センターのほうには若い人が利用されている。デジタルとかですと、若い人は慣れていますから、利用しやすい部分があるとは思いますけれども、１週間の体験ツアーを組むとは言っておりますけれども、そうすぐにできるものではないかと思うんです。その辺の高齢者に関する工夫はどのように行っているのか。この２点について伺いたいと思います。","respondent":"上川内生涯学習課長","answer":"さっきの説明の中では言っていませんでしたが、平成１４年に内部の事務事業評価をやっておりますが、ヘルストレーニングルーム事業がＤランクになりました。","voiceIndex":88,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"１人５００円の利用料だと採算がとれない。もし分かるのであれば、東品川文化センターの年間の経費といいますか、それから、工事後、防音施設にしたときに経費がどれぐらいかかるのか、防音施設にしたら、おそらくスタッフは１人置かないというふうになるんでしょうか。それがわからないんですけれども、コストはどう変化していくのか教えていただければと思います。","respondent":"上川内生涯学習課長","answer":"年間経費ですが、基本的には普通の講習室ですので、あそこに受付の人はおりません。現在の年間経費ということですが、今具体的には職員の人件費とは別枠でなっておりまして、事業費として指導員の経費が５００万円ちょっとかかっております。","voiceIndex":90,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"健康づくりというところで、財政効率がはじめにありきとはいかないと思うので、お金がかかっても必要なところにはきちんと経費を入れてくるということが大事な姿勢だと思いますので、そこのところはこ今後ともそういうふうにしていただきたいと思うのと、２カ月半後ぐらいですか、年内に閉鎖になるということを、利用者に対してきちんとした説明と、今後品川健康センターに利用者が移るわけですけれども。","respondent":"上川内生涯学習課長","answer":"現場の館長のほうにも、時間を都合してと言われて、説明もしております。今までこれについては全然文教委員会に諮ってございませんし、ここで諮ってから公に張り紙をするなりしていく算段になっております。","voiceIndex":92,"id":"exchange-035"},{"speaker":"西本委員","kind":"提案","question":"個人で利用されていると思うんですが、利用されている方は結構お友達関係ができているはずで、何曜日に来るとかという話があって、結構交流があると思いますから、そういう交流のあり方たちを、個別対応というよりも、グループで紹介するとか、１人ではなかなか利用しずらいので、グループでどうですかとか、機会を設けて、一緒に行きましょうとか、あとはインストラクターのほうで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":94,"id":"exchange-036"},{"speaker":"沢田委員","kind":"質問","question":"何点か聞きますけれども、こうした筋力トレーニングというんでしょうか、ジムというんでしょうか、区内にできる施設というのは幾つぐらいあるのか。","respondent":"上川内生涯学習課長","answer":"トレーニング施設ですが、ジム系が民間では１２館、公設が５館あります。全体で１７館、トレーニングジムとしています。","voiceIndex":95,"id":"exchange-037"},{"speaker":"沢田委員","kind":"質問","question":"この問題は、中央館一つにしてデラックスにしていくのか、あるいは小さな施設を身近なところで利用できるように、多少グレードを落としても何カ所かつくっていくようにするのかが問われているんだけれども、区のほうとしては、ああいうトレーニングジムみたいなものは、今５館あるとおっしゃいましたけれども、なるべく絞って、そこに来てもらうようにするということのように聞けるんですが。","respondent":"上川内生涯学習課長","answer":"マシンがかなり高額なもので、ほかのところでは講習室とか学習室がまだ足りないという状況なので、トレーニングジムを新たにつくるということはありませんし、もともとトレーニングジム、昭和４７年に建ったときの建物が、民間でもかなり高級なホテルにしかなかったということで。","voiceIndex":97,"id":"exchange-038"},{"speaker":"沢田委員","kind":"質問・要望","question":"絶対こっちがいいとは言えない。それから、３１年間ですか、長い間親しんで、利用者が年間で減ってきたというのは分かりましたけれども、現に４,９００名いる。廃止しないでほしいというのが区長あてに陳情が出されているというような話を聞いたんですけれども、そういう利用者に対する理解を得る努力というのはどうだったか。その点についてはもう少し説明をいただきたいんです。","respondent":"古川教育次長","answer":"そういう中で、今後東品川文化センターと同様に、また維持し、発展し、充実していくか、このことが今求められてきている中で、このヘルストレーニングルームについては、３０年という中で、もちろんさまざまな方、愛着をお持ちの方もいらっしゃいますので。","voiceIndex":99,"id":"exchange-039"},{"speaker":"沢田委員","kind":"提案","question":"区側の提案ですね、実際にああいうのをやって、比較的近所にできたということは分かりますし、この提案をすることが無茶だと言うつもりは全然ないんですけれども、廃止をするという、現に利用者がいるという場合には、周到な準備と理解を得るような説明を前提としてやるべきだというふうに私は思うんです。今の答弁では、いつ言ったのかというのが出されていない。","respondent":"上川内生涯学習課長","answer":"それで、聞かれたときには、紙に掲げるとかというのは、まだ議会の承認もとっていませんし、まだ品川健康センターとの連携もきちんとつながっておりませんでしたので、それをきちんとしてから、安心できる形で外部のほうに説明したいと思いまして、口頭では。","voiceIndex":101,"id":"exchange-040"},{"speaker":"沢田委員","kind":"提案","question":"学童保育クラブの廃止の問題もそうなんですけれども、施設が廃止されるということは大変なことですよ。利用者が現にいるということですからね。住民参加というのは、決定したものを説明するだけなのか。私は違うと思うんです。事案決定前に住民の意見を聞き、識者の意見を聞いて決めるのに、条例提案して議会で決めたら、もう決定事項になってしまう。その点で不十分だったというふうに私は思えてなりません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-041"},{"speaker":"石田副委員長","kind":"質問・要望","question":"先ほどの答弁で一つだけ確認をしたいのは、浴室の部分を講習室に考えておりますというお話がありました。そこら辺のところをもうちょっと具体的に教えていただきたい。どうしても予算付けができなかったんだということで、そこの部分を１年になるのか、２年になるのかわからないけれども、閉じるというわけですね。そこら辺の費用対効果を考えられても、基本的に閉じるという考えですね。","respondent":"上川内生涯学習課長","answer":"施設係との具体的な詰めはまだ、細かい見積もりはしていないんですが、今のあらあらの話の中では、１,０００万円程度だったら、１１m2の中でやるほうがいいのではないかというような意見もありますので、講習室のほうは小さな講習室をという要望もあるというので。","voiceIndex":104,"id":"exchange-042"},{"speaker":"石田副委員長","kind":"質問・要望","question":"要望があるからやっていく、やっていかないということは、もちろんそれはあると思います。それでいくならば、例えば要望を言うなら、１,０００万円で、３５坪ですよ。そうすると、坪当たりの防音工事は３０万円ぐらいです。それも要望もあります。その中でまた講習室だということは、要望はもちろん分かるけれども、１年の稼動率を考えていくならば、その戦略というのはおかしいよとなるんですね。","respondent":"上川内生涯学習課長","answer":"だから、全体ばらければ、全然使われない時間帯というのもあるというふうに現場からは聞いておるところなので、皆さんが集中するところの時間帯はもう少し何とかできないかと思います。","voiceIndex":106,"id":"exchange-043"},{"speaker":"石田副委員長","kind":"質問","question":"そういうふうに指示もされているでしょう。では、そこにもう一つダブっている部分が増えたのは当たり前ですよ。６割台、７割の稼働率で終わってしまうわけですよ。それをまた上げるためにどういう戦略があるんですか。それをやるからまた６割、７割の稼働率になってしまうんじゃないですか。だから、上げるための戦略をどのように考えているんですかと伺っているわけです。","respondent":"古川教育次長","answer":"現年度予算の中で、あるいはさらなる何らかの措置の中で一体的なものができるか、できないかもまだ検討の余地はあるのではないか、この辺もまた検討をしていきたいと思ってありますし、場合によっては、１１７m2の改修が先になる部分もあろうかと思いますが。","voiceIndex":108,"id":"exchange-044"},{"speaker":"山路委員","kind":"質問・要望","question":"課題は、意見として申し上げましたけれども、地域ニーズに高い何かをということは求められると思いまして、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-045"},{"speaker":"沢田委員","kind":"提案","question":"賛成しかねます。ついでに態度表明をさせていただきたいと思います。さっきも言いましたように、区側の提案はとんでもないと言うつもりはないんです。老朽化して、おそらくあまり投資をしてこなかった。だから、そういう点で正しい選択なのかどうなのかということが、２点目。今後そこは改めていただきたいなというふうに、以上３点申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-046"},{"speaker":"本間委員","kind":"質問・要望","question":"新しいさまざまな区民ニーズを的確に捉えながら、新しい事業の展開といいますか、事業の変更といいますか、そういう部分を進めておられるのだろうと、先ほど事務事業評価等々の中身にも触れられたことがありましたけれども、十分その辺は区民ニーズに応えるべく、今までより、より内容のサービスが提供できるものとして、失敗しないように、代替機能を誘導すべく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"文化センターの今後の利用については、これからますます改築等々の問題を含めて、議論を進めていくことが必要かと思いますけれども、ＰＲの方法で、より多くの区民の皆さんに使っていただいて、地域の方たちに楽しんでもらえるような、そういう利用方法を考えるべきだと思いますし、東品川文化センターについては、老朽化の問題等々もありますので、当然ながら品川健康センターの中での、今日視察した中でも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-048"},{"speaker":"中塚委員","kind":"質問","question":"自民党の石田議員の質問の中で、学校給食の調理代行に関する質問があると思うんですけれども、それに関して質問をしたいと思います。それが１点目です。もう一つ、前回の文教委員会の最後に僕が行った質問ですけれども、学力テストの成績の答案を返したほうがいいかなと思ったんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4480#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":47416,"voices":126}},{"id":"h15-20030929-5","meetingId":"h15-cm09","date":"2003年9月29日","dateIso":"2003-09-29","committee":"総務委員会","time":"午前１０時０3分～午後３時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を72件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第３９号議案 非常勤職員の報酬及び費用弁償に関する条例の一部を改正する条例","agenda":"の第３９号議案 非常勤職員の報酬及び費用弁償に関する条例の一部を改正する条例","exchanges":[{"speaker":"武内委員","kind":"意見","question":"この非常勤職員の方のお仕事なんですが、ここに書いてあるとおり、生活安全に関する取り組みと歩きたばこのほうを書いてありますが、全体的にやっていくと思うんですが、主に歩きたばこのほうを中心にやるのか、それとも先ほどおっしゃったパトロールとかそういった方面に力点を置くのか、その比率というのは今、まだこれからだと思うんですが、大体どんなイメージとしてあるのか。","respondent":"桑村人事課長","answer":"基本的には、生活安全条例を具現化するというのが基本ですので、生活安全対応は基本というふうに考えてあります。地域センター等での防犯等の相談業務とか、あるいは地域巡回の実施とか、特定重点地域と申しておりますが、そういったものについては、もっと重点的に回ったり。","voiceIndex":7,"id":"exchange-001"},{"speaker":"川西委員","kind":"意見","question":"今のに続きまして、済みません、勤務交替制の朝と夕方の勤務、それから、組織ですね、どういう組織にするのか。","respondent":"桑村人事課長","answer":"組織ですけども、区民生活事業部の中に生活安全担当という組織をつくりまして、課長職の組織ですけども、そこに係長、また、その下にこういったＯＢの方の非常勤の方がつくというラインといいましょうか、ラインの組織をつくるという予定です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"警察官のＯＢの方ということで、それぞれいろんな経験とかのものをお持ちの方ということではあるんでしょうけれも、基本的には、いわゆる民間で言えば定年退職後という発想のＯＢという考え方なのかどうかということで、まずお伺いをしたいと思います。","respondent":"桑村人事課長","answer":"その意味で今回、任用する職員ですけど、済みません、人数を言わなくて申しわけありません。３人予定していますけれども、６１歳の方、６０歳の方、５４歳の方を予定しています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"土井委員","kind":"確認","question":"わかりました。そこで、品川区の区役所内においても、いわゆる賃金というか、報酬という面では、再雇用の方もいらっしゃるわけでしょうから、そういう皆さんとの間のバランスとかというのは、こういうので、とれているんだろうなということで、ちょっと確認の意味で。","respondent":"桑村人事課長","answer":"今回、期末ですと、勤勉とかを支出する予定はございませんので、そのところは今、区の再任用ですと、２カ月ぐらい出ますので、多分、給料的にはほぼ同額ぐらいになるのかなというふうに考えています。ただ、月額の給料では高くなるということです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"土井委員","kind":"確認","question":"もう一つ、次も確認です。現在における品川区の再任用の区の職員だったら、引き続きいろんなところでお働きになるときには、いわゆる月々の報酬、何ていうか、そういう報酬のほかに年に一定のものが支給される。その一定のものというのは今、何かありましたけれども。今度、採用するこの方々については、その種のがないということですか。","respondent":"桑村人事課長","answer":"それはなぜかというと、時間が短いとか給料の月額が低いとかということはありますけれども、ほかの手当関係も、いわゆる再任用独特といいましょうか、その年齢では当然もらえないような手当は別としまして、そのほかの手当は同じということなので、期末勤勉手当につきましても。","voiceIndex":15,"id":"exchange-005"},{"speaker":"本田委員","kind":"意見","question":"警察のＯＢということで、生活安全条例の施行からすると、地域の中で専門、いわゆる警察にいた人が取り締まりというのか、警戒をしていると、そういう名前の効果というのはあると思うんですよね。今、非常勤職員として今回、考えているのは３名って言いましたっけ、ちょっとそこをもう一回。","respondent":"桑村人事課長","answer":"現在、３名を予定しております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"本田委員","kind":"質問・要望","question":"そうすると、人数が必要だし、この地域にはＯＢがきていないと、その辺の割り振りといいますか、なぜ３名なのか。少なくとも４地域指定ですから、専門家が全地域にいるというのがあってもいいんじゃないかなと思ったりするんですけれども、これは所管外のことになってしまいますけれども、３人だけじゃ足りないわけですから、どういう人を今度は採るのか。ちょっとお聞かせいただきたいと思います。","respondent":"桑村人事課長","answer":"その間のいわゆる４地域の対応ですが、一つは職員が直接、管理職等も含めまして、一定、早番・遅番を含む体制をとるというようなこともありますし、また地域の方等の応援をもらいまして、その意味だと、３名の方が、今回は４地域ですけど、３地域にはある程度行けたり。","voiceIndex":19,"id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"仕事に関しては申しわけないんですけれども、この３名の方を中心にこの条例施行に当たっていくわけですけれども、即１０月１日から、あさってのことですけれども、違反者はいただきますよという行為に移っていくわけですか。","respondent":"市岡企画財政課長","answer":"条例の施行日が１０月１日ですので、いわゆる過ち料、過料については１０月１日から徴収ができるですが、この辺は実際の運用の中で、過度に権力的にならないように、啓発を中心に進めていくという考え方です。","voiceIndex":21,"id":"exchange-008"},{"speaker":"本田委員","kind":"提案","question":"これで終わりますけれども、警察ＯＢ、専門的な方が配置されて、できるだけ円滑に、効果的にこれを実行されていくということの趣旨での提案は、よく理解できます。その辺は今、課長のご答弁にありましたように、条例の本来の趣旨をしっかりと生かしていくために、無用なトラブルはできるだけ避けるように執行をしていっていただきたいなというふうに要望しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-009"},{"speaker":"土井委員","kind":"質問","question":"簡単なことなんですけど、服飾は支給とかなんとかというのはあるんでしょうか。着るものなんです。","respondent":"市岡企画財政課長","answer":"これはあす、補正予算のほうのご審議の中でご説明するつもりですが、基本的に制服、生活安全のお仕事、あるいは法規制、禁止の仕事をしているということが、区民の皆さんにわかるような制服を予定いたすつもりでおります。","voiceIndex":24,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"意見","question":"それがたしか４定のときも同じような答弁だったのが、年明けて１定になると、もう、すぐ急転直下、過料出るんだということをちょっと、何ていいますかね、変わったというふうな認識だったんですけど、そこら辺のところの区の考え方、どういうふうにして、そういうふうに変わってきたのかというようなことを改めて、どっかで説明があったのかもしれないんですけども、聞いておきたいんですけども。","respondent":"市岡企画財政課長","answer":"ほかの区でも、歩きたばこ禁止の対策はいろいろやっておりまして、当初、品川区は、なるべくモラルに訴えて、余り厳しい対応はしないで済むのならば、そういう形でやりたいと考えていたんですが、区民の皆様のご要望が大変強くて。","voiceIndex":27,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"核心はやっぱりその問題だと思うんですよね。それが、今のご説明ですと、区民の要望を受けてってということだっただけども、区民の要望を受けて、どういうふうにして、モラルのところから過料、罰則導入というふうな考えになったのかというそこのところが、何かよくわからないです。要するに、区民から要望があれば、じゃ、いろんなところで、そういうふうに変えるのかということなんですけど。","respondent":"中尾根企画部長","answer":"そういう状況を改めて把握し直して、じゃ、本当に、どうしたらそういうものをなくすことができるのかということで、罰則というものが一つの抑止効果があるんだとすれば、基本的にはとりたくはないんですけど、そういった措置もやむを得ないと、このように判断して。","voiceIndex":29,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとなかなか納得、私はちょっとわからないなと、落ちないところもあります。で、どなたかの質問のところでも、どっちが重点なんだということだったんですけど、こっちのほうが重点だというふうなご答弁だったんですけど、具体的にどういうことをやるのか。もうちょっと仕事の中身ですね、ちょっとお聞かせください。","respondent":"市岡企画財政課長","answer":"それから特定地域については、特に警察とか防犯協会と協議をいたしまして、そこについては重点的な巡回をするということと、平成１６年度中に４カ所程度のモデル地域を考えてございまして、この中で、今申し上げたような活動を重点的に行う。","voiceIndex":31,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問・要望","question":"わかりました。警察のほうの勧奨退職というのはかなり、どういうふうな動きが出て、自治体に対してどういうふうな要望が来ているのかって、そこら辺のところはどうなんでしょう。","respondent":"桑村人事課長","answer":"正直ですね、警察のほうでどのような勧奨をやっているか、私も知りませんので、大変申しわけないですが、ちょっと内容についてはお答えできないです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"川西委員","kind":"質問","question":"それで私も、所管課のほうに細則というんですか、できてるなら見せてもらいたいって言いましたら、９月初めです。たら、まだできてないからというので、区民委員会で出されて、そしたらいただこうかなと思ってる矢先だったもんですから。なぜ、この条例をつくるときに、重点地域というか、指定地域だけをつくって、区全域を対象にしなかったかというのは、どんなことなんでしょうか。","respondent":"市岡企画財政課長","answer":"ただし、規則で、特に重点的に、通勤のお客さん等が地域の皆さんに非常にご迷惑をかけているような地域について、規則で告示をしまして、そこを重点地域にしているということであって、過料、罰則をいただくのはその地域ですが、区民の皆様には、あるいは外来されている方には。","voiceIndex":35,"id":"exchange-015"},{"speaker":"川西委員","kind":"質問・要望","question":"わかりました。条例を読んでも、細かいことは出てなかったものですから、済みません。それで、私は、この非常勤の方が今回、年度途中３名、来年６名ということで予定されているんですから、全区的にまちを結局キャンペーンなさる時期もあると思うんですけど、やっぱりそういうことを区民の皆さんにもう少し詳しく、機会があったら教えていただきたいということをお願いしたい。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-016"},{"speaker":"林（宏）委員","kind":"質問","question":"あしたの説明で、組織の生活安全担当という部署ができるという、あした、説明があるんでしょうけど、担当という名前の部署はいろいろほかにもあるんだけど、この人たちの居場所といったら失礼だけど、所管の場所をそういうふうに定める。これは半永久的に生活安全担当というところに人を配置していくんですか。","respondent":"榎本行財政改革担当課長","answer":"それで、担当課長につきましては臨時的に置くという形、柔軟に対応できるような形の組織づくりしていますので、今のところ、生活安全条例の中の推進としては、生活安全担当主査を中心に非常勤を交えた体制で、推進していくという形にしたい。","voiceIndex":38,"id":"exchange-017"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、うがった見方をすると、この部署がいわゆる東京都の天下り先っていう感覚にならないですか。首をかしげてる人、たくさんいるんだけど。なりませんか。","respondent":"中尾根企画部長","answer":"特に安全条例、生活安全の対応の場合、やはり現実的ないろいろな犯罪の問題というのに直面したり、それから、どういうふうにやればいいのかという専門的な知識も必要だということですね。","voiceIndex":40,"id":"exchange-018"},{"speaker":"林（宏）委員","kind":"質問","question":"頼まれてじゃないのはわかるけども、結果的にはポストが、東京都のＯＢの行き場所ができてくるわけですよね、こういう順繰りね。そうすると、やっぱり、ある意味で、僕はこれから先、なぜかというと、本来、警察がやる仕事というのは、東京都のやる仕事じゃないですか。それを区がかわってやるという形になっている。それについてはどういうふうにお考えなんでしょう。","respondent":"濱野助役","answer":"したがって、このポストなり陣容なりを永久的に設置をしなければ、区の役割が果たせないかということになれば、決してそういうことではなくて、一定のところに到達すれば、人材としてのこういった方々が、未来もずっと必要だというふうには考えてございません。","voiceIndex":42,"id":"exchange-019"},{"speaker":"林（宏）委員","kind":"質問","question":"今の、先ほど来、出ているんだけど、防犯協会というところと協力して、防犯協会の組織って、どういう組織ですか。その人たちとこのＯＢが連絡し合ったって、人間がプラスになるだけで、なぜ防犯協会の事務局のそういう警察のＯＢの人の力を借りようとしないんですか。制服を着る。安全は確かにしなきゃいけないけど、警察官の仕事を肩がわりするようなことじゃないですか、これ。","respondent":"濱野助役","answer":"ただ、区が生活安全の仕事に手をつけて、区民の生活安全のためのいろいろな仕事を立ち上げるときのノウハウとしては、やはりそういった人材の活用が必要だという判断で、今回、招聘なり、採用なりをしているもので、防犯協会と協力をするという意味でも。","voiceIndex":44,"id":"exchange-020"},{"speaker":"林（宏）委員","kind":"意見","question":"だけど、僕はやっぱり東京都ときちんと、今、まさに財調絡み、あるいはいろんなもので、都と区の仕事の分担をはっきりしていくという中で、やっぱりこうやって全く東京都に勤めていた職員、今も勤めている職員、その人たちが部署を品川区役所の中につくるというのは、僕は東京都の仕事を肩がわりしているように思えてならないんで、そういうことについての配慮も、区としてはするべきだ、形の上でね。","respondent":"市岡企画財政課長","answer":"それで、こういう仕事が基礎的自治体で行わなければならないほど、東京の治安の問題というのはいろいろ問題を大きくしている中で、だとすれば、これからですけれども、財調の区側の提案の中では、品川区だけではなくて、地域の安全のための対策を。","voiceIndex":46,"id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"だからやっぱり、担当課長を設けて、そこに主査を設けてという、そういう形になってくると、なぜ東京都の仕事を品川区役所の中に置きかえなきゃいけないのかなという疑問が、どうも出てくるんで、それだけはちょっと気になるんで。これから、もしかして、この部署が広がっていったらえらいことになるなという気もしていなくはない。あそこまでべたべたビラを歩道に張りつけるということの意識は何なんですか。","respondent":"中尾根企画部長","answer":"ないしは出勤時の問題が、非常に朝夕のたばこを吸う場合は多いわけですから、そのことをはっきり認識させてもらう有効な方式として、ちょっとそのところを考え方としてはスタート時点では重視させていただいたですので、ご理解いただきたい。","voiceIndex":48,"id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そういう落書きのたぐいなんかもそうなんで、あれが効果があるという意識で張ったとしたら、そういうことにも僕は利用していけばいいけど、僕はあれは、今度は来る人たちに、はがすような意識を持たせたほうがいいと思いますので、それだけ要望をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-023"},{"speaker":"築舘委員","kind":"質問","question":"それはある程度、説明をしっかりして、そして、十分に区の、派遣で来るわけですから、課長さんというものがどういう方かっていうのは、もちろん立派な方が来ると思いますけど、そこはしっかりと位置づけをしておいてもらいたいというのが一点です。それは意見として言っておきます。その辺は基本的にという意味なんでしょうけれども、臨機応変にしておかないと。ただ、７時１５分から二交替制ですと。","respondent":"桑村人事課長","answer":"その意味で、もちろん仕事の内容によっては、夜遅くのこともありますでしょうし、また日曜日、重点的な関係があったり、相談体制になるというのは当然のことだろうと思いますので、そのことは十分、相談してまいりたいと思います。","voiceIndex":51,"id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"今、私の質問、３人の方の質問も聞いて、改めて思ったんですけど、まず生活安全条例の具体化ということだと、まさに私は、まず警察の仕事なんじゃないかというふうに私は思うんですね。もう一つ、ポイ捨てがあるんだというふうな説明だったんですけど、やっぱりこれは、私はモラルのほうできちっとやっぱり、こっちのほうを外さないでやっていくべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-025"},{"speaker":"林（宏）委員","kind":"意見","question":"一つだけ聞いておくね。ないということなんだけど、５月１日にかわって、２定だったよね。なぜこの３定までずれたかだけ、ちょっと……。","respondent":"桑村人事課長","answer":"それからもう一つは、先ほど申し上げたとおり、なかなか適用者がいないということがありまして、各自治体がその場の判断で、どこで条例を適用させるかということはございましたんで、基本的には大体、どこの自治体も３定でこの条例についての改正を行っているものだと思います。","voiceIndex":61,"id":"exchange-026"},{"speaker":"林（宏）委員","kind":"意見","question":"本来は２定で対応すべき問題でしょう。それが３定になったり、よそが大体３定だからというのは理由にならないんで。やっぱりやるべきことは、いないからいいやで済む話じゃないと思うんで、そういうのはきちんと、それこそきちんと、お役所仕事でやらないと、何で２定に出ないのかなと思うもんね、一般的には。それだけ、そういうことについてはやっぱり、きちんとしなきゃいけないものはしていきましょう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-027"},{"speaker":"川西委員","kind":"質問","question":"教育公務員特例法のことなんですけど、これはいつごろからできているんですか。それで、これが例えば幼稚園教育職員の資質の向上を図ると、あるいは、行政ではなくて、教員、小・中学校の教員、こう、する場合のそのぐらいの、ということなのか。どういう時代的背景から、こういうものができたのか、ちょっと教えてください。","respondent":"桑村人事課長","answer":"私どものほうは、先ほど申し上げたように、ちょっと歴史がまだ浅いですので、該当者がいませんけども、普通の方が申し出があれば、それから対応したいというふうに考えています。","voiceIndex":64,"id":"exchange-028"},{"speaker":"川西委員","kind":"質問","question":"わかりました。もう一つですけども、職場復帰もう一回しますよね、大学院課程をやって。その保証というのは１００％認めてくれてるでしょうか。","respondent":"桑村人事課長","answer":"基本的にいわゆる休業というんでしょうか、これについては復職が前提ですので、もちろん戻ってきていただいて、仕事していただくのが前提で、行っていただくということで、そういう知識を身につけられてやめられては、やはりこの制度をつくった意味がございませんので。","voiceIndex":66,"id":"exchange-029"}]},{"id":"topic-02","title":"第４９号議案、戸越幹線貯留管整備工事その１請負契約","agenda":"第４９号議案、戸越幹線貯留管整備工事その１請負契約","exchanges":[{"speaker":"宮崎委員","kind":"意見","question":"わかりました。この間、ちょっと参考までに、この間の直近のところでは大体、落札というのは大体この九十六、七％ぐらいが多かったなと思うんですけど、そこら辺のところは、この間の動きとの関係ではどうでしょう。","respondent":"西島経理課長","answer":"工事の金額によって、ずれがあります。ちょっと手元に資料はございませんけれども、大体、議会にかけ、お諮りするようなものについては、大体９５から９６ぐらいではなかったかと私は記憶しています。","voiceIndex":76,"id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。ほとんどシールドで組んで、工事自体がこれ、いわゆる下請けにどんどん出すという性格のものじゃないと思うんですけども、そういう面で、可能な部分というのは、この工事に関して、出てくるものなんでしょうか。","respondent":"矢部下水道河川課長","answer":"まだ実際に契約になっておりませんので、その辺の詳しいところはわかりませんけれども、土工等、これは推進工法ですので、その基本的な技術につきましては、その技術を持ったところが先進的にやっていきますけれども、それに伴う土工等、地盤改良もありますし。","voiceIndex":78,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問","question":"せっかく下水道の課長が来られてて、この貯留管というのは、下水道管じゃなくて、貯留するための管ということの理解で。このものの役割、さっき経理課長からお話があったとおり、ここに水をためる、字からいうと、水をためる管ですわね。この延長約４５０ｍぐらいの中に雨水を貯留させるための管なわけですか。その辺ちょっと、この工事そのものの役割をちょっと具体的に示してくれますか。","respondent":"矢部下水道河川課長","answer":"貯留管、貯留する形態としまして、今回のような貯留管と、それから調整池ですね、西品川公園にもありますけれども、そういうような調整池と、そういうような２つの形態がありますけれども、通常、速やかに流す形の下水管とは若干違うような役割を負っている管が貯留管です。","voiceIndex":80,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、たゆみがあるというか、たるみがあるというのか、そこにたまるようになって、上澄みというか、上側がこういうふうに流れていって。それとも、ポンプみたいなので、こういうふうに出しちゃうというような、いわゆる池方式なんですが、その辺まで、もうちょっと詳しく教えてくれませんか。","respondent":"矢部下水道河川課長","answer":"委員おっしゃられるとおり、２つの構造があります。自然に流れていってしまうものと、ポンプアップしてという形態の２つがあります。今回につきましては、自然に流れるような構造になっております。","voiceIndex":82,"id":"exchange-033"},{"speaker":"林（宏）委員","kind":"意見","question":"わかりました。そういう工事をするということで。その１となっているんだけど、どこまでその次が続いていくのか、それをちょっと説明。その２、その３、その４となっていくと、往々にしてというか、よくあるのは、ここで落札、この次は随意契約っていうのが出てくるのが、往々にして我々目にするんだけど、どのぐらいのスパンでこの工事、関連した工事が進んでいくのか。","respondent":"矢部下水道河川課長","answer":"その工事を一応、その２工事ということで、うちのほうでは考えしています。今、随契の話ですけれども、基本的に別件の工事に、要するに工事の場所が違いますので、どうしても随契でなければならないという、今のところは状況にはないのかなというふうには判断しております。","voiceIndex":84,"id":"exchange-034"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうことはこの入札に参加する人たちは、入札段階で、この先こういう工事があって、それについてはというような、今、建設やらない、現説にもならない、未来説明みたいな感じだけど、そういうことが伝わっているんですか。貯留管、今回のその１工事、その１ってつけてるんだから、その２が、あるいはその３がって想像できるわけですわね。それについては、入札参加した人たちは知っているんですか。","respondent":"西島経理課長","answer":"ただ、お話のありましたように、その１というふうに名前がついておりますので、じゃ、その２、その３はあるのかなというのは、業者サイドのほうでいろいろ情報を得たりというような行動はされるかと思いますが。","voiceIndex":86,"id":"exchange-035"},{"speaker":"林（宏）委員","kind":"意見","question":"東京都からは話は来てないの、それじゃ。受託なんでしょうけど、さっき下水道河川課長のほうが説明したように、この先こういう予定があるよという。行政と自治体、品川区としてはわかっているわけ、全体の工事はこれだけあるという、それはわかっているんですね。","respondent":"矢部下水道河川課長","answer":"その管を除きまして、残り２本の管を品川区のほうでやらせてくださいということで、お願いして、今回実現した経緯がありますので、そういう意味では、私どものほうではどういう場所で工事が出るというのは当然、承知しております。","voiceIndex":88,"id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"いろいろ入札という、何ていうのかな、活動というか、事業が一つあって、こういうふうに仕事が入ってくる。とかくいろいろ言われる。最後に一点だけ、これによって戸越の、いわゆる水が出る、戸越銀座に水が出るというののカバーリングはどのぐらい、数字に出せるんですか。役に立つということはわかるんだけど、数字的にどのぐらいというのは出ているんですか、それだけ最後教えてください。","respondent":"矢部下水道河川課長","answer":"それで、下水道局のほうでは、よく言うんですけど、５０mmの雨が降って、８０％の雨水が下水道管に入る計画を今、進めているわけなんですけど、現状は５０mmのうちの５０％の雨しか収用できない能力ですので、それを８０％にアップさせようという形で。","voiceIndex":90,"id":"exchange-037"},{"speaker":"本田委員","kind":"質問","question":"都の委託事業ということでありますけれども、これは財調の４８％の中に入っているお金なんですか、都のほうは。","respondent":"市岡企画財政課長","answer":"ただし、東京都が予算の中で色をつけているかどうかというのは、また都府県の仕事と、都が行う市の仕事の中で、明確に色をつけているかどうかというのは、なかなか難しいところですので。","voiceIndex":92,"id":"exchange-038"},{"speaker":"本田委員","kind":"質問","question":"基礎的な自治体の財源が、委託事業ですか、東京都から来るという仕組みで、お金は流れると、税金は流れるという理解でいいのかなというようなことなんです。","respondent":"市岡企画財政課長","answer":"ただ、下水道の仕事の中にも、この部分は非常に地域に密着したものですから、本来的に市の仕事だといってよろしいかと思うんですが、広域的な下水道の話とか仕事とか、いろいろ絡んでおりますので。","voiceIndex":94,"id":"exchange-039"}]},{"id":"topic-03","title":"平成１５年請願第１２号 品川区私立幼稚園児保護者負担教育費軽減の為の請願","agenda":"平成１５年請願第１２号 品川区私立幼稚園児保護者負担教育費軽減の為の請願","exchanges":[{"speaker":"川西委員","kind":"意見","question":"実際の入園料と、それから、従来出てきている差というのは、累計でわかったら。それから、預かり保育のことですが、それで平成１２年度から「きんだぁ」が出てくるというような形で、休日とか長期休業の際のはちょっとこっちへ置いておいて、４時までとか１時まで、あるいは３時までのを５時までとかというのは、どっちに入るかわかりません。この保護者負担の実態調査というのはされているのかどうか。","respondent":"宮地総務課長","answer":"預かり保育について、今、委託という形で、園に対しまして１００万円余、委託料でやってありますが、保護者のほうへの助成、補助金ということは今現在は考えてございません。","voiceIndex":102,"id":"exchange-040"},{"speaker":"川西委員","kind":"質問","question":"請願の結論を出すに当たってもう一つ、平均１１万円の入園料ということになりまして、そこまで引き上げるお金があるんですね。それが一つですね。それから、今の説明ですと、園によって、預かり、朝、夕方、あれですけども、幼稚園というのは１８時といっているのは６時のことじゃないですかね。１８時以前は無料という理解をしていてよろしいんでしょうか。その２つを。","respondent":"宮地総務課長","answer":"８万５,０００円で、平均の１１万円まで上げる予定はないのかですが、先ほどお話ししましたとおり、２３区といたしましてはかなり上位のほう、むしろ平均しまして、３万５,０００円ですから、相当上位のほうにあろうかと思いますが、今のところは５,０００円、今年度。","voiceIndex":104,"id":"exchange-041"},{"speaker":"築舘委員","kind":"意見","question":"大企業もいつ首になるかもわからないというような情勢もあるわけでして、そのときの所得が高くても、その辺は常に流動的という意味も含めて、等級といいますか、ランクを少し拡大するという考え方がないかどうかということと、それから、国と都とランクが4)と5)の人に分かれていますけど、その辺の説明をちょっとお願いしたい。","respondent":"宮地総務課長","answer":"むしろ、この６割を超えている部分の、補助金が何ももらえない４割の方がいらっしゃいますが、そういった方たちはかなり高額な所得ということになりますので、全体としますと、一定の６割の東京都の段階までカバーしているというところで。","voiceIndex":108,"id":"exchange-042"},{"speaker":"築舘委員","kind":"質問","question":"幼保一元化というような問題も出てきてますけれども、他区のほうなんですが、例えば千代田区・中央区・港区というのは、補助金は全くゼロと。これは何か特殊事情があってゼロになっているのか。一番トップが入園料の補助金が世田谷９万円で、こちら８万５，０００円ということですから、それなりに補助していただいているというふうには思いますけども。その辺の状況がわかりましたら、教えてください。","respondent":"宮地総務課長、本間総務部長","answer":"千代田・中央・港のゼロというのも、ちょっとこちらのほうでは把握しかねるんですけれども、それぞれの区の就学前児童数とか全体の施策に占める重さとか、そういうところもお考えがおありなのかなというふうに思っておりますが。若干補足しますと、この３区の私立幼稚園といいますと、ちょっと全国区的な有名な幼稚園が多うございまして、要するに区外から通ってくるような附属の幼稚園等が中心となってございまして、そういう関係から。","voiceIndex":110,"id":"exchange-043"},{"speaker":"本田委員","kind":"質問","question":"国のほうの１０万２,０００円の具体的論理というのは、所得のほうは。いわゆる都のほうしか、１４万円のところは幾らですか。","respondent":"宮地総務課長","answer":"それから１４万円以下のところですね、都の。こちらが７７０万円ですが、こちらもちょっと、いろいろ条件がありますので、参考までにということで。","voiceIndex":113,"id":"exchange-044"},{"speaker":"本田委員","kind":"質問","question":"区立の幼稚園は入園費は２,０００円だったよね。毎月のあれは今、８,０００円といったですね。少し上の６１.０３％になっておりますけれども、７７０万円ぐらいのところをもうちょっとこれは緩和できないだろうかなというふうに思うんですね。その辺ではどうなんですか。１５万円前後ぐらいまで、保育園の入園がね。その辺はいかがですか。","respondent":"宮地総務課長","answer":"ただ、あくまでも入園料というのは、公立の２,０００円に対しまして、平均で１１万円ですので、それにはなるべくということで、今回、５,０００円させていただいたという結果です。","voiceIndex":115,"id":"exchange-045"},{"speaker":"本田委員","kind":"質問","question":"４０代になって、小さなお子さんを育てるという方も結構、最近は目立ってきていますよね。そういうことを考えると、一方ではサラリーマンでもある程度の収入を得るというところもあるわけですから、ちょっと、そういう時代の流れ、背景というものも、見ていく必要があるんではないかなというふうに思うんですがね。これはちょっと意見を申し上げて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-046"},{"speaker":"宮崎委員","kind":"質問","question":"先ほど入園料のところで、平均１１万円ぐらいという話もあったんですけど、ちょっとそこら辺を実際に父母の方々の負担がどうなっているかというのをもうちょっと、わかったら教えていただければと思いますけど。","respondent":"宮地総務課長","answer":"先ほど、お２人の例でも申し上げましたけれども、お１人で払っている場合に、大体、平均で２万３，０００円の月額の保育料ですから、それに１２倍と、それから入園料は平均で１１万円ですので、それなりに。ただ、入園料は１回きりですから、翌年からはなくなりますので。","voiceIndex":118,"id":"exchange-047"},{"speaker":"宮崎委員","kind":"質問","question":"ここに対象の方々の数等はあるんですけれども、そこら辺のいわゆる負担感というのがどういう感じになっているのかというのは、何か数字でわかるようなものとか、あるいは区のほうの認識というものは何かわかるんでしょうか。","respondent":"宮地総務課長","answer":"園児保護者補助金につきましても、６割強の方がランク4)まで、特にランク4)のところに多く入っているわけですけれども、残りの４割の方がこれよりさらに上のところにいらっしゃるということで、一定の率の一覧はありますが。","voiceIndex":120,"id":"exchange-048"},{"speaker":"宮崎委員","kind":"意見","question":"東京都のほうの負担が相当あるはずなんですけど。保護者あて補助金のところでいいんですけれども、東京都の負担がどういうふうになっているのか。総額のところで見ると、ちょっとそこら辺の都の負担が、もちろん都の制度があって、それの上乗せ、ベースにはやっていると思うんですけれども、そこら辺のところはどういうふうになっていますか。","respondent":"宮地総務課長","answer":"ただし、区のほうでは月額７,０００円上乗せしておりますので、１２倍の８万４,０００円、これは減額しないで、変わらず、この間、補助として上乗せしています。","voiceIndex":122,"id":"exchange-049"},{"speaker":"宮崎委員","kind":"意見","question":"全体に、例えば補助金総額でいきますと、(1)の就園奨励補助金、そういうところで、実際にどういうふうになっているか、都の対応がどうなっているかというのはよくわからないんですけれども、そういうふうに就園奨励補助金となっているか。あるいは、込みでやっているのか、よくわからないんですけれども、例えば就園奨励補助金もそうですが、補助金総額が１億１,２００万円になっていると。","respondent":"宮地総務課長","answer":"国のほうですと、４分の１が国、４分の３が区と、先ほどちょっと申し上げましたけど。東京都のほうですと、額はちょっと細かくなるんですが、おおむねの割合でいきますと、品川のほうが多いので、４・６の割合で、区のほうが多く出しているです。","voiceIndex":124,"id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。そうすると、この前、一般質問でもちょっと触れたんですけど、今、東京都が第２次財政再建推進プランをつくると、そういう動きで、この１０月あたりをめどにつくろうという動きがあるんですけど、かなり私学助成とかが、かなり高どまりしているんではということで言われているんでけど、ちょっとこのところが心配な点はあるんですよね、東京都の動きは。","respondent":"市岡企画財政課長","answer":"東京都は第２次財政再建推進プランの中間のまとめを７月に発表しておりますが、その中では、検討を対象とするものを補助金としてリストを挙げただけで、具体的にそれをどういうふうに見直すかは、今度の最終報告といいますか、プランができた段階でのお話になろうかと思います。","voiceIndex":130,"id":"exchange-051"},{"speaker":"宮崎委員","kind":"質問・要望","question":"実際の父母負担の維持、父母負担の軽減措置というのを全体の水準としてどう維持していけるのかというのは、かなり心配な点はあるんですけれども、そこら辺のところ、東京都との関係というの、ちょっとこの連合会のほうが、東京都に対してどういう働きかけをしているのかわからないですけれども、一般質問でも取り上げたんですけども、やっぱり東京都に対してもいろいろ具体的なところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":132,"id":"exchange-052"},{"speaker":"武内委員","kind":"意見","question":"この園児保護者補助金のほうが、平成１４年からランク3)とランク4)が新たに加わったというか、それはおそらく１の就園奨励費補助金のほうはもとからこれ、ちょっと所得制限が緩和されている中での、それと比較して、こういう形になったのかどうかということ。","respondent":"宮地総務課長","answer":"ただし、それに対して区のほうで負担している補助の部分は、そういう形で分けないで、一律月額７,０００円の１２カ月分の８万４,０００円でプラスしていると、そういうことです。","voiceIndex":133,"id":"exchange-053"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと聞くのを忘れたんです。この要望のところで、３点目に連合会の助成というふうに書いてありますが、延長保育と区の考え方というのはどういうふうに。","respondent":"宮地総務課長","answer":"これはもう既に保護者の方への補助金という形も出しておりますし、園に対します支援という形でも補助金を出しておりますので、そういったことではそちらでお渡ししているので、そういう考え方で出します。","voiceIndex":135,"id":"exchange-054"},{"speaker":"林（宏）委員","kind":"質問","question":"そもそも論からいきたいと思うんですけども、出していただいたこの資料、補助金がいろいろ出てます。そもそも補助金を出すという品川区の考え方、原点。こういうことなんで、幼稚園に、それから保護者の人に補助を出すという原点は何ですか。","respondent":"宮地総務課長","answer":"非常に厳しい経済状況の中で、私立幼稚園の設置者の方々は頑張っていらっしゃる。そこもやはり区としては、お願いしている部分を補助金の助成するという形で応援をしていきたいと、そういう考え方で始めているんだというふうに理解しております。","voiceIndex":137,"id":"exchange-055"},{"speaker":"林（宏）委員","kind":"意見","question":"少子化と言われる時代はいつからか認識が違うと思うんだけど。昭和４４年、４７年ごろは、少子化がまだ始まってないのに、品川区でもう６,０００人ぐらいの子供が誕生してた時代。その時代に少子化の解消のためなんていう理由はなかった。そもそもこの補助金というのは、公私格差をなくしていくという考え方が、基本的にあるというふうに僕は認識しているんだけど、違いますか。","respondent":"宮地総務課長","answer":"公私格差是正というのがありますので、そこをやはり大部分担っていただいている私立のほうに、区としても何らかの支援という形での助成制度というふうに認識いたしました。","voiceIndex":139,"id":"exchange-056"},{"speaker":"林（宏）委員","kind":"質問","question":"なかなか公私の格差が、どこでその差をカウントするかというのは非常に難しい。私立に行っているご家庭、あるいはお子さんに向けての税金の配分はどのぐらい、あるいは、公立の幼稚園に行っているご家庭、あるいはお子さんに対して、どういうふうにというその差も公私間の差というふうにカウントできるのかなと思うんですよね。そういう認識でよろしいでしょうかね。","respondent":"本間総務部長","answer":"確かに私立幼稚園のほうが若干、通常の平均的なところの園を選べば、若干高くなるかなというようなことなんですが、区では一方ではこういう直接保護者に出す補助金だけではなくて、私立幼稚園側もそういう教育費等を上げないように、幼稚園そのものに対する助成等も。","voiceIndex":141,"id":"exchange-057"},{"speaker":"林（宏）委員","kind":"質問","question":"いわゆる就学前のお子さんたちの教育、幼稚園の場合はそういうことだけど、私立の幼稚園、保育園も含めて、頼らざるを得ない。一般質問でうちの委員長も取り上げてした次世代育成事業、部長はもう品川区はほとんどやっているからいいんだみたいに、随分、胸を張って堂々とおっしゃられていたんだけど、こういうことも含まれて、計画が練られていくというふうに理解していていいですか。","respondent":"中尾根企画部長","answer":"したがいまして、子供さんがオギャアと生まれてから、学校を卒業して、そして育っていく青少年ぐらいまでのところを何を本来やるべきか、幅広く検討したいと考えています。","voiceIndex":143,"id":"exchange-058"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"たまたまあと、来年いっぱいぐらいに計画をつくり上げていく、そういうスパンだと思いますので、そういう中に生かしていっていただきたい。さっき言ったそもそも論から始まれば、ここに言われていることはごもっともというふうに聞かれる心を持ってらっしゃるというふうに信じて、次世代の部分にこれから取り組んでいくと思いますんで、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-059"},{"speaker":"林（宏）委員","kind":"意見","question":"ただ、いろいろ、今年５,０００円上がって、なかなか連続というのもあれだろうし、財政的な検討をされるということでありますから、十分、趣旨は理解し、決して後退じゃないというふうにくぎを差しながら、趣旨採択で、きょう決めていっていただければありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-060"},{"speaker":"土井委員","kind":"質問・要望","question":"このことについては、区議として聞いていかなきゃならんことだなということだというふうに理解をしておりますし、それぞれが、予算要望の時期ということもあっての内容ですから、ぜひ、こういう予算の要望というものも、こういう皆さんから出ているんだというのがおわかりをいただける議論であったというふうに私思うんですから黙っているんで、ぜひそのような形で趣旨採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-061"},{"speaker":"本田委員","kind":"質問・要望","question":"企画部長のほうからもご答弁がありましたですね、就学前の子供さんに対して、どう次世代をにらんで税の配分をするのかというような大きな観点から、ぜひとらえていただきたい。品川の置かれている区民の置かれている状況を理解していただきたいというふうに思っております。そういう意味で、趣旨全体を採択ということについて、結構ですので、きょう採決をしたらどうかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-062"},{"speaker":"川西委員","kind":"質問・要望","question":"それで、要望としてありました、先ほど申し上げたように預かり保育という「きんだぁ」「とどらぁ」、この充実を今後一層図ってほしいという、私は、私が一般質問だか総括だかしてましたのをやりました。やっぱり保育園だけじゃなくて、幼稚園も時間延長保育の内容充実を切に要望して、賛成です。今、皆さんがお出しになった趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-063"},{"speaker":"本田委員","kind":"質問・要望","question":"ちょっと私も確認しておきます。趣旨採択をということなんですけど、３番目の連合会、運動団体への助成というのが、他の区の助成しているいろんなのがありますよ。町会を含めて。そういうことは、見るところはきちっと見て、ご判断を適切にしていただきたいということを含めて、趣旨採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-064"}]},{"id":"topic-04","title":"平成１５年請願第２１号 東京法務局品川出張所の移転計画を早急に撤回する請願","agenda":"平成１５年請願第２１号 東京法務局品川出張所の移転計画を早急に撤回する請願","exchanges":[{"speaker":"林（宏）委員","kind":"質問・要望","question":"今よく言われる、役所の場合だとワンストップってよく言われるけど、私たちが区役所に来て、登記所に行かなきゃいけないといったら、また３０分、１時間かけて行って、証明をもらってきて、また区役所に出すなんていうそういう非常なむだが生じてくるということも考えると、やっぱりあと二、三年はｅジャパン計画に沿ってというか、の関係で、動かないというふうになっているんだけど。","respondent":"西島経理課長","answer":"まだ当区としては最終的な決定をしているわけじゃございませんけども、一方に委員会での討議を踏まえまして、前回も委員会で意見書採択、本会議で意見書採択という動きを踏まえまして、区のほうとしても、要望書をあわせて出したですので、その辺。","voiceIndex":160,"id":"exchange-065"},{"speaker":"林（宏）委員","kind":"提案","question":"とすると、議会がイニシアチブを持って動いていきたいというふうに思いますので、もう一度、撤回を求める意見書をこの委員会から提案して、品川区議会として法務局、国のほうへ働きかけていき、あわせて、品川区も動いていただくということを、これは委員長からか議長からかわかりませんけども、意思はあるようですから、強く、議会の行動を注視していただいて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":162,"id":"exchange-066"},{"speaker":"宮崎委員","kind":"提案","question":"今の提案でいいと思うんですけども、ちょっと参考で出していただければと思うんですけども、そういう意味で、議会の立場、区の対応というのはこういうことで理解しますけど、国のほうがどういう理屈で移転を考えているのか。論点がどういうふうになっているのか、ちょっとそこら辺が今よくわからないんですけど。","respondent":"西島経理課長","answer":"国の今回の出てきた動きですけれども、政府の行政改革の一環として閣議決定をして、民事行政審議会の答申を受けた形での一定の動きの中の一つだというふうにご理解いただければと。","voiceIndex":163,"id":"exchange-067"},{"speaker":"宮崎委員","kind":"意見","question":"行革の一環で出てきているというのは何となくわかるんですけど、いわゆる理屈ですね。それがなぜ、あえて向こうのほうなんだというのが、何かよくわからないんですね。そこのところが、どういう理屈でそっちなのか。それに対して、こっちがどういうふうに反論しているのかというのが、少なくとも私のいうところですね。","respondent":"西島経理課長","answer":"品川区の件数は十分認識しているという回答でございました。","voiceIndex":165,"id":"exchange-068"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっと感想で、いわゆる、これから国との論争をどういうふうにしていくのかというのは、ちょっと、余り今、よく見えないんで、参考までに聞きました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":167,"id":"exchange-069"},{"speaker":"林（宏）委員","kind":"意見","question":"さっきもお話ししたように、区側も同じ考えでいらっしゃるということだし、区民も同じ考えで、議会ももちろん同じだ。やっぱり意思表示が必要だと思いますので、採択をして、正副にお任せしますので、意見書をつくって。有能なる正副委員長さんにご依頼申し上げまして、意見書をよろしくつくり上げて、出すということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":170,"id":"exchange-070"},{"speaker":"中島副委員長","kind":"質問","question":"公明党としての立場で今、意見を述べさせていただいていますが、行政改革というのは、あくまでも、できるだけコストを安くして、住民サービスを主にしていくというそういう点で、やはり今回の、もし移転で、まだまだ不便を感じるところがたくさんあるわけですから、その辺のところをしっかり区として私たちも強調していきたいということでいきたいと思います。採択。意見書を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-071"},{"speaker":"土井委員","kind":"質問・要望","question":"私どもも、その線でぜひいっていただきたいというふうに思っています。きょうご説明があったような内容等もいろんな見地のところから、我々のほうも重視をいたしておりましたけれども、見よう考えようによっては、だから移るのよというふうにもとれるんですよね、今の発表は。そうじゃないんだよということをやっぱり出しておかなきゃいけないんではないかと、このように思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-072"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1626#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":48421,"voices":181}},{"id":"h15-20030930-6","meetingId":"h15-cm09","date":"2003年9月30日","dateIso":"2003-09-30","committee":"区民委員会","time":"午前１０時０８分～午後１時３７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"民間の葬儀場を使っての、いろいろランクはあるようですけれども、最低ランクと、あるいは一般的なランクと比較してどのくらいなのかなというのをちょっと知りたいので、もしその辺がわかったら教えていただきたいというのが一つと、それから、見学会についても説明をいただきまして、一般の区民の方も見学できるということで、ありがたいなと思うんですけれども、結構区民の方たちの関心も高くて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"あるいは仕出しの食事というんですか、あるいはお花代、あの辺の部分は全然手つかずなんですよね。一つ花をとってみると生花一つ１万５,０００円と言いますけれども、その値段が１万５,０００円が妥当かどうかというのはありますよね。器をつくりましたよ、その他は考えているんでしょうか。ちょっと難しいかもしれませんけれども。","respondent":"長田区民課長","answer":"こちらのほうも２種類ほどございまして、ＡとＢというふうに分かれていまして、これは段飾りのグレードにもよったり、その葬儀のグレードにもよりますけれども、Ａのほうが６２万円、それからＢのほうは４８万円ということで。","voiceIndex":10,"id":"exchange-002"},{"speaker":"松澤委員","kind":"意見","question":"今の協定料金のほうも見直す方向でということで考えていらっしゃるようですので、それでよしとしますけれども、なかなか難しい問題ですけれどもね。できる限り、こちらも安くできるような形にしたんならば、もっと区民の利便性を考えてということですので、商売でありますので、そこのところは、言えるかどうか知りませんけれども、努力のほうをよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"関連して。今、臨海斎場を設定した新しい料金を考えるという話で、それはそれでほんとうに予想していなかっただけに、よかったなと歓迎できるんですけれども、そうすると、今あるＡとＢのこの２ランクのこれは、このままであるわけですか。","respondent":"長田区民課長","answer":"それで、当然そういった考えから、桐ヶ谷斎場を使ったときの協定料金の現在のＡとＢと、それから今度新しく臨海斎場を使った場合、これは１種類になるのか２種類になるのかわかりませんが、そういったことでの料金設定が、今度２本立て。","voiceIndex":13,"id":"exchange-004"},{"speaker":"嶋委員","kind":"質問","question":"火葬料が２万３,０００円で骨壺を含むということなんですが、桐ヶ谷斎場もそうですが、骨壺もランクがあったりとかするんですけれども、臨海斎場に関しては、骨壺はランクはないんですか。","respondent":"長田区民課長","answer":"現在のところは、骨壺は品川区の品川総合福祉センターの授産事業としてつくっていただく予定です。ランクについては大人と子どもの大きさの違いはありますけれども、それぞれの骨壺は１種類です。","voiceIndex":15,"id":"exchange-005"},{"speaker":"嶋委員","kind":"質問","question":"これは人間ということなんですが、動物の火葬に関しては、考えていらっしゃいますでしょうか。","respondent":"長田区民課長","answer":"こちらにつきましては、人体の一部ですとか、そういう部分はありますけれども、動物については想定をしてございません。","voiceIndex":17,"id":"exchange-006"},{"speaker":"田中副委員長","kind":"質問","question":"いよいよ完成ということなんですけれども、これまではなぎさ会館が近隣にありまして、臨海斎場の完成後のなぎさ会館にとっての影響というんでしょうか、どれだけ影響があるのかということをどう想定されているのかということと、ゆくゆくは臨海斎場のほうにシフトされると仮定するならば、なぎさ会館の使用のあり方というものを将来的には検討していかなきゃいけない、将来的な課題かもしれませんが。","respondent":"長田区民課長","answer":"それで、副委員長がご提案いただきましたとおり、なぎさ会館のほうが著しく減るようなことがあれば、それはそれで当然将来に向かってどうするかという検討の必要性はあろうかというふうに思っているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"木下委員","kind":"質問","question":"ちょっとわからないのでお聞きしたいんですけれども、葬儀社が協定葬儀ということで、今先ほどお話があったように、すごく葬儀費用が高いということで、一部民間企業で価格破壊ですか、葬儀費用の面についても葬儀社がいろいろ行われている状況の中におきまして、協定葬儀ということだと、これは別段ほかのそういう価格破壊するような葬儀社でも、使えることは使えると理解してよろしいんでしょうか。","respondent":"長田区民課長、高星委員長、市川産業振興課長","answer":"そういった業者が依頼をして、ここでやるというのは、もうご宗家の意向の問題ですので、何ら支障はございません。ほかになければ、これで１の臨海斎場についてを終了したいと思います。(2)の「品川区年末対策特別事業資金２００３」の実施について、理事者からご説明をお願いいたします。","voiceIndex":24,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"このごろメディアの報道なんかでは、自分はそうはあまり感じないんですけれども、景気は底打ちしたというような報道が出ているんですけれども、実際に事業主または従業員の方と窓口で接しられていると思うんですが、そういう生の声といいますか、何か感じるものがありましたら、ちょっと報道とは違うんじゃないのかとか感じるものがありましたら、お伺いしたいと思います。","respondent":"市川産業振興課長","answer":"これまでなかなか設備投資が動かなかったんですが、例年に比べて３０％ぐらい今年度春から設備投資が動いております。これを一つの好転のきざしとして見るかどうか、その辺はもうしばらく推移を見てまいりたいと考えています。","voiceIndex":30,"id":"exchange-009"},{"speaker":"三村委員","kind":"質問","question":"基本的な質問でちょっとよくわからないものでお聞きしたいんですけれども、この事業というのは、直接区が融資するわけではなくて、融資をあっせんするという事業という感じなんでしょうか。通常、想定されるもし補助をするということで、どの程度融資を今年度は融資あっせん、融資実行のほうを想定した事業規模を想定金額があれば教えていただければと思います。","respondent":"市川産業振興課長","answer":"ちなみに、今おそらく信用金庫で利率は市場金利というのはおそらく２.８％ぐらいになっているかと思いますので、かなり低利の利率で受けられるということになります。それと、今年度の新規の融資枠というか、私どもが想定している融資枠が７８億円ほど予定をしています。","voiceIndex":32,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"それだけの枠を想定していただいているということについては、今の視野というのを、区側の思いというのはよく伝わってくるような気がするんですけれども、実際昨年度までの実績で、融資を受けたいと思った方たちの傾向ですか、中身、融資を受けたお金でどういうふうな使い方をしているのかというところがもしわかればでいいんですけれども、教えていただきたいと思います。","respondent":"市川産業振興課長","answer":"７８億円と申し上げましたのは、ただいま説明させていただいた緊急融資を含んで年度全体で７８億円の枠を予定しております。そのうち、今回は２０億円を一応想定をしています。","voiceIndex":34,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"できたら私はあっせん件数も伺いたかったなというふうに思うんですけれども。あっせん件数と、そしてあっせんというのは、いわゆる区が金融機関のほうに紹介する件数というふうに理解しているんですけれども、それ以前に相談に来て、ちょっとこれは無理じゃないですかと区が判断して紹介には至らなかったという数字があるのかなというふうに思うんですけれども、そこも伺いたいと思います。","respondent":"市川産業振興課長","answer":"個別には前段の傾向で今申し上げたものを１割ぐらい積み上げていただくと、それで近時は、この二、三年は１５％ぐらい積み上げていただくと、大体そのような数字になる。","voiceIndex":36,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"だからどうこうということではないんですけれども、ほんとうにそういう実態の中で、ご苦労して経営を維持して、できるだけ負担を大きくしないように、倒産に至らないように頑張ろうという、そういう経営者の方々がいっぱいいるということを改めて実感したんですけれども、そういう中で５００件ぐらいずっと来ているという、そういう状況。","respondent":"市川産業振興課長","answer":"平成１０年のときは、この年だけが極めて突出している年でございまして、これは平成１０年１０月から１２月にかけて、このときには３カ月間にわたって打ったときなんですが、時折しも政府が景気対策として特別信用保証枠ということを設けまして、たしか。","voiceIndex":38,"id":"exchange-013"},{"speaker":"田中副委員長","kind":"質問","question":"ほかにありますでしょうか。ないようですので、これで２の「品川区年末対策特別事業資金２００３」の実施についてを終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"品川区は、プレミアム付商品券は初めてつくるということですが、他区がやっていれば、他区の状況を、どんな成果が出たよとか、こういうところが心配だとか、あれば教えてください。","respondent":"市川産業振興課長","answer":"他の団体でのプレミアム付商品券の発行状況ということかと思いますが、私どもつかんでおります限り、品川区を除いて、既に２３区のうちの８区で何らかのプレミアム付の商品券の発行事業が行われてあります。","voiceIndex":44,"id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"そこでなんですけれども、今まで、品川区において、プレミアムの商品券を販売しなかったのに、なぜ今の時期に今回販売することになったのかということが、積極的に区も今回行うようにしていると思うんですけれども、一つ考えるのは、１０％のプレミアムがつくときにいっぱい券が売れるよ、買うよという状態だけになったらまずいんじゃないかなという気持ちがあるんですけれども、その辺はいかがでしょうか。","respondent":"市川産業振興課長","answer":"それで、このチラシの冒頭「商店街がんばる宣言」というのがありますけれども、今回、区内の商店街、どのようにこのプレミアム付商品券の流通に向けて頑張っていただけるかというのは、ひとつ期待をしたいところということで考えております。","voiceIndex":46,"id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"たしかなんですけれども、中延商店街で実際にこれに似た形で現在しているか、するというようなお話を伺ったんですが、もしわかれば、その辺の状況を教えていただければありがたいんですけれども。","respondent":"市川産業振興課長","answer":"今、中延商店街のお話がございましたけれども、もういわばあと１カ月後にこの獲得競争が始まるわけでして、おそらく今委員のおっしゃったのは、商店街で用意している立て看板とか横断幕だとか、そういうものはもう気の早いと言っては怒られてしまいますけれども。","voiceIndex":48,"id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"最後なんですけれども、販売方法で郵便局のみでの予約販売と今回なっておりますが、この郵便局のみにした背景というのはあるのでしょうか。","respondent":"市川産業振興課長","answer":"この区内２４カ所予定していますけれども、振替でやりますと、どこの引換場所にどのぐらいのお客さんが来るということがあらかじめ数字の把握もできるということで、これもあわせて販売管理という面からはメリットがあるということで、あと、これだけに販売方法を絞ったことで。","voiceIndex":50,"id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"それは当然ながら、これだけのプレミアムがつくんだから、使えないと、利用しないと損ですよという呼びかけもあると思うんですけれども、それと同時に、この相手方である品川区商店街連合会側がもっともっと努力していかなくてはいけないと思うんですけれども、これだけのプレミアムをつけるからには、こちらの産業振興課としても品川区商店街連合会に対してもっと販路を広げなさい。","respondent":"市川産業振興課長","answer":"私どもは、この数字を一体どうやって増やしていくのか具体的な方策を一緒に考えましょうということで、幾つか検討してまいりました。","voiceIndex":52,"id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"よくわかりました。もう一つお話が出たかどうか、ちょっと聞き漏らしている部分があるかもしれませんけれども、これは期限が切れちゃったのは、どうなるんですか、使えないんですか。それとも１割引きのプレミアムがないもので使えるのか、その点はどうなんでしょう。","respondent":"市川産業振興課長","answer":"ただ、実際にこれは通常の場合の共通商品券も５年の有効期限を付していますけれども、なかなかやはり店先でお客様が実際に持ってこられると、その辺は建前と本音のちょっと難しい線がありますけれども、今回の場合は、特に先ほど申し上げた、短期回収という目的がありますので。","voiceIndex":54,"id":"exchange-020"},{"speaker":"嶋委員","kind":"質問","question":"松澤委員のお話と重なるところがあるんですが、実は前に地域振興券のときに、やはり取扱店が大変少なくて、私も地元の商店街にほんとうに１件１件回って取り扱ってほしいという形で回った記憶があるんですが、そのときに商店街の方が言われたことは、地域振興券、お店の方が持って、それを取りかえにお金にかえていくときに、大変ちょっと手間暇かかることと、それと。","respondent":"市川産業振興課長","answer":"以前実施いたしました地域振興券のときと換金のシステムがちょっと若干違うんですが、ただ、今委員がおっしゃったように、毎日例えば２万円も３万円も共通商品券が来るのだったら別なんですけれども。","voiceIndex":56,"id":"exchange-021"},{"speaker":"嶋委員","kind":"意見","question":"換金という意味では簡素化を進めることという流れができているということなんですけれども、今の信用金庫とおっしゃったんですけれども、郵便局をせっかくこういう形で取り込んで、郵便局はどのような、これに関して換金システムの中にあるのか聞いておきたいと思います。","respondent":"市川産業振興課長","answer":"これは、一般金融機関、これは郵便局もそうなんですけれども、そこを使いますと、いわゆる手数料を取られてしまいますので、それが結構この事業にとって大きな意味合いを持っておりますので、それで地元の信用金庫に限って換金をしているという、そういう経緯があります。","voiceIndex":58,"id":"exchange-022"},{"speaker":"木下委員","kind":"質問","question":"よくほかでも８区がやっていらっしゃるということなんですけれども、かなりそれでもって効果が出ているところがあるのか、またほかのところと変わらないことをやっていて効果があるのかなという気もしますし、あと、小売店がこれを取り扱うことによって手間暇がかかる分、例えば小売店としてのメリットがあるのかどうなのかというのをお教えいただけますでしょうか。","respondent":"市川産業振興課長","answer":"つまり、これですべて商店街の活性化が見込めるものだとは私どもも思ってございませんし、やはり商店街がこういう取り組みをする中で、特に地域の中で商店街は、やはり地域あってのものですので、地域の中で存在感を示して。","voiceIndex":60,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"基本的なところでわからないので教えていただきたいんですけれども、１万円買うと１万１,０００円分の買い物ができるということで、ここを見ると５００円券が２２枚ついてくるということですよね。それで、この２２枚には丸特という印があるんでしょうか。プラス１,０００円分というのは、この丸特が書いてあるのは１月３１日過ぎちゃうと、もう全然使えないという、そういう理解なんですか。","respondent":"市川産業振興課長","answer":"つづりで売らせていただきます。それがこの２２枚つづり。要するに１万１,０００円分が一とじになっていまして、それを１万円で購入していただく。それで、もちろん通常出回っている商品券と違いがわかるような表示がしています。","voiceIndex":62,"id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"その何か特別の印がついているプレミアム付の商品券は、１枚であっても２枚であっても、とにかく１月３１日までに使わないと使えなくなっちゃうのが基本で、さっきいろいろなお店の方とのやりとりの中で、必ずしもというのはあったようですけれども、基本的には使えなくなっちゃうんですか。家の中に１枚とか２枚とかどこの家庭にも商品券はありますよね。それはもういつでも使えるわけですよね。","respondent":"市川産業振興課長","answer":"この目的は、今委員がおっしゃったような、たんすの中にしまい込んであるような商品券も改めてそういうものを探していただくなり見つけていただいて、この期間のうちに商品券を使えば、このプレミアム付と同じようにサービスが受けられるので。","voiceIndex":64,"id":"exchange-025"},{"speaker":"三村委員","kind":"意見","question":"１件だけ、その２２枚つづりというのは、別にばらしても使えるということの理解でよろしいのかということと、あと、先ほどご利用になりますかという声かけまではということだったんですけれども、実際私も何枚かいただいて、ほんとうにどこのお店で使おうかなというのが、お店の人の顔色を見つつ、使えるというシールを見つつ、どこで使おうというのは、ほんとうに３枚、４枚の数だったんですけれども。","respondent":"市川産業振興課長","answer":"それから２点目のことについては、先ほど申し上げたとおりですけれども、特に私どもの区民生活事業部長がその辺を強く品川区商店街連合会の役員のほうに申し入れを行ってありますので、あと３カ月、４カ月の推移ですけれども、またいろいろご利用いただければと思います。","voiceIndex":66,"id":"exchange-026"},{"speaker":"松澤委員","kind":"質問・要望","question":"あるいはここにいらっしゃる理事者全員が５万円のお金で使ってみる、果たして商店が気持ちよく売ってくれるのかどうか実態を調べるぐらいの気構えを持っていただきたいと思うんですが、その点いかがでしょうか。","respondent":"太川区民生活事業部長","answer":"これにつきましては、私ども管理職等も通じまして、ぜひ実践をしてみたいというふうに考えてあります。いろいろな形で声かけはしてまいりたいと考えています。","voiceIndex":70,"id":"exchange-027"},{"speaker":"田中副委員長","kind":"質問・要望","question":"区民生活事業部長を中心にご利用いただきながらという、そういう意味で、ぜひこの事業に対して職員の皆様のご支援もいただきながら、また区の役割として、こういった補助をするだけではなくて、この全体を効果的な形にしていく上でも、いろいろな形で区としても区の立場でバックアップなりをしていかなきゃいけない部分がたくさんあるかと思うんですが、例えば先ほどのお話では、商店街なり個店の努力。","respondent":"市川産業振興課長、高星委員長、冨田戸籍住民課長","answer":"それで、私どもが昨日説明させていただきましたにぎわい助成事業という助成事業の対象商店街、そこの連絡組織みたいなものを持ってありますので。以上で、３のプレミアム付商品券の発行についてを終了いたします。続きまして、(4)の住民基本台帳ネットワークシステムの実施状況について、理事者からご説明をお願いいたします。それで、住基ネットの第２次サービスの実施状況ですけれども、運用開始としましては、政令の定めに従いまして。","voiceIndex":72,"id":"exchange-028"},{"speaker":"三村委員","kind":"質問","question":"先ほど事務処理の効率化、省力化ということでお話があったかと思うんですけれども、そのコストはどのように変化をするのか、把握していらっしゃれば、教えていただければと考えています。人件費ですとか、機械のランニングコストとかを含めて、どの程度の効率化を見込まれているのか。","respondent":"冨田戸籍住民課長","answer":"来年の１２月に除籍の電算化が図られて、完成するということで、今年度も若干の見直しは予定はしていますけれども、最終的にはまだ確定はしていない状況です。","voiceIndex":81,"id":"exchange-029"},{"speaker":"南委員","kind":"確認","question":"文字告知のところがよくわからないんですけれども、通常の生活ではあまり難しい字とか読めないような字というのは使いたくないということで、使わないで過ぎていますよね。それはそれとして理解できることですけれども、そうすると、戸籍そのものにもなくなっちゃう、残らなくなっちゃうということなのか、ちょっとその辺を確認したいんですけど。","respondent":"冨田戸籍住民課長","answer":"それについては、その趣旨を尊重するということになります。電算化する場合には、これにしなければなりませんので、その方については電算にしないという、現在の紙の戸籍のまま継続をするということになります。","voiceIndex":83,"id":"exchange-030"},{"speaker":"南委員","kind":"質問","question":"でも、通常の生活ではちょっと面倒くさいなということもあるので、下の心だけなんですけれども、それが正しい字なのかどうかというのはちょっとよくわからないところで質問をしているので大変申しわけないんですけれども、親の思いというのがあって、その字を使って戸籍上登録してというふうになっているけれども、自分が実際に生活上面倒くさいから使わないと、そこのところの関係というのは。","respondent":"冨田戸籍住民課長","answer":"それで、電算処理に関しては、戸籍事務を電算処理だけでやるということができるようになったのが平成６年の法律改正で、それから電算処理ができるようになったわけですけれども、これも同じような、平成２年と同じような考えで、言うなれば新しい戸籍をつくる。","voiceIndex":85,"id":"exchange-031"},{"speaker":"南委員","kind":"質問","question":"紙の戸籍として本人が希望されれば残せるというところがあるから、わかりました。あまりこだわるつもりはないんですけれども、一人一人の考え方の中でそういうのはあっていいのかなというふうに思ったので、わかりました。当然もう十数年も前の話ですから、国民的合意というのは当然とれているということで理解していけばいいのかなというふうに思うんですけれども、そういうことですよね。","respondent":"冨田戸籍住民課長","answer":"過去にやっている自治体の状況ですけれども、どうしても従来のままと申し出がある方は、数字は１００件いかないんで、何十万戸の中で数十件の範囲でという状況で、一応ご理解はいただけるものと考えています。","voiceIndex":87,"id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"３回ほど推進会議というのを開く予定なんですよね。これは、２月ごろまでの予定しか書いていないんですけれども、改めて、この公募された方も含めて、この推進会議の任期という言い方をしていいんでしょうか、その任期と、そして投げかけるテーマみたいな、そういうものと、それから、今後のこの３回の会議の内容はどんなようなものに予定されているのか教えていただければと思います。","respondent":"金井環境課長","answer":"任期ですけれども、任期は２年を予定しております。再任は妨げないです。それから、今後の予定ですけれども、１０月は皆さんのお顔合わせということと、この会議のあり方ですとか今後の進め方等々の確認をいただくという予定で考えております。","voiceIndex":94,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことで考慮されて、これから区のほうでも事務局として運営されていかれると思いますけれども、改めてちょっとその辺の考え方みたいなのを教えていただければと思います。","respondent":"金井環境課長","answer":"今、私どもでこの会議の運営のあり方、そういったものの内容について検討しております。この中では、今委員ご指摘のように、未来を担う子どもたちの育成というのを会議の一つの大きな役割に入れようというふうに考えております。","voiceIndex":96,"id":"exchange-034"},{"speaker":"三村委員","kind":"質問・要望","question":"応募者数が２１名で選出者１１名ということなんですけれども、この１１名を選んだ基準みたいなものがあれば教えていただきたいということと、先ほど分科会の設定等を検討していきたいということだったんですけれども、応募された方で、選出されなかった方は、こういった分科会等の参加等、何かほかに参加する機会などを考えられているのか、もし考えていらっしゃれば教えていただければと思います。","respondent":"金井環境課長","answer":"１１名以外の方ですけれども、まだ具体的に考えておりませんが、できればそういった分科会を設置をした時にお声かけを、区としてもそれなりの活動をしている方もいらっしゃいますので、できる限り活用していきたいという考え方は持っております。","voiceIndex":98,"id":"exchange-035"},{"speaker":"松澤委員","kind":"意見","question":"それで１１名選考されたということなので、やはり今の現在における環境問題に対する関心の高さ、その中で、３名を増やしたということは皆さんの質がよかったので増やしたのかなというような気がしますけれども、中学、高校、大学生なんですけれども、この方たちは、それぞれ意識が高いということもあったんでしょうけれども、やはり定員いっぱいしか応募が来ないということは。","respondent":"金井環境課長","answer":"委員のご指摘のとおり、大変中、高、大学生の中で情報提供が、私ども広報のあり方が若干もう少しきめ細かにやればいいのかなというふうに反省をしていますけれども。","voiceIndex":100,"id":"exchange-036"},{"speaker":"松澤委員","kind":"質問","question":"やはり中学生、高校生というのは、国民性なんていうと怒られちゃうけれども、外国ではどんどん手を挙げて、私がやります、やりますというようなことで、そういうような意味では、一つのあれかなと思います。環境、せっかく環境活動推進会議ということで委員として公募されたのですから、実りあるような活動にひとつなるようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-037"},{"speaker":"嶋委員","kind":"質問","question":"その小冊子がこの四、五回の中で、もうできてしまうのか、それかもう少し時間と内容をかけてつくられていかれるのか、今後のこの会議がこれからスタートする、この方たちがもっといろいろなことで発信、情報提供、ある程度勉強された方も参加されるというお話がありましたので、今後のこの方たちの１年先の計画的なものというのがあれば教えてもらいたいと思います。","respondent":"金井環境課長","answer":"それで、それは委員の環境計画を説明する中で、まず私どもが先にこういうテーマをお示ししないとなかなかどうやって取り組んでいいかわからないと思いますので、例としてこういった取り組みを今２点挙げておりますが、そういう議論をする中で。","voiceIndex":103,"id":"exchange-038"},{"speaker":"嶋委員","kind":"質問・要望","question":"１０年間というスパンでやっていくということなので、中身の濃いすばらしいものができていく、そういう意味では、区内企業の３社というのは、ちょっとそういうところが少な過ぎているのかなという、品川区内にはもう東京電力、東京ガスはいつもお目にかかっている方たちばかりなので、もっともっと１０年間のスパンでするならば、大きな区内の企業をたくさん入れていただいて。","respondent":"金井環境課長","answer":"委員ご指摘のとおりです。こういう直接的な委員として入っていただいているのは現在３社ですけれども、あまりたくさん増やしても身動きができないです。環境に対する企業活動というのは、非常に大事です。そういう意味では、東京商工会議所品川支部というのが入っております。","voiceIndex":105,"id":"exchange-039"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ環境リサイクルフェアなどをたくさん催して、区内の企業がいっぱい努力しているところがあると思います。そういうところの方たちの頑張っているところも見せていただいて、ぜひ大成功させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2372#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":40253,"voices":122}}]);
